const S="https://app.incusgrid.com",P="https://play.google.com/store/apps/details?id=com.incusgrid.app",e="https://blog.incusgrid.com",M="https://www.instagram.com/incusgrid/",E="https://www.facebook.com/incusgrid/",G=["Plan the season.","Sail the day."],o={path:"/",htmlLang:"en",ogLocale:"en_GB",meta:{title:"IncusGrid · Local knowledge and weather routing for sailors",description:"Sailing routes and boat stays from real passages, years of wind, wave and lightning data, plus the 10-day forecast and weather routing for your boat. Plan your season and your passage on one map.",keywords:"sailing routes, cruising routes, weather routing, passage planning, route planning, departure planning, sailing forecast, wind forecast, boat polar, boat stays, anchorage, marina, wintering, wind statistics, sea state, waves, lightning, thunderstorm, thunderstorm risk, lightning density, terrain shielding, sailing planning, yacht, cruising, seabed, seabed map, seagrass, Posidonia, sand for anchoring"},nav:{routes:"Routes",passages:"Passages",stays:"Boat stays",weather:"Weather",thunderstorms:"Lightning",blog:"Blog",openApp:"Open the map"},hero:{position:"Sailing intelligence",lead:"IncusGrid turns years of data into the local knowledge every crew needs before casting off: real boat movements, wind, waves and lightning on one map. Plus the forecast for the next 10 days and a passage planner that routes your boat through the forecast wind, hour by hour, with gusts and waves along the way.",ctaApp:"Open the map",ctaAndroid:"Android app",heroAlt:"Sailing routes across the Caribbean Sea, from Hispaniola to the Lesser Antilles and the coast of South America, drawn from real passages of cruising boats.",heroCaption:"Sailing routes, Caribbean Sea · all months",notes:[{label:"Boats",value:"Thousands"},{label:"Movements",value:"Millions"},{label:"Lightning strikes",value:"Billions"},{label:"Forecast",value:"10 days"},{label:"Coverage",value:"Worldwide"}]},contrast:{kicker:"Season and forecast",title:"The season tells you which month. The forecast tells you which day.",text:"Which passage do crews take in June? Where do boats spend the winter? Which month brings the Meltemi, and which wintering harbour sees fewer thunderstorms in November? Answers that only show up when you look at many years at once. As your departure gets closer, the passage planner works out on the 10-day forecast when to leave and when you arrive."},chapters:[{id:"routes",number:"01",kicker:"Sailing routes",title:"Plan crossings on the experience of thousands of crews.",text:"Thousands of real passages show when a crossing makes sense, in which direction, and where crews set off and arrive. The prevailing winds, good places to wait for a weather window and a safe landfall after a night at sea are already built in. From Sicily to the Ionian Islands, for example, most boats head east in May and June and sail back in September.",points:["Popularity per month and direction","The most popular routes in your current map view","Share a route with your crew"],image:"route-detail",alt:"The route from Sicily to the Ionian Islands selected, with how popular it is in each month and direction.",coords:"38°12′N · 017°30′E",caption:"Sicily → Ionian Islands, by month and direction"},{id:"route-wind",number:"02",kicker:"Wind along the route",title:"Know the wind before you cast off.",text:"Every route shows the wind you can expect on it, month by month: where it comes from, how strong it blows, how much of the passage you sail upwind, on a beam reach or downwind, and how often the sea stays calm. From Sicily to the Ionian Islands in May: wind from the northwest, Bft 3, more than half of the way downwind.",points:["Prevailing wind and Beaufort force for every month","Upwind, beam reach or downwind on the route’s course","Sea state along the route"],image:"route-wind",alt:"The route card for Sicily to the Ionian Islands: prevailing wind, Beaufort force, wind strength, point of sail and sea state for every month, with May selected.",coords:"",caption:"Sicily → Ionian Islands, wind in May",card:!0},{id:"passage",number:"03",kicker:"Passage planner · weather routing",title:"Know when you arrive before you cast off.",text:"Set a start and a destination, pick your boat, and the passage planner finds a fast route through the forecast wind of the next 10 days, hour by hour, with gusts and waves along the way. From Leros to Rhodes, 86 nautical miles, leaving on Wednesday at 20:00: one night downwind with no more than 15 knots of wind, no motoring, arriving on Thursday just before eleven.",points:["Arrival, strongest wind, gusts and waves, hours under sail and under motor","For your boat: type and size, or your own polar","Underway, your position next to the plan, and the rest of the route recalculated"],image:"passage",alt:"The passage planner with the route from Leros to Rhodes on the wind forecast: waypoints with times, the boat south of Kos at night, and beside it the arrival, strongest wind, and hours sailing and motoring.",coords:"36°48′N · 027°50′E",caption:"Leros → Rhodes, leaving Wednesday 20:00 · forecast of 31 October"},{id:"departures",number:"04",kicker:"Compare departures",title:"The right day to cast off.",text:"The planner calculates the same passage for up to twelve departures, six hours apart, and lines up arrival, duration, strongest wind and time under motor. Leaving Leros on Wednesday morning, you reach Rhodes at midnight; leaving on Wednesday evening, the next morning. The star marks the departure with the least time under motor and upwind.",points:["Up to twelve departures, every six hours","Tap a row to see its route","Save a passage or share it with your crew, always on the latest forecast"],image:"departures",alt:"The departures table for Leros to Rhodes, every six hours from Wednesday 08:00: arrival, duration, strongest wind and hours under motor, with the best departure, Thursday at 14:00, starred.",coords:"",caption:"Leros → Rhodes, departures from Wednesday 08:00",card:!0},{id:"stays",number:"05",kicker:"Boat stays",title:"Where other boats stay.",text:"Where do crews leave their boat for two months in summer, and where do they spend the winter? Boat stays show the harbours and anchorages where boats paused — from a few days to more than six months, by season.",points:["Filter by length of stay","See in which months boats stay at a place","Spot popular wintering harbours"],image:"stay-detail",alt:"Preveza: typical length of stay and the months in which boats stay there.",coords:"38°57′N · 020°45′E",caption:"Preveza, length of stay and season"},{id:"hotspots",number:"06",kicker:"Hotspots",title:"Find the quieter anchorage.",text:"Where do boats crowd in August, and where is there still room? Hotspots shows how busy each sailing area is, month by month. The Ionian and the Saronic Gulf glow, while Andros, a day’s sail from Athens, stays calm.",points:["From quiet to crowded","Every month of the year","Busiest and quietest months at any point"],image:"hotspots",alt:"How busy Greek sailing areas are in August: crowded around the Ionian Islands and the Saronic Gulf, quiet off Andros, with the point inspector open.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Greece, August"},{id:"spot",number:"07",kicker:"Spot report",title:"Everything about one place, in one card.",text:"Press and hold any place on the map, or right-click it, and the spot report brings it all together for the month you choose: wind and sea state, thunderstorms, how well the terrain shields it, and the boat stays and routes nearby. Gaios on Paxos in September: calm or light wind most of the time, a calm or slight sea, and thunderstorms on about one day in six. The month strip shows November as the month with the most thunderstorms.",points:["Wind, sea state and thunderstorms for one place and month","Boat stays and routes within 5 nautical miles","Every month rated at a glance, as a link for your crew"],image:"spot",alt:"The spot report for Gaios on Paxos in September: wind and sea state, thunderstorms, terrain shielding, boat stays and routes nearby, and every month rated at a glance.",coords:"",caption:"Gaios, Paxos, September",card:!0},{id:"wind",number:"08",kicker:"Wind",title:"How much northerly wind should you expect?",text:"Pick a direction and a month: in July the central Aegean turns deep blue. That’s the Meltemi. Tap a spot near Mykonos and you see it blow from the north in 60% of all July hours or more.",points:["Strength and direction for every month","Wind by time of day","Tap any point for its numbers"],image:"wind",alt:"How often the wind blows from the north in the Aegean Sea in July, with the point inspector open near Mykonos.",coords:"37°36′N · 025°00′E",caption:"Wind from the north, Aegean Sea, July"},{id:"waves",number:"09",kicker:"Waves",title:"Know the sea state before you go.",text:"How many days per month bring waves of 2.5 m or more? In January the reach of the Mistral across the Gulf of Lion stands out clearly.",points:["From calm to very rough seas","Swell and short, steep seas","Every month of the year"],image:"waves",alt:"Days with rough seas in the western Mediterranean in January.",coords:"41°00′N · 005°00′E",caption:"Rough days, western Mediterranean, January"},{id:"risk",number:"10",kicker:"Thunderstorm Risk",title:"Which harbour sees fewer thunderstorms?",text:"Thunderstorm Risk brings together how often thunderstorms occur, how violent they are and how mountains, headlands and open sea shape them, for every month and down to single bays. Tap one place, then another, and see how much more or less risk the second one has. Preveza and Messolonghi are both popular for wintering: in November, Messolonghi has 27% less thunderstorm risk.",points:["Thunderstorm days, lightning density and terrain in one value","Differences down to single bays","Tap two places to compare them"],image:"risk",alt:"Thunderstorm Risk in the Ionian Sea in November: Preveza tapped first, then Messolonghi, with the point inspector showing 27% less risk.",coords:"38°40′N · 021°10′E",caption:"Preveza vs. Messolonghi, November",markers:[{x:34.09,y:27.12,text:"Preveza, tapped first: risk value 50 in November.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, 47 nm away: 27% less thunderstorm risk.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Lightning data",title:"How often, how violent, how likely.",text:"Behind the risk are three layers you can open on their own, on the same scale in every month. In September the Mediterranean shows why you need all three: thunderstorms are most frequent along the Adriatic and Ionian coasts, the lightning is densest over the sea between Italy and Greece, and conditions that favour storms reach far into the south.",points:["Thunderstorm Days: how often storms occur, 2013–2025","Lightning Density: how violent they are","Thunderstorm Potential: where they can build, 1994–2023"],image:"days",alt:"Thunderstorm Days in the Mediterranean in September.",coords:"40°00′N · 015°00′E",caption:"Thunderstorm Days, Mediterranean, September",panels:[{label:"Thunderstorm Days",image:"days",alt:"Thunderstorm Days in the Mediterranean in September.",caption:"Thunderstorm Days, Mediterranean, September"},{label:"Lightning Density",image:"density",alt:"Lightning Density in the Mediterranean in September.",caption:"Lightning Density, Mediterranean, September"},{label:"Thunderstorm Potential",image:"potential",alt:"Thunderstorm Potential in the Mediterranean in September.",caption:"Thunderstorm Potential, Mediterranean, September"}]},{id:"terrain",number:"12",kicker:"Terrain Exposure",title:"Same bay, different shielding.",text:"Thunderstorm Risk tells you which bay. Terrain Exposure tells you which side of it: surrounding hills can shield an anchorage from lightning, and the layer shows how well the terrain protects each part of a bay, so you can pick the better spot before you drop anchor.",points:["Compare spots within one bay","Detailed 30 m elevation data"],image:"terrain",alt:"Terrain Exposure in Komiža Bay on Vis, Croatia.",coords:"43°02′N · 016°05′E",caption:"Komiža Bay, Vis",markers:[{x:56.9,y:57.69,text:"Little shielding from surrounding terrain.",color:"#762a83"},{x:53.84,y:26.35,text:"Some shielding from surrounding terrain.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Stronger shielding from surrounding terrain.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Seabed",title:"Sand or seagrass?",text:"Before you drop the anchor: the Seabed layer shows sand, mud, rock, seagrass and coral along the coast, from the Mediterranean to the tropics. In the Bay of Palma a wide band of seagrass runs along the shore, and the sand lies further out. Anchoring on Posidonia is banned in more and more places, so it pays to know before you arrive.",points:["Sand, mud, rock, seagrass and coral","Europe and shallow tropical coasts","Open to everyone"],image:"seabed",alt:"The seabed in the Bay of Palma, Mallorca: a wide band of seagrass along the shore, sand further out, with the point inspector showing seagrass.",coords:"39°30′N · 002°37′E",caption:"Seabed, Bay of Palma"}],story:{kicker:"Our story",title:"Born from a close call.",text:"In October 2024, our family was sailing the Ionian Sea when lightning struck right next to our boat. That moment raised a simple question: are we safer here, or on the other side of the bay? IncusGrid started as the answer — and grew into a map of everything we wished we had known before that season.",more:"Read the full story",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Greece",note:"Where the idea was born"},fromBlog:{kicker:"From the blog",title:"Data stories from the water.",all:"All posts",note:""},devices:{kicker:"Web & Android",title:"On deck or at the chart table.",text:"Use IncusGrid in any browser or install the Android app. Search for your sailing area and explore on phone, tablet or laptop.",points:["No installation needed in the browser","Android app on Google Play","Available in 19 languages"],web:"Open in the browser",android:"Get it on Google Play",phoneAlt:"IncusGrid Android app showing boat stays around the Ionian Islands."},final:{title:"Plan your next season. And your next passage.",text:"Routes, boat stays, wind, waves and lightning from many years of real data, plus the 10-day forecast and the passage planner — on one map.",cta:"Open the map"},disclaimerLabel:"Caution",disclaimer:"IncusGrid is made for planning and is not a navigation aid. Routes are drawn schematically, and boat stays are derived from pauses in boat reports, not confirmed berths. The passage planner uses a simple polar, without currents or the effect of waves on boat speed, and does not route you into the harbour. Always check current forecasts, official charts and local conditions before you go to sea.",footer:{blog:"Blog",legal:"Legal Notice",privacy:"Privacy Policy",terms:"Terms of Service",cookies:"Cookie Settings",support:"Support",madeWith:"Made with",made:"in Portugal",englishOnly:""}},s={path:"/de",htmlLang:"de",ogLocale:"de_DE",meta:{title:"IncusGrid · Revierwissen und Wetterrouting für Segler",description:"Segelrouten und Bootspausen aus echten Passagen, Jahre an Wind-, Wellen- und Blitzdaten, dazu die 10-Tage-Vorhersage und Wetterrouting für dein Boot. Plane Saison und Passage auf einer Karte.",keywords:"Segelrouten, Törnplanung, Törnplaner, Wetterrouting, Passagenplanung, Routenplanung, Abfahrtsplanung, Wettervorhersage, Windvorhersage, Polare, Ankerplatz, Marina, Winterlager, Windstatistik, Seegang, Wellen, Blitze, Gewitter, Gewitterrisiko, Blitzdichte, Segeln, Yacht, Blauwassersegeln, Meeresboden, Seegras, Posidonia, Ankergrund"},nav:{routes:"Routen",passages:"Törnplaner",stays:"Bootspausen",weather:"Wetter",thunderstorms:"Blitze",blog:"Blog",openApp:"Karte öffnen"},hero:{position:"Sailing intelligence",lead:"IncusGrid macht aus Jahren an Daten das Revierwissen, das jede Crew vor dem Ablegen braucht: echte Bootsbewegungen, Wind, Wellen und Blitze auf einer Karte. Dazu die Vorhersage für die nächsten 10 Tage und ein Törnplaner, der deine Route Stunde für Stunde durch den vorhergesagten Wind rechnet, mit Böen und Wellen auf dem Weg.",ctaApp:"Karte öffnen",ctaAndroid:"Android-App",heroAlt:"Segelrouten in der Karibik, von Hispaniola über die Kleinen Antillen bis zur Küste Südamerikas, gezeichnet aus echten Passagen von Fahrtenyachten.",heroCaption:"Segelrouten, Karibisches Meer · alle Monate",notes:[{label:"Boote",value:"Tausende"},{label:"Bewegungen",value:"Millionen"},{label:"Blitzeinschläge",value:"Milliarden"},{label:"Vorhersage",value:"10 Tage"},{label:"Abdeckung",value:"Weltweit"}]},contrast:{kicker:"Saison und Vorhersage",title:"Die Saison sagt dir, in welchem Monat. Die Vorhersage sagt dir, an welchem Tag.",text:"Welche Passage nehmen Crews im Juni? Wo überwintern Boote? Welcher Monat bringt den Meltemi, und in welchem Winterhafen gibt es im November weniger Gewitter? Antworten, die erst sichtbar werden, wenn man viele Jahre auf einmal betrachtet. Rückt die Abfahrt näher, rechnet der Törnplaner auf der 10-Tage-Vorhersage, wann du ablegst und wann du ankommst."},chapters:[{id:"routes",number:"01",kicker:"Segelrouten",title:"Plane Überfahrten mit der Erfahrung tausender Crews.",text:"Tausende echte Passagen zeigen, wann eine Überfahrt sinnvoll ist, in welche Richtung, und wo Crews ablegen und ankommen. Die vorherrschenden Winde, gute Orte, um auf ein Wetterfenster zu warten, und ein sicherer Landfall nach einer Nacht auf See stecken schon darin. Von Sizilien zu den Ionischen Inseln zum Beispiel fahren die meisten Boote im Mai und Juni nach Osten und im September zurück.",points:["Beliebtheit je Monat und Richtung","Die beliebtesten Routen im aktuellen Kartenausschnitt","Teile eine Route mit deiner Crew"],image:"route-detail",alt:"Die Route von Sizilien zu den Ionischen Inseln ausgewählt, mit ihrer Beliebtheit je Monat und Richtung.",coords:"38°12′N · 017°30′E",caption:"Sizilien → Ionische Inseln, nach Monat und Richtung"},{id:"route-wind",number:"02",kicker:"Wind entlang der Route",title:"Kenne den Wind, bevor du ablegst.",text:"Jede Route zeigt den Wind, den du dort erwarten kannst, Monat für Monat: woher er kommt, wie stark er weht, wie viel der Passage du am Wind, mit halbem Wind oder raumschots segelst und wie oft die See ruhig bleibt. Von Sizilien zu den Ionischen Inseln im Mai: Wind aus Nordwest, 3 Bft, mehr als die Hälfte des Weges raumschots.",points:["Vorherrschender Wind und Windstärke in Beaufort für jeden Monat","Am Wind, halber Wind oder raumschots auf dem Kurs der Route","Seegang entlang der Route"],image:"route-wind",alt:"Die Routenkarte von Sizilien zu den Ionischen Inseln: vorherrschender Wind, Windstärke in Beaufort, Stärke, Kurs und Seegang für jeden Monat, mit ausgewähltem Mai.",coords:"",caption:"Sizilien → Ionische Inseln, Wind im Mai",card:!0},{id:"passage",number:"03",kicker:"Törnplaner · Wetterrouting",title:"Wann du ankommst, bevor du ablegst.",text:"Setze Start und Ziel, wähle dein Boot, und der Törnplaner sucht eine schnelle Route durch den vorhergesagten Wind der nächsten 10 Tage, Stunde für Stunde, mit Böen und Wellen entlang des Weges. Von Leros nach Rhodos, 86 Seemeilen, Abfahrt Mittwoch um 20 Uhr: eine Nacht raumschots mit höchstens 15 Knoten Wind, ohne Motor, Ankunft am Donnerstag kurz vor elf.",points:["Ankunft, stärkster Wind, Böen und Wellen, Stunden unter Segel und unter Motor","Für dein Boot: Bootstyp und Größe oder deine eigene Polare","Unterwegs deine Position neben dem Plan, der Rest der Route neu berechnet"],image:"passage",alt:"Der Törnplaner mit der Route von Leros nach Rhodos auf der Windvorhersage: Wegpunkte mit Uhrzeiten, das Boot südlich von Kos in der Nacht, daneben Ankunft, stärkster Wind, Segel- und Motorstunden.",coords:"36°48′N · 027°50′E",caption:"Leros → Rhodos, Abfahrt Mittwoch 20:00 · Vorhersage vom 31. Oktober"},{id:"departures",number:"04",kicker:"Abfahrten vergleichen",title:"Der richtige Tag zum Ablegen.",text:"Der Planer rechnet dieselbe Passage für bis zu zwölf Abfahrten im Abstand von sechs Stunden und stellt Ankunft, Dauer, stärksten Wind und Zeit unter Motor nebeneinander. Von Leros am Mittwochmorgen kommst du um Mitternacht in Rhodos an, am Mittwochabend am nächsten Vormittag. Der Stern markiert die Abfahrt mit der wenigsten Zeit unter Motor und am Wind.",points:["Bis zu zwölf Abfahrten, alle sechs Stunden","Eine Zeile antippen, um ihre Route zu sehen","Passage speichern oder mit der Crew teilen, immer auf der neuesten Vorhersage"],image:"departures",alt:"Die Abfahrtstabelle für Leros nach Rhodos, alle sechs Stunden ab Mittwoch 08:00: Ankunft, Dauer, stärkster Wind und Motorstunden, die beste Abfahrt am Donnerstag um 14:00 mit einem Stern markiert.",coords:"",caption:"Leros → Rhodos, Abfahrten ab Mittwoch 08:00",card:!0},{id:"stays",number:"05",kicker:"Bootspausen",title:"Wo andere Boote liegen.",text:"Wo lassen Crews ihr Boot im Sommer für zwei Monate liegen, und wo verbringen sie den Winter? Bootspausen zeigen die Häfen und Ankerplätze, an denen Boote pausiert haben — von wenigen Tagen bis zu mehr als sechs Monaten, nach Saison.",points:["Nach Liegedauer filtern","Sehen, in welchen Monaten Boote an einem Ort liegen","Beliebte Winterhäfen entdecken"],image:"stay-detail",alt:"Preveza: typische Liegedauer und die Monate, in denen Boote dort liegen.",coords:"38°57′N · 020°45′E",caption:"Preveza, Liegedauer und Saison"},{id:"hotspots",number:"06",kicker:"Hotspots",title:"Das ruhigere Plätzchen finden.",text:"Wo drängen sich im August die Boote, und wo ist noch Platz? Hotspots zeigt Monat für Monat, wie belebt ein Revier ist. Ionisches Meer und Saronischer Golf leuchten, Andros dagegen, eine Tagesetappe von Athen entfernt, bleibt ruhig.",points:["Von ruhig bis überlaufen","Jeder Monat des Jahres","Belebteste und ruhigste Monate an jedem Punkt"],image:"hotspots",alt:"Wie belebt die griechischen Reviere im August sind: voll um die Ionischen Inseln und im Saronischen Golf, ruhig vor Andros, mit geöffnetem Ortsinspektor.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Griechenland, August"},{id:"spot",number:"07",kicker:"Steckbrief",title:"Alles über einen Ort, auf einen Blick.",text:"Halte einen Ort auf der Karte gedrückt oder klicke ihn mit der rechten Maustaste an: Der Steckbrief fasst für den gewählten Monat alles zusammen, Wind und Seegang, Gewitter, den Schutz durch das Gelände und die Bootspausen und Routen in der Nähe. Gaios auf Paxos im September: meist kaum oder wenig Wind, ruhige bis leicht bewegte See und an etwa jedem sechsten Tag Gewitter. Die Monatsleiste zeigt auf einen Blick, dass der November die meisten Gewitter bringt.",points:["Wind, Seegang und Gewitter für einen Ort und Monat","Bootspausen und Routen im Umkreis von 5 Seemeilen","Jeder Monat auf einen Blick bewertet, als Link für deine Crew"],image:"spot",alt:"Der Steckbrief für Gaios auf Paxos im September: Wind und Seegang, Gewitter, Schutz durch das Gelände, Bootspausen und Routen in der Nähe und jeder Monat auf einen Blick bewertet.",coords:"",caption:"Gaios, Paxos, September",card:!0},{id:"wind",number:"08",kicker:"Wind",title:"Wie viel Nordwind erwartet dich?",text:"Wähle Richtung und Monat: Im Juli färbt sich die zentrale Ägäis tiefblau. Das ist der Meltemi. Tippe auf einen Punkt bei Mykonos, und du siehst: Im Juli kommt der Wind in 60 % aller Stunden oder mehr aus Norden.",points:["Stärke und Richtung für jeden Monat","Wind nach Tageszeit","Tippe auf einen Punkt für seine Werte"],image:"wind",alt:"Wie oft der Wind im Juli in der Ägäis aus Norden weht, mit geöffnetem Punkt-Inspektor bei Mykonos.",coords:"37°36′N · 025°00′E",caption:"Wind aus Norden, Ägäis, Juli"},{id:"waves",number:"09",kicker:"Wellen",title:"Kenne den Seegang, bevor du losfährst.",text:"Wie viele Tage im Monat bringen Wellen ab 2,5 m? Im Januar sieht man deutlich, wie weit der Mistral über den Golfe du Lion hinausreicht.",points:["Von ruhiger bis sehr rauer See","Dünung und kurze, steile See","Jeder Monat des Jahres"],image:"waves",alt:"Tage mit rauer See im westlichen Mittelmeer im Januar.",coords:"41°00′N · 005°00′E",caption:"Raue Tage, westliches Mittelmeer, Januar"},{id:"risk",number:"10",kicker:"Gewitterrisiko",title:"In welchem Hafen gibt es weniger Gewitter?",text:"Das Gewitterrisiko verbindet, wie oft Gewitter auftreten, wie heftig sie sind und wie Berge, Landzungen und offenes Meer sie formen — für jeden Monat und bis hinunter zu einzelnen Buchten. Tippe auf einen Ort, dann auf einen zweiten, und du siehst, wie viel mehr oder weniger Risiko der zweite hat. Preveza und Messolonghi sind beide beliebt zum Überwintern: Im November hat Messolonghi 27 % weniger Gewitterrisiko.",points:["Gewittertage, Blitzdichte und Gelände in einem Wert","Unterschiede bis hinunter zu einzelnen Buchten","Tippe auf zwei Orte, um sie zu vergleichen"],image:"risk",alt:"Gewitterrisiko im Ionischen Meer im November: erst Preveza angetippt, dann Messolonghi, der Punktinspektor zeigt 27 % weniger Risiko.",coords:"38°40′N · 021°10′E",caption:"Preveza vs. Messolonghi, November",markers:[{x:34.09,y:27.12,text:"Preveza, zuerst angetippt: Risikowert 50 im November.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, 47 sm entfernt: 27 % weniger Gewitterrisiko.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Blitzdaten",title:"Wie oft, wie heftig, wie wahrscheinlich.",text:"Hinter dem Risiko stehen drei Ebenen, die du auch einzeln öffnen kannst, in jedem Monat auf derselben Skala. Im September zeigt das Mittelmeer, warum es alle drei braucht: Gewitter sind entlang der Adria- und der ionischen Küsten am häufigsten, die Blitze am dichtesten über dem Meer zwischen Italien und Griechenland, und gewitterbegünstigende Bedingungen reichen weit in den Süden.",points:["Gewittertage: wie oft Gewitter auftreten, 2013–2025","Blitzdichte: wie heftig sie sind","Gewitterpotenzial: wo sie entstehen können, 1994–2023"],image:"days",alt:"Gewittertage im Mittelmeer im September.",coords:"40°00′N · 015°00′E",caption:"Gewittertage, Mittelmeer, September",panels:[{label:"Gewittertage",image:"days",alt:"Gewittertage im Mittelmeer im September.",caption:"Gewittertage, Mittelmeer, September"},{label:"Blitzdichte",image:"density",alt:"Blitzdichte im Mittelmeer im September.",caption:"Blitzdichte, Mittelmeer, September"},{label:"Gewitterpotenzial",image:"potential",alt:"Gewitterpotenzial im Mittelmeer im September.",caption:"Gewitterpotenzial, Mittelmeer, September"}]},{id:"terrain",number:"12",kicker:"Geländeexposition",title:"Gleiche Bucht, andere Abschirmung.",text:"Das Gewitterrisiko sagt dir, welche Bucht. Die Geländeexposition sagt dir, welche Seite davon: Umliegende Hügel können einen Ankerplatz vor Blitzen abschirmen, und die Ebene zeigt, wie gut das Gelände jeden Teil einer Bucht schützt — damit du die bessere Stelle wählst, bevor der Anker fällt.",points:["Vergleiche Stellen innerhalb einer Bucht","Detaillierte Höhendaten mit 30 m Auflösung"],image:"terrain",alt:"Geländeexposition in der Bucht von Komiža auf Vis, Kroatien.",coords:"43°02′N · 016°05′E",caption:"Bucht von Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Geringe Abschirmung durch das umliegende Gelände.",color:"#762a83"},{x:53.84,y:26.35,text:"Etwas Abschirmung durch das umliegende Gelände.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Stärkere Abschirmung durch das umliegende Gelände.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Meeresboden",title:"Sand oder Seegras?",text:"Bevor der Anker fällt: Die Ebene Meeresboden zeigt Sand, Schlamm, Fels, Seegras und Korallen entlang der Küste, vom Mittelmeer bis in die Tropen. In der Bucht von Palma zieht sich ein breites Band aus Seegras an der Küste entlang, der Sand liegt weiter draußen. Ankern auf Posidonia ist an immer mehr Orten verboten, also lohnt es sich, das vor der Ankunft zu wissen.",points:["Sand, Schlamm, Fels, Seegras und Korallen","Europa und flache tropische Küsten","Für alle offen"],image:"seabed",alt:"Der Meeresboden in der Bucht von Palma, Mallorca: ein breites Band aus Seegras entlang der Küste, weiter draußen Sand, der Punktinspektor zeigt Seegras.",coords:"39°30′N · 002°37′E",caption:"Meeresboden, Bucht von Palma"}],story:{kicker:"Unsere Geschichte",title:"Entstanden aus einem Schreckmoment.",text:"Im Oktober 2024 war unsere Familie im Ionischen Meer unterwegs, als direkt neben unserem Boot ein Blitz einschlug. Danach stand eine einfache Frage im Raum: Sind wir hier sicherer oder auf der anderen Seite der Bucht? IncusGrid begann als Antwort darauf — und wurde zu einer Karte mit allem, was wir vor dieser Saison gern gewusst hätten.",more:"Die ganze Geschichte lesen (Englisch)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Griechenland",note:"Wo die Idee entstand"},fromBlog:{kicker:"Aus dem Blog",title:"Datengeschichten vom Wasser.",all:"Alle Beiträge",note:"Beiträge auf Englisch."},devices:{kicker:"Web & Android",title:"An Deck oder am Kartentisch.",text:"Nutze IncusGrid in jedem Browser oder installiere die Android-App. Suche dein Revier und erkunde es auf Handy, Tablet oder Laptop.",points:["Im Browser ohne Installation","Android-App bei Google Play","In 19 Sprachen verfügbar"],web:"Im Browser öffnen",android:"Bei Google Play laden",phoneAlt:"IncusGrid-Android-App mit Bootspausen rund um die Ionischen Inseln."},final:{title:"Plane deine nächste Saison. Und deine nächste Passage.",text:"Routen, Bootspausen, Wind, Wellen und Blitze aus vielen Jahren echter Daten, dazu die 10-Tage-Vorhersage und der Törnplaner — auf einer Karte.",cta:"Karte öffnen"},disclaimerLabel:"Hinweis",disclaimer:"IncusGrid ist für die Planung gemacht und keine Navigationshilfe. Routen sind schematisch gezeichnet, und Bootspausen werden aus Pausen in Bootsmeldungen abgeleitet, nicht aus bestätigten Liegeplätzen. Der Törnplaner rechnet mit einer einfachen Polare, ohne Strömung und ohne den Einfluss der Wellen auf die Bootsgeschwindigkeit, und führt dich nicht bis in den Hafen. Prüfe vor dem Auslaufen immer aktuelle Vorhersagen, amtliche Seekarten und die Bedingungen vor Ort.",footer:{blog:"Blog",legal:"Impressum",privacy:"Datenschutz",terms:"Nutzungsbedingungen",cookies:"Cookie-Einstellungen",support:"Support",madeWith:"Mit",made:"gemacht in Portugal",englishOnly:"Rechtliche Seiten auf Englisch."}},l={path:"/fr",htmlLang:"fr",ogLocale:"fr_FR",meta:{title:"IncusGrid · Connaissance locale et routage météo pour les navigateurs",description:"Routes de navigation et pauses de bateaux issues de vraies traversées, des années de données de vent, de vagues et de foudre, plus les prévisions à 10 jours et le routage météo pour votre bateau. Préparez votre saison et votre traversée sur une seule carte.",keywords:"routage météo, préparation de traversée, planification de route, choix de l’heure de départ, météo marine, prévisions de vent, polaires bateau, routes de navigation, navigation hauturière, croisière à la voile, mouillage, port, hivernage, statistiques de vent, état de la mer, vagues, houle, foudre, orages, risque d’orage, densité de foudre, préparer une navigation, voilier, grand voyage, fonds marins, herbier, posidonie, fond de mouillage"},nav:{routes:"Routes",passages:"Traversées",stays:"Pauses des bateaux",weather:"Météo",thunderstorms:"Foudre",blog:"Blog",openApp:"Ouvrir la carte"},hero:{position:"Sailing intelligence",lead:"IncusGrid transforme des années de données en connaissance locale dont chaque équipage a besoin avant de larguer les amarres : de vrais mouvements de bateaux, le vent, les vagues et la foudre sur une seule carte. Avec en plus les prévisions des 10 prochains jours et un planificateur de traversée qui route votre bateau dans le vent prévu, heure par heure, avec les rafales et les vagues tout au long du trajet.",ctaApp:"Ouvrir la carte",ctaAndroid:"Appli Android",heroAlt:"Routes de navigation à travers la mer des Caraïbes, d’Hispaniola aux Petites Antilles et jusqu’à la côte de l’Amérique du Sud, tracées à partir de vraies traversées de voiliers de croisière.",heroCaption:"Routes de navigation, mer des Caraïbes · tous les mois",notes:[{label:"Bateaux",value:"Des milliers"},{label:"Mouvements",value:"Des millions"},{label:"Impacts de foudre",value:"Des milliards"},{label:"Prévisions",value:"10 jours"},{label:"Couverture",value:"Mondiale"}]},contrast:{kicker:"Saison et prévisions",title:"La saison vous dit quel mois. La prévision vous dit quel jour.",text:"Quelle traversée les équipages font-ils en juin ? Où les bateaux passent-ils l’hiver ? Quel mois amène le meltem, et quel port d’hivernage connaît le moins d’orages en novembre ? Des réponses qui n’apparaissent qu’en regardant de nombreuses années à la fois. À l’approche du départ, le planificateur de traversée calcule sur les prévisions à 10 jours quand partir et quand vous arriverez."},chapters:[{id:"routes",number:"01",kicker:"Routes de navigation",title:"Planifiez vos traversées avec l’expérience de milliers d’équipages.",text:"Des milliers de vraies traversées montrent quand une traversée a du sens, dans quel sens, et d’où les équipages partent et où ils arrivent. Les vents dominants, les bons endroits pour attendre une fenêtre météo et un atterrissage sûr après une nuit en mer y sont déjà intégrés. De la Sicile aux îles Ioniennes, par exemple, la plupart des bateaux font route vers l’est en mai et juin et reviennent en septembre.",points:["Popularité par mois et par sens","Les routes les plus populaires dans votre vue actuelle de la carte","Partagez une route avec votre équipage"],image:"route-detail",alt:"La route de la Sicile aux îles Ioniennes sélectionnée, avec sa popularité pour chaque mois et chaque sens.",coords:"38°12′N · 017°30′E",caption:"Sicile → îles Ioniennes, par mois et par sens"},{id:"route-wind",number:"02",kicker:"Le vent sur la route",title:"Connaissez le vent avant de larguer les amarres.",text:"Chaque route indique le vent à prévoir, mois par mois : d’où il vient, quelle est sa force, quelle part du trajet se fait au près, au travers ou au portant, et à quelle fréquence la mer reste calme. De la Sicile aux îles Ioniennes en mai : vent de nord-ouest, force 3 Beaufort, plus de la moitié du trajet au portant.",points:["Vent dominant et force Beaufort pour chaque mois","Au près, au travers ou au portant sur le cap de la route","État de la mer le long de la route"],image:"route-wind",alt:"La fiche de la route de la Sicile aux îles Ioniennes : vent dominant, force Beaufort, force du vent, allure et état de la mer pour chaque mois, mai sélectionné.",coords:"",caption:"Sicile → îles Ioniennes, le vent en mai",card:!0},{id:"passage",number:"03",kicker:"Planificateur de traversée · routage météo",title:"Sachez quand vous arriverez avant de larguer les amarres.",text:"Indiquez un départ et une destination, choisissez votre bateau, et le planificateur de traversée trouve une route rapide dans le vent prévu des 10 prochains jours, heure par heure, avec les rafales et les vagues tout au long du trajet. De Leros à Rhodes, 86 milles nautiques, départ le mercredi à 20 h : une nuit au portant avec 15 nœuds de vent au maximum, sans moteur, arrivée le jeudi peu avant onze heures.",points:["Arrivée, vent le plus fort, rafales et vagues, heures à la voile et au moteur","Pour votre bateau : type et taille, ou votre propre polaire","En route, votre position comparée au plan, et le reste de la route recalculé"],image:"passage",alt:"Le planificateur de traversée avec la route de Leros à Rhodes sur la prévision de vent : points de route avec horaires, le bateau au sud de Kos pendant la nuit, et à côté l’arrivée, le vent le plus fort et les heures à la voile et au moteur.",coords:"36°48′N · 027°50′E",caption:"Leros → Rhodes, départ mercredi 20 h · prévision du 31 octobre"},{id:"departures",number:"04",kicker:"Comparer les départs",title:"Le bon jour pour larguer les amarres.",text:"Le planificateur calcule la même traversée pour un maximum de douze départs, espacés de six heures, et compare l’arrivée, la durée, le vent le plus fort et le temps au moteur. En quittant Leros le mercredi matin, vous arrivez à Rhodes à minuit ; en partant le mercredi soir, le lendemain matin. L’étoile signale le départ avec le moins de moteur et de près.",points:["Jusqu’à douze départs, toutes les six heures","Touchez une ligne pour voir sa route","Enregistrez une traversée ou partagez-la avec votre équipage, toujours sur la dernière prévision"],image:"departures",alt:"Le tableau des départs de Leros à Rhodes, toutes les six heures à partir du mercredi 8 h : arrivée, durée, vent le plus fort et heures au moteur, avec le meilleur départ, jeudi à 14 h, marqué d’une étoile.",coords:"",caption:"Leros → Rhodes, départs à partir du mercredi 8 h",card:!0},{id:"stays",number:"05",kicker:"Pauses des bateaux",title:"Là où les autres bateaux s’arrêtent.",text:"Où les équipages laissent-ils leur bateau deux mois en été, et où passent-ils l’hiver ? Les pauses des bateaux montrent les ports et les mouillages où des bateaux ont fait halte — de quelques jours à plus de six mois, selon la saison.",points:["Filtrez par durée de pause","Voyez au cours de quels mois les bateaux restent à un endroit","Repérez les ports d’hivernage prisés"],image:"stay-detail",alt:"Preveza : durée de pause typique et mois pendant lesquels les bateaux y restent.",coords:"38°57′N · 020°45′E",caption:"Preveza, durée de pause et saison"},{id:"hotspots",number:"06",kicker:"Hotspots",title:"Trouvez le mouillage plus tranquille.",text:"Où les bateaux se pressent-ils en août, et où reste-t-il de la place ? Hotspots montre, mois par mois, la fréquentation de chaque zone de navigation. La mer Ionienne et le golfe Saronique s’illuminent, tandis qu’Andros, à une journée de navigation d’Athènes, reste calme.",points:["Du calme à la foule","Chaque mois de l’année","Mois les plus fréquentés et les plus calmes en tout point"],image:"hotspots",alt:"La fréquentation des zones de navigation grecques en août : animée autour des îles Ioniennes et dans le golfe Saronique, calme au large d’Andros, avec l’inspecteur de point ouvert.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Grèce, août"},{id:"spot",number:"07",kicker:"Fiche du lieu",title:"Tout sur un endroit, en une seule fiche.",text:"Appuyez longuement sur n’importe quel endroit de la carte, ou faites un clic droit : la fiche du lieu réunit tout pour le mois choisi, le vent et l’état de la mer, les orages, la protection qu’offre le relief, ainsi que les pauses des bateaux et les routes à proximité. Gaios, à Paxos, en septembre : la plupart du temps un vent nul ou faible, une mer calme à peu agitée, et des orages environ un jour sur six. La barre des mois montre que novembre est le mois qui compte le plus d’orages.",points:["Vent, état de la mer et orages pour un lieu et un mois","Pauses des bateaux et routes dans un rayon de 5 milles nautiques","Chaque mois évalué d’un coup d’œil, en lien pour votre équipage"],image:"spot",alt:"La fiche du lieu pour Gaios, à Paxos, en septembre : vent et état de la mer, orages, protection par le relief, pauses des bateaux et routes à proximité, et chaque mois évalué d’un coup d’œil.",coords:"",caption:"Gaios, Paxos, septembre",card:!0},{id:"wind",number:"08",kicker:"Vent",title:"Combien de vent du nord faut-il attendre ?",text:"Choisissez une direction et un mois : en juillet, le centre de la mer Égée vire au bleu profond. C’est le meltem. Touchez un point près de Mykonos et vous voyez qu’il souffle du nord pendant 60 % des heures de juillet, voire plus.",points:["Force et direction pour chaque mois","Le vent selon l’heure","Touchez un point pour voir ses chiffres"],image:"wind",alt:"Fréquence du vent du nord en mer Égée en juillet, avec l’inspecteur de point ouvert près de Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vent du nord, mer Égée, juillet"},{id:"waves",number:"09",kicker:"Vagues",title:"Connaissez l’état de la mer avant de partir.",text:"Combien de jours par mois apportent des vagues de 2,5 m ou plus ? En janvier, la portée du mistral sur le golfe du Lion ressort nettement.",points:["De la mer calme à la mer très agitée","Houle et mer courte et creuse","Chaque mois de l’année"],image:"waves",alt:"Jours de mer agitée en Méditerranée occidentale en janvier.",coords:"41°00′N · 005°00′E",caption:"Jours agités, Méditerranée occidentale, janvier"},{id:"risk",number:"10",kicker:"Risque d’orage",title:"Quel port connaît le moins d’orages ?",text:"Le risque d’orage réunit la fréquence des orages, leur violence et la façon dont les montagnes, les caps et la mer ouverte les façonnent — pour chaque mois et jusqu’à l’échelle d’une baie. Touchez un endroit, puis un second, et voyez combien de risque en plus ou en moins présente le second. Preveza et Messolonghi sont deux ports d’hivernage prisés : en novembre, Messolonghi présente 27 % de risque d’orage en moins.",points:["Jours d’orage, densité de foudre et relief en une seule valeur","Des différences jusqu’à l’échelle d’une baie","Touchez deux endroits pour les comparer"],image:"risk",alt:"Risque d’orage en mer Ionienne en novembre : d’abord Preveza, puis Messolonghi, l’inspecteur de point affiche 27 % de risque en moins.",coords:"38°40′N · 021°10′E",caption:"Preveza face à Messolonghi, novembre",markers:[{x:34.09,y:27.12,text:"Preveza, touché en premier : valeur de risque 50 en novembre.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, à 47 M : 27 % de risque d’orage en moins.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Données de foudre",title:"Fréquence, violence, probabilité.",text:"Derrière le risque se cachent trois couches que vous pouvez aussi ouvrir séparément, sur la même échelle chaque mois. En septembre, la Méditerranée montre pourquoi il faut les trois : les orages sont les plus fréquents le long des côtes adriatiques et ioniennes, la foudre est la plus dense sur la mer entre l’Italie et la Grèce, et les conditions favorables aux orages s’étendent loin vers le sud.",points:["Jours d’orage : la fréquence des orages, 2013–2025","Densité de foudre : leur violence","Potentiel orageux : là où ils peuvent se former, 1994–2023"],image:"days",alt:"Jours d’orage en Méditerranée en septembre.",coords:"40°00′N · 015°00′E",caption:"Jours d’orage, Méditerranée, septembre",panels:[{label:"Jours d’orage",image:"days",alt:"Jours d’orage en Méditerranée en septembre.",caption:"Jours d’orage, Méditerranée, septembre"},{label:"Densité de foudre",image:"density",alt:"Densité de foudre en Méditerranée en septembre.",caption:"Densité de foudre, Méditerranée, septembre"},{label:"Potentiel orageux",image:"potential",alt:"Potentiel orageux en Méditerranée en septembre.",caption:"Potentiel orageux, Méditerranée, septembre"}]},{id:"terrain",number:"12",kicker:"Exposition du terrain",title:"Même baie, autre protection.",text:"Le risque d’orage vous dit quelle baie. L’exposition du terrain vous dit quel côté : les collines alentour peuvent protéger un mouillage de la foudre, et la couche montre à quel point le relief protège chaque partie d’une baie, pour que vous choisissiez le meilleur endroit avant de jeter l’ancre.",points:["Comparez les endroits d’une même baie","Données d’altitude détaillées à 30 m"],image:"terrain",alt:"Exposition du terrain dans la baie de Komiža, sur l’île de Vis, en Croatie.",coords:"43°02′N · 016°05′E",caption:"Baie de Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Faible effet protecteur du relief environnant.",color:"#762a83"},{x:53.84,y:26.35,text:"Effet protecteur partiel du relief environnant.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Effet protecteur plus marqué du relief environnant.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Fonds marins",title:"Sable ou herbier ?",text:"Avant de mouiller : la couche Fonds marins montre le sable, la vase, la roche, les herbiers et le corail le long des côtes, de la Méditerranée aux tropiques. Dans la baie de Palma, une large bande d’herbier longe la côte et le sable se trouve plus au large. Le mouillage sur la posidonie est interdit dans de plus en plus d’endroits : mieux vaut le savoir avant d’arriver.",points:["Sable, vase, roche, herbier et corail","Europe et côtes tropicales peu profondes","Ouvert à tous"],image:"seabed",alt:"Les fonds marins dans la baie de Palma, Majorque : une large bande d’herbier le long de la côte, du sable plus au large, l’inspecteur indique un herbier.",coords:"39°30′N · 002°37′E",caption:"Fonds marins, baie de Palma"}],story:{kicker:"Notre histoire",title:"Né d’une grosse frayeur.",text:"En octobre 2024, notre famille naviguait en mer Ionienne quand la foudre est tombée juste à côté de notre bateau. Ce moment a soulevé une question simple : sommes-nous plus en sécurité ici, ou de l’autre côté de la baie ? IncusGrid est né pour y répondre — et est devenu une carte de tout ce que nous aurions aimé savoir avant cette saison.",more:"Lire toute l’histoire (en anglais)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Grèce",note:"Là où l’idée est née"},fromBlog:{kicker:"Sur le blog",title:"Des histoires de données, côté mer.",all:"Tous les articles",note:"Articles en anglais."},devices:{kicker:"Web & Android",title:"Sur le pont ou à la table à cartes.",text:"Utilisez IncusGrid dans n’importe quel navigateur ou installez l’appli Android. Cherchez votre bassin de navigation et explorez-le sur téléphone, tablette ou ordinateur portable.",points:["Aucune installation dans le navigateur","Appli Android sur Google Play","Disponible en 19 langues"],web:"Ouvrir dans le navigateur",android:"Disponible sur Google Play",phoneAlt:"L’appli Android IncusGrid affichant les pauses des bateaux autour des îles Ioniennes."},final:{title:"Préparez votre prochaine saison. Et votre prochaine traversée.",text:"Routes, pauses des bateaux, vent, vagues et foudre issus de nombreuses années de données réelles, plus les prévisions à 10 jours et le planificateur de traversée — sur une seule carte.",cta:"Ouvrir la carte"},disclaimerLabel:"Attention",disclaimer:"IncusGrid est fait pour préparer vos navigations et n’est pas une aide à la navigation. Les routes sont tracées de façon schématique, et les pauses des bateaux sont déduites d’interruptions dans les signalements de position, pas de places de port confirmées. Le planificateur de traversée utilise une polaire simplifiée, sans courants ni effet des vagues sur la vitesse du bateau, et ne vous guide pas jusque dans le port. Consultez toujours les prévisions actuelles, les cartes marines officielles et les conditions locales avant de prendre la mer.",footer:{blog:"Blog",legal:"Mentions légales",privacy:"Politique de confidentialité",terms:"Conditions d’utilisation",cookies:"Paramètres des cookies",support:"Assistance",madeWith:"Fait avec",made:"au Portugal",englishOnly:"Pages juridiques en anglais."}},d={path:"/it",htmlLang:"it",ogLocale:"it_IT",meta:{title:"IncusGrid · Conoscenza locale e routing meteo per velisti",description:"Rotte a vela e soste delle barche da vere traversate, anni di dati su vento, onde e fulmini, più le previsioni a 10 giorni e il routing meteo per la tua barca. Pianifica la stagione e la traversata su un’unica mappa.",keywords:"routing meteo, pianificazione della traversata, pianificazione della rotta, scelta della partenza, meteo marina, previsioni del vento, polare della barca, rotte a vela, rotte di crociera, navigazione d’altura, ancoraggio, rada, marina, porto, rimessaggio invernale, statistiche del vento, stato del mare, onde, fulmini, temporali, rischio temporali, densità di fulmini, pianificare una crociera, barca a vela, vela d’altura, fondale, posidonia, prateria di posidonia, fondale per ancorare"},nav:{routes:"Rotte",passages:"Traversate",stays:"Soste delle barche",weather:"Meteo",thunderstorms:"Fulmini",blog:"Blog",openApp:"Apri la mappa"},hero:{position:"Sailing intelligence",lead:"IncusGrid trasforma anni di dati nella conoscenza locale che ogni equipaggio deve avere prima di mollare gli ormeggi: veri movimenti di barche, vento, onde e fulmini su un’unica mappa. In più le previsioni dei prossimi 10 giorni e un pianificatore di traversata che calcola la rotta della tua barca nel vento previsto, ora per ora, con raffiche e onde lungo il percorso.",ctaApp:"Apri la mappa",ctaAndroid:"App Android",heroAlt:"Rotte a vela nel Mar dei Caraibi, da Hispaniola alle Piccole Antille fino alla costa del Sud America, tracciate da vere traversate di barche da crociera.",heroCaption:"Rotte a vela, Mar dei Caraibi · tutti i mesi",notes:[{label:"Barche",value:"Migliaia"},{label:"Movimenti",value:"Milioni"},{label:"Fulmini",value:"Miliardi"},{label:"Previsioni",value:"10 giorni"},{label:"Copertura",value:"Mondiale"}]},contrast:{kicker:"Stagione e previsioni",title:"La stagione ti dice quale mese. La previsione ti dice quale giorno.",text:"Quale traversata fanno gli equipaggi a giugno? Dove passano l’inverno le barche? Quale mese porta il Meltemi, e in quale porto di svernamento ci sono meno temporali a novembre? Risposte che emergono solo guardando molti anni insieme. Quando la partenza si avvicina, il pianificatore di traversata calcola sulle previsioni a 10 giorni quando partire e quando arrivi."},chapters:[{id:"routes",number:"01",kicker:"Rotte a vela",title:"Pianifica le traversate con l’esperienza di migliaia di equipaggi.",text:"Migliaia di vere traversate mostrano quando conviene attraversare, in quale direzione, e da dove gli equipaggi partono e dove arrivano. I venti dominanti, i posti giusti per aspettare una finestra meteo e un atterraggio sicuro dopo una notte in mare sono già compresi. Dalla Sicilia alle Isole Ionie, per esempio, la maggior parte delle barche va verso est a maggio e giugno e torna a settembre.",points:["Popolarità per mese e direzione","Le rotte più popolari nella vista attuale della mappa","Condividi una rotta con il tuo equipaggio"],image:"route-detail",alt:"La rotta dalla Sicilia alle Isole Ionie selezionata, con la sua popolarità per ogni mese e direzione.",coords:"38°12′N · 017°30′E",caption:"Sicilia → Isole Ionie, per mese e direzione"},{id:"route-wind",number:"02",kicker:"Il vento lungo la rotta",title:"Conosci il vento prima di mollare gli ormeggi.",text:"Ogni rotta mostra il vento che puoi aspettarti, mese per mese: da dove arriva, quanto soffia forte, quanta parte della traversata navighi di bolina, al traverso o in andatura portante, e quanto spesso il mare resta calmo. Dalla Sicilia alle Isole Ionie a maggio: vento da nord-ovest, forza 3 Beaufort, più di metà del percorso in andatura portante.",points:["Vento dominante e forza Beaufort per ogni mese","Bolina, traverso o andatura portante lungo la rotta","Stato del mare lungo la rotta"],image:"route-wind",alt:"La scheda della rotta dalla Sicilia alle Isole Ionie: vento dominante, forza Beaufort, forza del vento, andatura e stato del mare per ogni mese, con maggio selezionato.",coords:"",caption:"Sicilia → Isole Ionie, il vento a maggio",card:!0},{id:"passage",number:"03",kicker:"Pianificatore di traversata · routing meteo",title:"Sai quando arrivi prima di mollare gli ormeggi.",text:"Imposta partenza e destinazione, scegli la tua barca, e il pianificatore di traversata trova una rotta veloce nel vento previsto dei prossimi 10 giorni, ora per ora, con raffiche e onde lungo il percorso. Da Lero a Rodi, 86 miglia nautiche, partenza mercoledì alle 20:00: una notte in andatura portante con non più di 15 nodi di vento, senza motore, arrivo giovedì poco prima delle undici.",points:["Arrivo, vento più forte, raffiche e onde, ore a vela e a motore","Per la tua barca: tipo e lunghezza, o la tua polare","In navigazione, la tua posizione rispetto alla rotta pianificata e il resto del percorso ricalcolato"],image:"passage",alt:"Il pianificatore di traversata con la rotta da Lero a Rodi sulla previsione del vento: waypoint con orari, la barca a sud di Kos di notte, e accanto l’arrivo, il vento più forte e le ore a vela e a motore.",coords:"36°48′N · 027°50′E",caption:"Lero → Rodi, partenza mercoledì 20:00 · previsione del 31 ottobre"},{id:"departures",number:"04",kicker:"Confronta le partenze",title:"Il giorno giusto per mollare gli ormeggi.",text:"Il pianificatore calcola la stessa traversata per un massimo di dodici partenze, a sei ore di distanza, e mette a confronto arrivo, durata, vento più forte e tempo a motore. Partendo da Lero mercoledì mattina arrivi a Rodi a mezzanotte; partendo mercoledì sera, la mattina dopo. La stella segna la partenza con meno tempo a motore e di bolina.",points:["Fino a dodici partenze, ogni sei ore","Tocca una riga per vederne la rotta","Salva una traversata o condividila con il tuo equipaggio, sempre sulla previsione più recente"],image:"departures",alt:"La tabella delle partenze da Lero a Rodi, ogni sei ore da mercoledì alle 08:00: arrivo, durata, vento più forte e ore a motore, con la partenza migliore, giovedì alle 14:00, segnata da una stella.",coords:"",caption:"Lero → Rodi, partenze da mercoledì 08:00",card:!0},{id:"stays",number:"05",kicker:"Soste delle barche",title:"Dove si fermano le altre barche.",text:"Dove lasciano la barca gli equipaggi per due mesi d’estate, e dove passano l’inverno? Le soste delle barche mostrano i porti e gli ancoraggi in cui le barche si sono fermate — da pochi giorni a più di sei mesi, stagione per stagione.",points:["Filtra per durata della sosta","Scopri in quali mesi le barche restano in un posto","Individua i porti più scelti per l’inverno"],image:"stay-detail",alt:"Preveza: durata tipica della sosta e mesi in cui le barche ci restano.",coords:"38°57′N · 020°45′E",caption:"Preveza, durata della sosta e stagione"},{id:"hotspots",number:"06",kicker:"Hotspot",title:"Trova l’ancoraggio più tranquillo.",text:"Dove si affollano le barche ad agosto, e dove c’è ancora spazio? Hotspot mostra mese per mese quanto è frequentata ogni zona di navigazione. Lo Ionio e il Golfo Saronico si accendono, mentre Andros, a una giornata di navigazione da Atene, resta tranquilla.",points:["Da tranquillo ad affollato","Ogni mese dell’anno","Mesi più e meno frequentati in ogni punto"],image:"hotspots",alt:"Quanto sono frequentate le zone di navigazione greche ad agosto: affollate intorno alle Isole Ionie e nel Golfo Saronico, tranquille al largo di Andros, con l’ispettore del punto aperto.",coords:"38°24′N · 023°36′E",caption:"Hotspot, Grecia, agosto"},{id:"spot",number:"07",kicker:"Scheda del luogo",title:"Tutto su un luogo, in una sola scheda.",text:"Tieni premuto un punto qualsiasi della mappa, o fai clic destro: la scheda del luogo riunisce tutto per il mese che scegli, vento e stato del mare, temporali, quanto il rilievo lo protegge, e le soste delle barche e le rotte nei dintorni. Gaios, a Paxos, a settembre: per lo più bonaccia o vento leggero, mare calmo o poco mosso e temporali circa un giorno su sei. La striscia dei mesi mostra che novembre è il mese con più temporali.",points:["Vento, stato del mare e temporali per un luogo e un mese","Soste delle barche e rotte entro 5 miglia nautiche","Ogni mese valutato a colpo d’occhio, come link per il tuo equipaggio"],image:"spot",alt:"La scheda del luogo per Gaios, a Paxos, a settembre: vento e stato del mare, temporali, protezione del rilievo, soste delle barche e rotte nei dintorni e ogni mese valutato a colpo d’occhio.",coords:"",caption:"Gaios, Paxos, settembre",card:!0},{id:"wind",number:"08",kicker:"Vento",title:"Quanto vento da nord devi aspettarti?",text:"Scegli una direzione e un mese: a luglio l’Egeo centrale si tinge di blu intenso. È il Meltemi. Tocca un punto vicino a Mykonos e vedi che soffia da nord per il 60% o più di tutte le ore di luglio.",points:["Intensità e direzione per ogni mese","Vento per fascia oraria","Tocca un punto per vederne i numeri"],image:"wind",alt:"Quanto spesso il vento soffia da nord nel Mar Egeo a luglio, con l’ispettore del punto aperto vicino a Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vento da nord, Mar Egeo, luglio"},{id:"waves",number:"09",kicker:"Onde",title:"Conosci lo stato del mare prima di partire.",text:"Quanti giorni al mese portano onde di 2,5 m o più? A gennaio si vede chiaramente fin dove arriva il Maestrale nel Golfo del Leone.",points:["Dal mare calmo al mare molto agitato","Onda lunga e mare corto e ripido","Ogni mese dell’anno"],image:"waves",alt:"Giorni di mare agitato nel Mediterraneo occidentale a gennaio.",coords:"41°00′N · 005°00′E",caption:"Giorni agitati, Mediterraneo occidentale, gennaio"},{id:"risk",number:"10",kicker:"Rischio temporali",title:"Quale porto ha meno temporali?",text:"Il Rischio temporali unisce quanto spesso si verificano i temporali, quanto sono violenti e come montagne, promontori e mare aperto li modellano — per ogni mese e fino alla singola baia. Tocca un punto, poi un secondo, e vedi quanto rischio in più o in meno ha il secondo. Preveza e Messolonghi sono entrambe molto amate per svernare: a novembre Messolonghi ha il 27% di rischio temporali in meno.",points:["Giorni di temporale, densità di fulmini e terreno in un unico valore","Differenze fino alla singola baia","Tocca due punti per confrontarli"],image:"risk",alt:"Rischio temporali nel Mar Ionio a novembre: prima toccata Preveza, poi Messolonghi, l’ispettore dei punti mostra il 27% di rischio in meno.",coords:"38°40′N · 021°10′E",caption:"Preveza vs. Messolonghi, novembre",markers:[{x:34.09,y:27.12,text:"Preveza, toccata per prima: valore di rischio 50 a novembre.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, a 47 mn: il 27% di rischio temporali in meno.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Dati sui fulmini",title:"Quanto spesso, quanto forte, quanto probabile.",text:"Dietro il rischio ci sono tre livelli che puoi aprire anche singolarmente, ogni mese sulla stessa scala. A settembre il Mediterraneo mostra perché servono tutti e tre: i temporali sono più frequenti lungo le coste adriatiche e ioniche, i fulmini più densi sul mare tra Italia e Grecia, e le condizioni favorevoli ai temporali si spingono molto a sud.",points:["Giorni di temporale: quanto spesso si verificano, 2013–2025","Densità di fulmini: quanto sono violenti","Potenziale temporalesco: dove possono formarsi, 1994–2023"],image:"days",alt:"Giorni di temporale nel Mediterraneo a settembre.",coords:"40°00′N · 015°00′E",caption:"Giorni di temporale, Mediterraneo, settembre",panels:[{label:"Giorni di temporale",image:"days",alt:"Giorni di temporale nel Mediterraneo a settembre.",caption:"Giorni di temporale, Mediterraneo, settembre"},{label:"Densità di fulmini",image:"density",alt:"Densità di fulmini nel Mediterraneo a settembre.",caption:"Densità di fulmini, Mediterraneo, settembre"},{label:"Potenziale temporalesco",image:"potential",alt:"Potenziale temporalesco nel Mediterraneo a settembre.",caption:"Potenziale temporalesco, Mediterraneo, settembre"}]},{id:"terrain",number:"12",kicker:"Esposizione del terreno",title:"Stessa baia, schermatura diversa.",text:"Il Rischio temporali ti dice quale baia. L’Esposizione del terreno ti dice quale lato: le colline intorno possono schermare un ancoraggio dai fulmini, e il livello mostra quanto il terreno protegge ogni parte di una baia, così scegli il punto migliore prima di dare fondo.",points:["Confronta punti diversi della stessa baia","Dati altimetrici dettagliati a 30 m"],image:"terrain",alt:"Esposizione del terreno nella baia di Komiža, sull’isola di Vis, in Croazia.",coords:"43°02′N · 016°05′E",caption:"Baia di Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Scarsa schermatura del terreno circostante.",color:"#762a83"},{x:53.84,y:26.35,text:"Una certa schermatura del terreno circostante.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Maggiore schermatura del terreno circostante.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Fondale",title:"Sabbia o posidonia?",text:"Prima di dare fondo all’ancora: il livello Fondale mostra sabbia, fango, roccia, praterie di fanerogame e corallo lungo la costa, dal Mediterraneo ai tropici. Nella baia di Palma un’ampia fascia di prateria corre lungo la riva e la sabbia è più al largo. Ancorare sulla posidonia è vietato in sempre più luoghi, quindi conviene saperlo prima di arrivare.",points:["Sabbia, fango, roccia, praterie e corallo","Europa e coste tropicali poco profonde","Aperto a tutti"],image:"seabed",alt:"Il fondale nella baia di Palma, Maiorca: un’ampia fascia di prateria lungo la costa, sabbia più al largo, con l’ispettore che indica prateria.",coords:"39°30′N · 002°37′E",caption:"Fondale, baia di Palma"}],story:{kicker:"La nostra storia",title:"Nato da un grande spavento.",text:"Nell’ottobre 2024 la nostra famiglia navigava nel Mar Ionio quando un fulmine è caduto proprio accanto alla nostra barca. Da quel momento è nata una domanda semplice: siamo più al sicuro qui o dall’altra parte della baia? IncusGrid è nato come risposta — ed è diventato una mappa di tutto ciò che avremmo voluto sapere prima di quella stagione.",more:"Leggi tutta la storia (in inglese)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Grecia",note:"Dove è nata l’idea"},fromBlog:{kicker:"Dal blog",title:"Storie di dati dal mare.",all:"Tutti gli articoli",note:"Articoli in inglese."},devices:{kicker:"Web & Android",title:"In coperta o al tavolo da carteggio.",text:"Usa IncusGrid in qualsiasi browser o installa l’app Android. Cerca la tua zona di navigazione ed esplorala su smartphone, tablet o laptop.",points:["Nessuna installazione nel browser","App Android su Google Play","Disponibile in 19 lingue"],web:"Apri nel browser",android:"Disponibile su Google Play",phoneAlt:"L’app Android di IncusGrid con le soste delle barche intorno alle Isole Ionie."},final:{title:"Pianifica la tua prossima stagione. E la tua prossima traversata.",text:"Rotte, soste delle barche, vento, onde e fulmini da molti anni di dati reali, più le previsioni a 10 giorni e il pianificatore di traversata — su un’unica mappa.",cta:"Apri la mappa"},disclaimerLabel:"Attenzione",disclaimer:"IncusGrid è fatto per la pianificazione e non è un aiuto alla navigazione. Le rotte sono tracciate in modo schematico, e le soste delle barche sono ricavate dalle pause nelle segnalazioni di posizione, non da ormeggi confermati. Il pianificatore di traversata usa una polare semplificata, senza correnti né l’effetto delle onde sulla velocità della barca, e non ti guida fin dentro il porto. Prima di uscire in mare controlla sempre le previsioni aggiornate, le carte nautiche ufficiali e le condizioni locali.",footer:{blog:"Blog",legal:"Note legali",privacy:"Informativa sulla privacy",terms:"Termini di servizio",cookies:"Impostazioni cookie",support:"Assistenza",madeWith:"Fatto con",made:"in Portogallo",englishOnly:"Pagine legali in inglese."}},u={path:"/nl",htmlLang:"nl",ogLocale:"nl_NL",meta:{title:"IncusGrid · Lokale kennis en weerrouting voor zeilers",description:"Zeilroutes en bootpauzes uit echte overtochten, jaren aan wind-, golf- en bliksemdata, plus de weersverwachting voor 10 dagen en weerrouting voor je boot. Plan je seizoen en je overtocht op één kaart.",keywords:"weerrouting, weather routing, overtocht plannen, routeplanner, vertrektijd plannen, zeilweer, windverwachting, polardiagram, zeilroutes, zeilreis plannen, ankerplaats, jachthaven, overwinteren, windstatistiek, zeegang, golven, deining, bliksem, onweer, onweersrisico, bliksemdichtheid, zeilen, jacht, langeafstandszeilen, blauwwaterzeilen, zeebodem, zeegras, posidonia, ankergrond"},nav:{routes:"Routes",passages:"Overtochten",stays:"Bootpauzes",weather:"Weer",thunderstorms:"Bliksem",blog:"Blog",openApp:"Open de kaart"},hero:{position:"Sailing intelligence",lead:"IncusGrid maakt van jaren aan data de lokale kennis die elke bemanning nodig heeft voordat ze losgooit: echte bootbewegingen, wind, golven en bliksem op één kaart. Plus de weersverwachting voor de komende 10 dagen en een overtochtplanner die je boot uur voor uur door de voorspelde wind routeert, met vlagen en golven onderweg.",ctaApp:"Open de kaart",ctaAndroid:"Android-app",heroAlt:"Zeilroutes in de Caribische Zee, van Hispaniola via de Kleine Antillen tot de kust van Zuid-Amerika, getekend uit echte overtochten van zeiljachten.",heroCaption:"Zeilroutes, Caribische Zee · alle maanden",notes:[{label:"Boten",value:"Duizenden"},{label:"Bewegingen",value:"Miljoenen"},{label:"Blikseminslagen",value:"Miljarden"},{label:"Verwachting",value:"10 dagen"},{label:"Dekking",value:"Wereldwijd"}]},contrast:{kicker:"Seizoen en verwachting",title:"Het seizoen vertelt je welke maand. De verwachting vertelt je welke dag.",text:"Welke oversteek maken bemanningen in juni? Waar overwinteren boten? In welke maand komt de Meltemi, en in welke overwinteringshaven is er in november minder onweer? Antwoorden die pas zichtbaar worden als je veel jaren tegelijk bekijkt. Komt je vertrek dichterbij, dan rekent de overtochtplanner op de verwachting voor 10 dagen uit wanneer je vertrekt en wanneer je aankomt."},chapters:[{id:"routes",number:"01",kicker:"Zeilroutes",title:"Plan oversteken met de ervaring van duizenden bemanningen.",text:"Duizenden echte overtochten laten zien wanneer een oversteek zinvol is, in welke richting, en waar bemanningen vertrekken en aankomen. De heersende wind, goede plekken om op een weergat te wachten en een veilige aanlanding na een nacht op zee zitten er al in. Van Sicilië naar de Ionische Eilanden bijvoorbeeld varen de meeste boten in mei en juni naar het oosten en in september weer terug.",points:["Populariteit per maand en richting","De populairste routes in je huidige kaartbeeld","Deel een route met je bemanning"],image:"route-detail",alt:"De route van Sicilië naar de Ionische Eilanden geselecteerd, met de populariteit per maand en richting.",coords:"38°12′N · 017°30′E",caption:"Sicilië → Ionische Eilanden, per maand en richting"},{id:"route-wind",number:"02",kicker:"Wind langs de route",title:"Ken de wind voordat je losgooit.",text:"Elke route toont de wind die je er kunt verwachten, maand voor maand: waar hij vandaan komt, hoe hard hij waait, hoeveel van de overtocht je aan de wind, met halve wind of met ruime wind zeilt, en hoe vaak de zee kalm blijft. Van Sicilië naar de Ionische Eilanden in mei: wind uit het noordwesten, 3 Bft, meer dan de helft van de tocht met ruime wind.",points:["Heersende wind en windkracht in Beaufort voor elke maand","Aan de wind, halve wind of ruime wind op de koers van de route","Zeegang langs de route"],image:"route-wind",alt:"De routekaart van Sicilië naar de Ionische Eilanden: heersende wind, windkracht in Beaufort, kracht, koers en zeegang voor elke maand, met mei geselecteerd.",coords:"",caption:"Sicilië → Ionische Eilanden, wind in mei",card:!0},{id:"passage",number:"03",kicker:"Overtochtplanner · weerrouting",title:"Weet wanneer je aankomt voordat je losgooit.",text:"Kies een start en een bestemming, kies je boot, en de overtochtplanner vindt een snelle route door de voorspelde wind van de komende 10 dagen, uur voor uur, met vlagen en golven onderweg. Van Leros naar Rhodos, 86 zeemijl, vertrek woensdag om 20:00: één nacht voor de wind met niet meer dan 15 knopen wind, zonder motor, aankomst donderdag even voor elven.",points:["Aankomst, sterkste wind, vlagen en golven, uren onder zeil en op de motor","Voor jouw boot: type en lengte, of je eigen polar","Onderweg je positie naast het plan, en de rest van de route opnieuw berekend"],image:"passage",alt:"De overtochtplanner met de route van Leros naar Rhodos op de windverwachting: waypoints met tijden, de boot ’s nachts ten zuiden van Kos, en daarnaast de aankomst, de sterkste wind en de uren zeilen en motoren.",coords:"36°48′N · 027°50′E",caption:"Leros → Rhodos, vertrek woensdag 20:00 · verwachting van 31 oktober"},{id:"departures",number:"04",kicker:"Vertrektijden vergelijken",title:"De juiste dag om los te gooien.",text:"De planner berekent dezelfde overtocht voor maximaal twaalf vertrektijden, zes uur uit elkaar, en zet aankomst, duur, sterkste wind en motoruren naast elkaar. Vertrek je woensdagochtend uit Leros, dan ben je om middernacht op Rhodos; vertrek je woensdagavond, dan de volgende ochtend. De ster markeert het vertrek met de minste tijd op de motor en aan de wind.",points:["Tot twaalf vertrektijden, om de zes uur","Tik op een rij om de route te zien","Bewaar een overtocht of deel hem met je bemanning, altijd op de nieuwste verwachting"],image:"departures",alt:"De vertrektabel voor Leros naar Rhodos, om de zes uur vanaf woensdag 08:00: aankomst, duur, sterkste wind en motoruren, met het beste vertrek, donderdag om 14:00, gemarkeerd met een ster.",coords:"",caption:"Leros → Rhodos, vertrektijden vanaf woensdag 08:00",card:!0},{id:"stays",number:"05",kicker:"Bootpauzes",title:"Waar andere boten liggen.",text:"Waar laten bemanningen hun boot in de zomer twee maanden liggen, en waar brengen ze de winter door? Bootpauzes tonen de havens en ankerplaatsen waar boten stillagen — van een paar dagen tot meer dan zes maanden, per seizoen.",points:["Filter op verblijfsduur","Zie in welke maanden boten ergens liggen","Ontdek populaire winterhavens"],image:"stay-detail",alt:"Preveza: gebruikelijke verblijfsduur en de maanden waarin boten er liggen.",coords:"38°57′N · 020°45′E",caption:"Preveza, verblijfsduur en seizoen"},{id:"hotspots",number:"06",kicker:"Hotspots",title:"Vind de rustigere ankerplek.",text:"Waar is het in augustus druk met boten, en waar is nog plek? Hotspots laat per maand zien hoe druk elk vaargebied is. De Ionische Zee en de Saronische Golf kleuren fel, terwijl Andros, een dagtocht van Athene, rustig blijft.",points:["Van rustig tot druk","Elke maand van het jaar","Drukste en rustigste maanden op elk punt"],image:"hotspots",alt:"Hoe druk de Griekse vaargebieden in augustus zijn: druk rond de Ionische Eilanden en in de Saronische Golf, rustig bij Andros, met de puntinspector geopend.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Griekenland, augustus"},{id:"spot",number:"07",kicker:"Plekprofiel",title:"Alles over één plek, in één overzicht.",text:"Houd een plek op de kaart ingedrukt of klik er met de rechtermuisknop op, en het plekprofiel brengt alles samen voor de maand die je kiest: wind en zeegang, onweer, hoe goed het terrein de plek beschermt, en de bootpauzes en routes in de buurt. Gaios op Paxos in september: meestal windstil of weinig wind, een kalme tot licht bewogen zee en op ongeveer één op de zes dagen onweer. De maandbalk laat zien dat november de maand met het meeste onweer is.",points:["Wind, zeegang en onweer voor één plek en maand","Bootpauzes en routes binnen 5 zeemijl","Elke maand in één oogopslag beoordeeld, als link voor je bemanning"],image:"spot",alt:"Het plekprofiel voor Gaios op Paxos in september: wind en zeegang, onweer, bescherming door het terrein, bootpauzes en routes in de buurt en elke maand in één oogopslag beoordeeld.",coords:"",caption:"Gaios, Paxos, september",card:!0},{id:"wind",number:"08",kicker:"Wind",title:"Hoeveel noordenwind kun je verwachten?",text:"Kies een richting en een maand: in juli kleurt de centrale Egeïsche Zee diepblauw. Dat is de Meltemi. Tik op een punt bij Mykonos en je ziet dat de wind in juli in 60% van alle uren of meer uit het noorden waait.",points:["Kracht en richting voor elke maand","Wind per tijdstip","Tik op een punt voor de cijfers"],image:"wind",alt:"Hoe vaak de wind in juli uit het noorden waait in de Egeïsche Zee, met de puntdetails geopend bij Mykonos.",coords:"37°36′N · 025°00′E",caption:"Wind uit het noorden, Egeïsche Zee, juli"},{id:"waves",number:"09",kicker:"Golven",title:"Ken de zeegang voordat je vertrekt.",text:"Hoeveel dagen per maand brengen golven van 2,5 m of meer? In januari zie je duidelijk hoe ver de Mistral over de Golf van Lion reikt.",points:["Van kalme tot zeer ruwe zee","Deining en korte steile zee","Elke maand van het jaar"],image:"waves",alt:"Dagen met ruwe zee in de westelijke Middellandse Zee in januari.",coords:"41°00′N · 005°00′E",caption:"Ruwe dagen, westelijke Middellandse Zee, januari"},{id:"risk",number:"10",kicker:"Onweersrisico",title:"In welke haven is er minder onweer?",text:"Onweersrisico combineert hoe vaak onweer voorkomt, hoe hevig het is en hoe bergen, kapen en open zee het vormen, voor elke maand en tot op het niveau van afzonderlijke baaien. Tik op een plek, dan op een tweede, en je ziet hoeveel meer of minder risico de tweede heeft. Preveza en Messolonghi zijn allebei populair om te overwinteren: in november heeft Messolonghi 27% minder onweersrisico.",points:["Onweersdagen, bliksemdichtheid en terrein in één waarde","Verschillen tot op het niveau van afzonderlijke baaien","Tik op twee plekken om ze te vergelijken"],image:"risk",alt:"Onweersrisico in de Ionische Zee in november: eerst Preveza aangetikt, dan Messolonghi, met de puntinspector die 27% minder risico toont.",coords:"38°40′N · 021°10′E",caption:"Preveza vs. Messolonghi, november",markers:[{x:34.09,y:27.12,text:"Preveza, als eerste aangetikt: risicowaarde 50 in november.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, 47 zm verderop: 27% minder onweersrisico.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Bliksemdata",title:"Hoe vaak, hoe hevig, hoe waarschijnlijk.",text:"Achter het risico zitten drie lagen die je ook afzonderlijk kunt openen, elke maand op dezelfde schaal. In september laat de Middellandse Zee zien waarom je ze alle drie nodig hebt: onweer komt het vaakst voor langs de Adriatische en Ionische kust, de bliksem is het dichtst boven zee tussen Italië en Griekenland, en omstandigheden die onweer in de hand werken reiken tot ver in het zuiden.",points:["Onweersdagen: hoe vaak onweer voorkomt, 2013–2025","Bliksemdichtheid: hoe hevig het onweer is","Kansrijke onweersomstandigheden: waar onweer kan ontstaan, 1994–2023"],image:"days",alt:"Onweersdagen in de Middellandse Zee in september.",coords:"40°00′N · 015°00′E",caption:"Onweersdagen, Middellandse Zee, september",panels:[{label:"Onweersdagen",image:"days",alt:"Onweersdagen in de Middellandse Zee in september.",caption:"Onweersdagen, Middellandse Zee, september"},{label:"Bliksemdichtheid",image:"density",alt:"Bliksemdichtheid in de Middellandse Zee in september.",caption:"Bliksemdichtheid, Middellandse Zee, september"},{label:"Kansrijke onweersomstandigheden",image:"potential",alt:"Kansrijke onweersomstandigheden in de Middellandse Zee in september.",caption:"Kansrijke onweersomstandigheden, Middellandse Zee, september"}]},{id:"terrain",number:"12",kicker:"Terreinblootstelling",title:"Dezelfde baai, andere afscherming.",text:"Onweersrisico vertelt je welke baai. Terreinblootstelling vertelt je welke kant ervan: omliggende heuvels kunnen een ankerplaats afschermen tegen bliksem, en de laag laat zien hoe goed het terrein elk deel van een baai beschermt — zodat je de betere plek kiest voordat het anker valt.",points:["Vergelijk plekken binnen één baai","Gedetailleerde hoogtedata met 30 m resolutie"],image:"terrain",alt:"Terreinblootstelling in de baai van Komiža op Vis, Kroatië.",coords:"43°02′N · 016°05′E",caption:"Baai van Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Weinig afscherming door het omliggende terrein.",color:"#762a83"},{x:53.84,y:26.35,text:"Enige afscherming door het omliggende terrein.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Meer afscherming door het omliggende terrein.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Zeebodem",title:"Zand of zeegras?",text:"Voordat het anker valt: de laag Zeebodem toont zand, slib, rots, zeegras en koraal langs de kust, van de Middellandse Zee tot de tropen. In de baai van Palma loopt een brede strook zeegras langs de kust, het zand ligt verder uit de kust. Ankeren op posidonia is op steeds meer plekken verboden, dus het loont om het te weten voordat je aankomt.",points:["Zand, slib, rots, zeegras en koraal","Europa en ondiepe tropische kusten","Voor iedereen open"],image:"seabed",alt:"De zeebodem in de baai van Palma, Mallorca: een brede strook zeegras langs de kust, verder uit de kust zand, de puntinspector toont zeegras.",coords:"39°30′N · 002°37′E",caption:"Zeebodem, baai van Palma"}],story:{kicker:"Ons verhaal",title:"Ontstaan na een bijna-inslag.",text:"In oktober 2024 zeilde ons gezin op de Ionische Zee toen de bliksem vlak naast onze boot insloeg. Dat moment riep een simpele vraag op: liggen we hier veiliger, of aan de andere kant van de baai? IncusGrid begon als het antwoord — en groeide uit tot een kaart met alles wat we vóór dat seizoen hadden willen weten.",more:"Lees het hele verhaal (Engels)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Griekenland",note:"Waar het idee ontstond"},fromBlog:{kicker:"Van de blog",title:"Dataverhalen van het water.",all:"Alle berichten",note:"Berichten in het Engels."},devices:{kicker:"Web & Android",title:"Aan dek of aan de kaartentafel.",text:"Gebruik IncusGrid in elke browser of installeer de Android-app. Zoek je vaargebied en verken het op telefoon, tablet of laptop.",points:["In de browser zonder installatie","Android-app via Google Play","Beschikbaar in 19 talen"],web:"Openen in de browser",android:"Ontdek het op Google Play",phoneAlt:"IncusGrid-Android-app met bootpauzes rond de Ionische Eilanden."},final:{title:"Plan je volgende seizoen. En je volgende overtocht.",text:"Routes, bootpauzes, wind, golven en bliksem uit vele jaren echte data, plus de verwachting voor 10 dagen en de overtochtplanner — op één kaart.",cta:"Open de kaart"},disclaimerLabel:"Let op",disclaimer:"IncusGrid is gemaakt voor de planning en is geen navigatiemiddel. Routes zijn schematisch getekend, en bootpauzes zijn afgeleid uit pauzes in bootmeldingen, niet uit bevestigde ligplaatsen. De overtochtplanner gebruikt een eenvoudige polar, zonder stroming of het effect van golven op de bootsnelheid, en routeert je niet tot in de haven. Controleer altijd de actuele weersverwachting, officiële zeekaarten en de lokale omstandigheden voordat je de zee op gaat.",footer:{blog:"Blog",legal:"Juridische informatie",privacy:"Privacybeleid",terms:"Gebruiksvoorwaarden",cookies:"Cookie-instellingen",support:"Support",madeWith:"Met",made:"gemaakt in Portugal",englishOnly:"Juridische pagina’s in het Engels."}},m={path:"/es",htmlLang:"es",ogLocale:"es_ES",meta:{title:"IncusGrid · Conocimiento local y routing meteorológico para navegantes",description:"Rutas de navegación y pausas de barcos de travesías reales, años de datos de viento, oleaje y rayos, más el pronóstico a 10 días y el routing meteorológico para tu barco. Planifica tu temporada y tu travesía en un solo mapa.",keywords:"routing meteorológico, enrutamiento meteorológico, planificación de travesías, planificación de rutas, planificación de la salida, meteorología para navegar, previsión de viento, polar del barco, rutas de navegación, navegación de crucero, navegación de altura, fondeadero, fondeo, puerto deportivo, invernada, estadísticas de viento, estado del mar, oleaje, rayos, tormentas, riesgo de tormenta, densidad de rayos, planificar una travesía, velero, vuelta al mundo en velero, fondo marino, posidonia, pradera de posidonia, fondeo en arena"},nav:{routes:"Rutas",passages:"Travesías",stays:"Pausas de barcos",weather:"Tiempo",thunderstorms:"Rayos",blog:"Blog",openApp:"Abrir el mapa"},hero:{position:"Sailing intelligence",lead:"IncusGrid convierte años de datos en el conocimiento local que toda tripulación necesita antes de soltar amarras: movimientos reales de barcos, viento, oleaje y rayos en un solo mapa. Además, el pronóstico de los próximos 10 días y un planificador de travesías que traza la ruta de tu barco con el viento pronosticado, hora a hora, con rachas y oleaje a lo largo del camino.",ctaApp:"Abrir el mapa",ctaAndroid:"App para Android",heroAlt:"Rutas de navegación por el mar Caribe, de La Española a las Antillas Menores y la costa de Sudamérica, trazadas a partir de travesías reales de veleros de crucero.",heroCaption:"Rutas de navegación, mar Caribe · todos los meses",notes:[{label:"Barcos",value:"Miles"},{label:"Movimientos",value:"Millones"},{label:"Rayos",value:"Miles de millones"},{label:"Pronóstico",value:"10 días"},{label:"Cobertura",value:"Mundial"}]},contrast:{kicker:"Temporada y pronóstico",title:"La temporada te dice qué mes. El pronóstico te dice qué día.",text:"¿Qué travesía hacen las tripulaciones en junio? ¿Dónde pasan el invierno los barcos? ¿Qué mes trae el meltemi, y qué puerto de invernada tiene menos tormentas en noviembre? Respuestas que solo aparecen cuando miras muchos años a la vez. Cuando se acerca la salida, el planificador de travesías calcula con el pronóstico a 10 días cuándo salir y cuándo llegas."},chapters:[{id:"routes",number:"01",kicker:"Rutas de navegación",title:"Planifica travesías con la experiencia de miles de tripulaciones.",text:"Miles de travesías reales muestran cuándo tiene sentido cruzar, en qué dirección, y desde dónde salen y adónde llegan las tripulaciones. Los vientos dominantes, los buenos sitios para esperar una ventana meteorológica y una recalada segura tras una noche en el mar ya vienen incluidos. De Sicilia a las islas Jónicas, por ejemplo, la mayoría de los barcos navegan hacia el este en mayo y junio y vuelven en septiembre.",points:["Popularidad por mes y dirección","Las rutas más populares en tu vista actual del mapa","Comparte una ruta con tu tripulación"],image:"route-detail",alt:"La ruta de Sicilia a las islas Jónicas seleccionada, con su popularidad en cada mes y dirección.",coords:"38°12′N · 017°30′E",caption:"Sicilia → islas Jónicas, por mes y dirección"},{id:"route-wind",number:"02",kicker:"El viento en la ruta",title:"Conoce el viento antes de soltar amarras.",text:"Cada ruta muestra el viento que puedes esperar en ella, mes a mes: de dónde sopla, con qué fuerza, qué parte de la travesía navegas en ceñida, de través o con vientos portantes, y con qué frecuencia el mar se mantiene en calma. De Sicilia a las islas Jónicas en mayo: viento del noroeste, fuerza 3 Beaufort, más de la mitad del camino con vientos portantes.",points:["Viento dominante y fuerza Beaufort para cada mes","Ceñida, través o portantes en el rumbo de la ruta","Estado del mar a lo largo de la ruta"],image:"route-wind",alt:"La ficha de la ruta de Sicilia a las islas Jónicas: viento dominante, fuerza Beaufort, fuerza del viento, rumbo y estado del mar para cada mes, con mayo seleccionado.",coords:"",caption:"Sicilia → islas Jónicas, viento en mayo",card:!0},{id:"passage",number:"03",kicker:"Planificador de travesías · routing meteorológico",title:"Conoce tu hora de llegada antes de soltar amarras.",text:"Indica un origen y un destino, elige tu barco, y el planificador de travesías encuentra una ruta rápida con el viento pronosticado de los próximos 10 días, hora a hora, con rachas y oleaje a lo largo del camino. De Leros a Rodas, 86 millas náuticas, saliendo el miércoles a las 20:00: una noche con vientos portantes y no más de 15 nudos, sin motor, y llegada el jueves poco antes de las once.",points:["Llegada, viento máximo, rachas y oleaje, horas a vela y a motor","Para tu barco: tipo y eslora, o tu propia polar","Navegando, tu posición junto al plan y el resto de la ruta recalculado"],image:"passage",alt:"El planificador de travesías con la ruta de Leros a Rodas sobre el pronóstico de viento: waypoints con horas, el barco al sur de Kos de noche y, al lado, la llegada, el viento máximo y las horas a vela y a motor.",coords:"36°48′N · 027°50′E",caption:"Leros → Rodas, salida el miércoles 20:00 · pronóstico del 31 de octubre"},{id:"departures",number:"04",kicker:"Comparar salidas",title:"El día adecuado para soltar amarras.",text:"El planificador calcula la misma travesía para hasta doce salidas, cada seis horas, y compara llegada, duración, viento máximo y tiempo a motor. Saliendo de Leros el miércoles por la mañana, llegas a Rodas a medianoche; saliendo el miércoles por la noche, a la mañana siguiente. La estrella marca la salida con menos tiempo a motor y en ceñida.",points:["Hasta doce salidas, cada seis horas","Toca una fila para ver su ruta","Guarda una travesía o compártela con tu tripulación, siempre con el pronóstico más reciente"],image:"departures",alt:"La tabla de salidas de Leros a Rodas, cada seis horas desde el miércoles a las 08:00: llegada, duración, viento máximo y horas a motor, con la mejor salida, el jueves a las 14:00, marcada con una estrella.",coords:"",caption:"Leros → Rodas, salidas desde el miércoles 08:00",card:!0},{id:"stays",number:"05",kicker:"Pausas de barcos",title:"Dónde se quedan otros barcos.",text:"¿Dónde dejan las tripulaciones su barco dos meses en verano, y dónde pasan el invierno? Las pausas de barcos muestran los puertos y fondeaderos donde los barcos se han detenido — desde unos días hasta más de seis meses, según la temporada.",points:["Filtra por duración de la pausa","Descubre en qué meses se quedan los barcos en un lugar","Encuentra puertos populares para invernar"],image:"stay-detail",alt:"Preveza: duración típica de la pausa y meses en los que los barcos se quedan allí.",coords:"38°57′N · 020°45′E",caption:"Preveza, duración de la pausa y temporada"},{id:"hotspots",number:"06",kicker:"Hotspots",title:"Encuentra el fondeadero más tranquilo.",text:"¿Dónde se aglomeran los barcos en agosto y dónde queda sitio? Hotspots muestra, mes a mes, lo concurrida que está cada zona de navegación. El mar Jónico y el golfo Sarónico brillan, mientras Andros, a un día de navegación de Atenas, sigue tranquila.",points:["De tranquilo a concurrido","Cada mes del año","Meses más y menos concurridos en cada punto"],image:"hotspots",alt:"Lo concurridas que están las zonas de navegación griegas en agosto: llenas en torno a las islas Jónicas y en el golfo Sarónico, tranquilas frente a Andros, con el inspector de punto abierto.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Grecia, agosto"},{id:"spot",number:"07",kicker:"Ficha del lugar",title:"Todo sobre un lugar, en una sola ficha.",text:"Mantén pulsado cualquier lugar del mapa, o haz clic derecho, y la ficha del lugar lo reúne todo para el mes que elijas: viento y estado del mar, tormentas, cuánto lo protege el relieve, y las pausas de barcos y rutas cercanas. Gaios, en Paxos, en septiembre: casi siempre calma o viento flojo, mar en calma o marejadilla y tormentas aproximadamente uno de cada seis días. La franja de meses muestra que noviembre es el mes con más tormentas.",points:["Viento, estado del mar y tormentas para un lugar y un mes","Pausas de barcos y rutas a menos de 5 millas náuticas","Cada mes valorado de un vistazo, como enlace para tu tripulación"],image:"spot",alt:"La ficha del lugar de Gaios, en Paxos, en septiembre: viento y estado del mar, tormentas, protección del relieve, pausas de barcos y rutas cercanas y cada mes valorado de un vistazo.",coords:"",caption:"Gaios, Paxos, septiembre",card:!0},{id:"wind",number:"08",kicker:"Viento",title:"¿Cuánto viento del norte te espera?",text:"Elige una dirección y un mes: en julio, el Egeo central se tiñe de azul intenso. Es el meltemi. Toca un punto cerca de Mykonos y verás que sopla del norte en el 60 % de todas las horas de julio o más.",points:["Fuerza y dirección para cada mes","Viento según la hora del día","Toca cualquier punto para ver sus datos"],image:"wind",alt:"Con qué frecuencia sopla el viento del norte en el mar Egeo en julio, con el inspector de puntos abierto cerca de Mykonos.",coords:"37°36′N · 025°00′E",caption:"Viento del norte, mar Egeo, julio"},{id:"waves",number:"09",kicker:"Oleaje",title:"Conoce el estado del mar antes de zarpar.",text:"¿Cuántos días al mes traen olas de 2,5 m o más? En enero se ve con claridad hasta dónde llega el mistral en el golfo de León.",points:["De mar en calma a mar muy gruesa","Mar de fondo y mar corta y empinada","Todos los meses del año"],image:"waves",alt:"Días de mar agitada en el Mediterráneo occidental en enero.",coords:"41°00′N · 005°00′E",caption:"Días agitados, Mediterráneo occidental, enero"},{id:"risk",number:"10",kicker:"Riesgo de tormenta",title:"¿Qué puerto tiene menos tormentas?",text:"El Riesgo de tormenta combina la frecuencia de las tormentas, su violencia y cómo las moldean las montañas, los cabos y el mar abierto — para cada mes y hasta el nivel de cada bahía. Toca un lugar, luego otro, y verás cuánto más o menos riesgo tiene el segundo. Preveza y Messolonghi son dos puertos muy populares para invernar: en noviembre, Messolonghi tiene un 27 % menos de riesgo de tormenta.",points:["Días de tormenta, densidad de rayos y terreno en un solo valor","Diferencias hasta el nivel de cada bahía","Toca dos lugares para compararlos"],image:"risk",alt:"Riesgo de tormenta en el mar Jónico en noviembre: primero se toca Preveza, luego Messolonghi, y el inspector de puntos muestra un 27 % menos de riesgo.",coords:"38°40′N · 021°10′E",caption:"Preveza frente a Messolonghi, noviembre",markers:[{x:34.09,y:27.12,text:"Preveza, el primer punto tocado: valor de riesgo 50 en noviembre.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, a 47 mn: un 27 % menos de riesgo de tormenta.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Datos de rayos",title:"Frecuencia, violencia, probabilidad.",text:"Detrás del riesgo hay tres capas que también puedes abrir por separado, con la misma escala en todos los meses. En septiembre, el Mediterráneo muestra por qué hacen falta las tres: las tormentas son más frecuentes a lo largo de las costas del Adriático y del Jónico, los rayos son más densos sobre el mar entre Italia y Grecia, y las condiciones favorables a tormentas llegan muy al sur.",points:["Días de tormenta: con qué frecuencia se producen, 2013–2025","Densidad de rayos: con qué violencia","Potencial de tormentas: dónde pueden formarse, 1994–2023"],image:"days",alt:"Días de tormenta en el Mediterráneo en septiembre.",coords:"40°00′N · 015°00′E",caption:"Días de tormenta, Mediterráneo, septiembre",panels:[{label:"Días de tormenta",image:"days",alt:"Días de tormenta en el Mediterráneo en septiembre.",caption:"Días de tormenta, Mediterráneo, septiembre"},{label:"Densidad de rayos",image:"density",alt:"Densidad de rayos en el Mediterráneo en septiembre.",caption:"Densidad de rayos, Mediterráneo, septiembre"},{label:"Potencial de tormentas",image:"potential",alt:"Potencial de tormentas en el Mediterráneo en septiembre.",caption:"Potencial de tormentas, Mediterráneo, septiembre"}]},{id:"terrain",number:"12",kicker:"Exposición del terreno",title:"Misma bahía, distinta protección.",text:"El Riesgo de tormenta te dice qué bahía. La Exposición del terreno te dice qué lado: las colinas de alrededor pueden proteger un fondeadero de los rayos, y la capa muestra lo bien que el terreno protege cada parte de una bahía, para que elijas el mejor sitio antes de fondear.",points:["Compara puntos dentro de una misma bahía","Datos de elevación detallados de 30 m"],image:"terrain",alt:"Exposición del terreno en la bahía de Komiža, en la isla de Vis, Croacia.",coords:"43°02′N · 016°05′E",caption:"Bahía de Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Poca protección del terreno circundante.",color:"#762a83"},{x:53.84,y:26.35,text:"Cierta protección del terreno circundante.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Mayor protección del terreno circundante.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Fondo marino",title:"¿Arena o posidonia?",text:"Antes de fondear: la capa Fondo marino muestra arena, fango, roca, praderas marinas y coral a lo largo de la costa, del Mediterráneo a los trópicos. En la bahía de Palma una amplia franja de pradera bordea la costa y la arena queda más afuera. Fondear sobre posidonia está prohibido en cada vez más lugares, así que conviene saberlo antes de llegar.",points:["Arena, fango, roca, praderas y coral","Europa y costas tropicales poco profundas","Abierto a todos"],image:"seabed",alt:"El fondo marino en la bahía de Palma, Mallorca: una amplia franja de pradera junto a la costa, arena más afuera, con el inspector mostrando pradera marina.",coords:"39°30′N · 002°37′E",caption:"Fondo marino, bahía de Palma"}],story:{kicker:"Nuestra historia",title:"Nació de un buen susto.",text:"En octubre de 2024, nuestra familia navegaba por el mar Jónico cuando un rayo cayó justo al lado de nuestro barco. Ese momento nos dejó una pregunta sencilla: ¿estamos más seguros aquí o al otro lado de la bahía? IncusGrid empezó como la respuesta — y se convirtió en un mapa de todo lo que nos habría gustado saber antes de aquella temporada.",more:"Lee la historia completa (en inglés)",link:`${e}/blog/introducing-incusgrid/`,place:"Igumenitsa, Grecia",note:"Donde nació la idea"},fromBlog:{kicker:"Del blog",title:"Historias de datos desde el agua.",all:"Todos los artículos",note:"Artículos en inglés."},devices:{kicker:"Web & Android",title:"En cubierta o en la mesa de cartas.",text:"Usa IncusGrid en cualquier navegador o instala la app para Android. Busca tu zona de navegación y explórala en el móvil, la tableta o el portátil.",points:["Sin instalar nada en el navegador","App para Android en Google Play","Disponible en 19 idiomas"],web:"Abrir en el navegador",android:"Disponible en Google Play",phoneAlt:"La app de IncusGrid para Android mostrando pausas de barcos alrededor de las islas Jónicas."},final:{title:"Planifica tu próxima temporada. Y tu próxima travesía.",text:"Rutas, pausas de barcos, viento, oleaje y rayos a partir de muchos años de datos reales, más el pronóstico a 10 días y el planificador de travesías — en un solo mapa.",cta:"Abrir el mapa"},disclaimerLabel:"Precaución",disclaimer:"IncusGrid está hecho para planificar y no es una ayuda a la navegación. Las rutas se dibujan de forma esquemática, y las pausas de barcos se deducen de interrupciones en los reportes de posición, no de amarres confirmados. El planificador de travesías usa una polar simplificada, sin corrientes ni el efecto del oleaje en la velocidad del barco, y no te lleva hasta dentro del puerto. Consulta siempre los pronósticos actuales, las cartas náuticas oficiales y las condiciones locales antes de salir a navegar.",footer:{blog:"Blog",legal:"Aviso legal",privacy:"Política de privacidad",terms:"Términos del servicio",cookies:"Configuración de cookies",support:"Soporte",madeWith:"Hecho con",made:"en Portugal",englishOnly:"Páginas legales en inglés."}},p={path:"/sv",htmlLang:"sv",ogLocale:"sv_SE",meta:{title:"IncusGrid · Lokalkännedom och väderroutning för seglare",description:"Seglingsrutter och båtpauser från verkliga överfarter, år av vind-, våg- och blixtdata, plus 10-dagarsprognosen och väderroutning för din båt. Planera säsongen och seglatsen på en karta.",keywords:"väderroutning, weather routing, seglatsplanering, ruttplanerare, avgångsplanering, seglingsväder, vindprognos, polardiagram, seglingsrutter, långsegling, segla jorden runt, ankarplats, gästhamn, marina, vinterförvaring, vindstatistik, sjögång, vågor, dyning, blixtar, åska, åskrisk, blixttäthet, segling, segelbåt, ruttplanering, havsbotten, sjögräs, posidonia, ankringsbotten"},nav:{routes:"Rutter",passages:"Seglatser",stays:"Båtpauser",weather:"Väder",thunderstorms:"Blixtar",blog:"Blogg",openApp:"Öppna kartan"},hero:{position:"Sailing intelligence",lead:"IncusGrid gör år av data till den lokalkännedom varje besättning behöver innan man kastar loss: verkliga båtrörelser, vind, vågor och blixtar på en karta. Dessutom prognosen för de kommande 10 dagarna och en seglatsplanerare som routar din båt genom den prognostiserade vinden, timme för timme, med byar och vågor längs vägen.",ctaApp:"Öppna kartan",ctaAndroid:"Android-app",heroAlt:"Seglingsrutter i Karibiska havet, från Hispaniola via Små Antillerna till Sydamerikas kust, ritade utifrån verkliga överfarter med långfärdsbåtar.",heroCaption:"Seglingsrutter, Karibiska havet · alla månader",notes:[{label:"Båtar",value:"Tusentals"},{label:"Rörelser",value:"Miljoner"},{label:"Blixtnedslag",value:"Miljarder"},{label:"Prognos",value:"10 dagar"},{label:"Täckning",value:"Hela världen"}]},contrast:{kicker:"Säsong och prognos",title:"Säsongen berättar vilken månad. Prognosen berättar vilken dag.",text:"Vilken överfart gör besättningar i juni? Var övervintrar båtarna? Vilken månad kommer meltemin, och vilken vinterhamn har färre åskväder i november? Svar som syns först när man tittar på många år samtidigt. När avfärden närmar sig räknar seglatsplaneraren ut på 10-dagarsprognosen när du ska kasta loss och när du är framme."},chapters:[{id:"routes",number:"01",kicker:"Seglingsrutter",title:"Planera överfarter med tusentals besättningars erfarenhet.",text:"Tusentals verkliga överfarter visar när en överfart är rimlig, i vilken riktning, och var besättningar kastar loss och kommer fram. Förhärskande vindar, bra ställen att vänta in ett väderfönster och en säker angöring efter en natt till sjöss finns redan inbyggda. Från Sicilien till Joniska öarna går till exempel de flesta båtar österut i maj och juni och seglar tillbaka i september.",points:["Popularitet per månad och riktning","De populäraste rutterna i din aktuella kartvy","Dela en rutt med din besättning"],image:"route-detail",alt:"Rutten från Sicilien till Joniska öarna vald, med hur populär den är varje månad och i varje riktning.",coords:"38°12′N · 017°30′E",caption:"Sicilien → Joniska öarna, per månad och riktning"},{id:"route-wind",number:"02",kicker:"Vind längs rutten",title:"Känn vinden innan du kastar loss.",text:"Varje rutt visar vinden du kan räkna med, månad för månad: varifrån den kommer, hur hårt den blåser, hur stor del av överfarten du seglar i bidevind, halvvind eller undanvind, och hur ofta sjön förblir lugn. Från Sicilien till Joniska öarna i maj: vind från nordväst, 3 Beaufort, mer än halva vägen i undanvind.",points:["Förhärskande vind och vindstyrka i Beaufort för varje månad","Bidevind, halvvind eller undanvind på ruttens kurs","Sjögång längs rutten"],image:"route-wind",alt:"Ruttkortet för Sicilien till Joniska öarna: förhärskande vind, vindstyrka i Beaufort, styrka, kurs och sjögång för varje månad, med maj valt.",coords:"",caption:"Sicilien → Joniska öarna, vind i maj",card:!0},{id:"passage",number:"03",kicker:"Seglatsplanerare · väderroutning",title:"Vet när du är framme innan du kastar loss.",text:"Välj start och mål, välj din båt, så hittar seglatsplaneraren en snabb rutt genom den prognostiserade vinden de kommande 10 dagarna, timme för timme, med byar och vågor längs vägen. Från Leros till Rhodos, 86 sjömil, avgång onsdag kl. 20:00: en natt i undanvind med högst 15 knop vind, utan motor, framme på torsdagen strax före elva.",points:["Ankomst, starkaste vind, byar och vågor, timmar för segel och för motor","För din båt: typ och storlek, eller ditt eget polardiagram","Under seglatsen din position bredvid planen, och resten av rutten omräknad"],image:"passage",alt:"Seglatsplaneraren med rutten från Leros till Rhodos på vindprognosen: waypoints med klockslag, båten söder om Kos på natten, och bredvid ankomst, starkaste vind och timmar för segel och motor.",coords:"36°48′N · 027°50′E",caption:"Leros → Rhodos, avgång onsdag 20:00 · prognos från 31 oktober"},{id:"departures",number:"04",kicker:"Jämför avgångar",title:"Rätt dag att kasta loss.",text:"Planeraren beräknar samma seglats för upp till tolv avgångar med sex timmars mellanrum och ställer ankomst, restid, starkaste vind och tid för motor sida vid sida. Lämnar du Leros på onsdagsmorgonen är du på Rhodos vid midnatt; lämnar du på onsdagskvällen, nästa morgon. Stjärnan markerar avgången med minst tid för motor och i bidevind.",points:["Upp till tolv avgångar, var sjätte timme","Tryck på en rad för att se dess rutt","Spara en seglats eller dela den med besättningen, alltid med den senaste prognosen"],image:"departures",alt:"Avgångstabellen för Leros till Rhodos, var sjätte timme från onsdag 08:00: ankomst, restid, starkaste vind och timmar för motor, med bästa avgång, torsdag kl. 14:00, markerad med en stjärna.",coords:"",caption:"Leros → Rhodos, avgångar från onsdag 08:00",card:!0},{id:"stays",number:"05",kicker:"Båtpauser",title:"Där andra båtar ligger.",text:"Var lämnar besättningar båten i två månader på sommaren, och var tillbringar de vintern? Båtpauser visar hamnarna och ankarplatserna där båtar gjort uppehåll — från några dagar till mer än sex månader, per säsong.",points:["Filtrera på hur länge båtarna ligger","Se vilka månader båtar ligger på en plats","Hitta populära vinterhamnar"],image:"stay-detail",alt:"Preveza: typisk vistelse och de månader då båtar ligger där.",coords:"38°57′N · 020°45′E",caption:"Preveza, vistelsens längd och säsong"},{id:"hotspots",number:"06",kicker:"Hotspots",title:"Hitta den lugnare ankringsplatsen.",text:"Var trängs båtarna i augusti, och var finns det fortfarande plats? Hotspots visar månad för månad hur livligt varje seglingsområde är. Joniska havet och Saroniska viken lyser, medan Andros, en dagsetapp från Aten, förblir lugnt.",points:["Från lugnt till fullt","Årets alla månader","Livligaste och lugnaste månader på varje punkt"],image:"hotspots",alt:"Hur livliga de grekiska seglingsområdena är i augusti: fullt kring Joniska öarna och i Saroniska viken, lugnt utanför Andros, med punktinspektören öppen.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Grekland, augusti"},{id:"spot",number:"07",kicker:"Platsprofil",title:"Allt om en plats, i en överblick.",text:"Håll fingret på en plats på kartan eller högerklicka på den, så samlar platsprofilen allt för den månad du väljer: vind och sjögång, åska, hur väl terrängen skyddar platsen och båtpauserna och rutterna i närheten. Gaios på Paxos i september: oftast stiltje eller svag vind, lugn till lätt sjö och åska ungefär var sjätte dag. Månadsraden visar att november är månaden med mest åska.",points:["Vind, sjögång och åska för en plats och månad","Båtpauser och rutter inom 5 nautiska mil","Varje månad bedömd i en överblick, som länk till din besättning"],image:"spot",alt:"Platsprofilen för Gaios på Paxos i september: vind och sjögång, åska, terrängens skydd, båtpauser och rutter i närheten och varje månad bedömd i en överblick.",coords:"",caption:"Gaios, Paxos, september",card:!0},{id:"wind",number:"08",kicker:"Vind",title:"Hur mycket nordlig vind kan du räkna med?",text:"Välj riktning och månad: i juli blir centrala Egeiska havet djupblått. Det är meltemin. Tryck på en punkt nära Mykonos så ser du att vinden blåser från norr under 60 % av alla timmar i juli, eller mer.",points:["Styrka och riktning för varje månad","Vind efter tid på dygnet","Tryck på en punkt för att se siffrorna"],image:"wind",alt:"Hur ofta vinden blåser från norr i Egeiska havet i juli, med punktdetaljerna öppna nära Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vind från norr, Egeiska havet, juli"},{id:"waves",number:"09",kicker:"Vågor",title:"Känn sjögången innan du ger dig iväg.",text:"Hur många dagar per månad har vågor på 2,5 m eller mer? I januari syns tydligt hur långt mistralen når ut över Lionbukten.",points:["Från lugn till mycket grov sjö","Dyning och kort, brant sjö","Årets alla månader"],image:"waves",alt:"Dagar med grov sjö i västra Medelhavet i januari.",coords:"41°00′N · 005°00′E",caption:"Dagar med grov sjö, västra Medelhavet, januari"},{id:"risk",number:"10",kicker:"Åskrisk",title:"Vilken hamn har färre åskväder?",text:"Åskrisk väger samman hur ofta det åskar, hur kraftiga åskvädren är och hur berg, uddar och öppet hav påverkar dem — för varje månad och ända ner till enskilda vikar. Tryck på en plats och sedan på en till, så ser du hur mycket högre eller lägre risk den andra har. Preveza och Messolonghi är båda populära för övervintring: i november har Messolonghi 27 % lägre åskrisk.",points:["Åskdagar, blixttäthet och terräng i ett värde","Skillnader ända ner till enskilda vikar","Tryck på två platser för att jämföra dem"],image:"risk",alt:"Åskrisk i Joniska havet i november: först Preveza, sedan Messolonghi, och punktinspektören visar 27 % lägre risk.",coords:"38°40′N · 021°10′E",caption:"Preveza vs. Messolonghi, november",markers:[{x:34.09,y:27.12,text:"Preveza, vald först: riskvärde 50 i november.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, 47 M bort: 27 % lägre åskrisk.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Blixtdata",title:"Hur ofta, hur kraftigt, hur troligt.",text:"Bakom risken finns tre lager som du också kan öppna var för sig, på samma skala varje månad. I september visar Medelhavet varför du behöver alla tre: åskvädren är vanligast längs Adriatiska och Joniska havets kuster, blixtarna är tätast över havet mellan Italien och Grekland, och åskgynnsamma förhållanden når långt söderut.",points:["Åskdagar: hur ofta det åskar, 2013–2025","Blixttäthet: hur kraftiga åskvädren är","Åskpotential: var åska kan bildas, 1994–2023"],image:"days",alt:"Åskdagar i Medelhavet i september.",coords:"40°00′N · 015°00′E",caption:"Åskdagar, Medelhavet, september",panels:[{label:"Åskdagar",image:"days",alt:"Åskdagar i Medelhavet i september.",caption:"Åskdagar, Medelhavet, september"},{label:"Blixttäthet",image:"density",alt:"Blixttäthet i Medelhavet i september.",caption:"Blixttäthet, Medelhavet, september"},{label:"Åskpotential",image:"potential",alt:"Åskpotential i Medelhavet i september.",caption:"Åskpotential, Medelhavet, september"}]},{id:"terrain",number:"12",kicker:"Terrängexponering",title:"Samma vik, olika skydd.",text:"Åskrisk visar vilken vik. Terrängexponering visar vilken sida av den: omgivande kullar kan skärma av en ankarplats mot blixtar, och lagret visar hur väl terrängen skyddar varje del av en vik — så att du kan välja den bättre platsen innan ankaret går.",points:["Jämför platser i samma vik","Detaljerade höjddata med 30 m upplösning"],image:"terrain",alt:"Terrängexponering i Komižaviken på Vis, Kroatien.",coords:"43°02′N · 016°05′E",caption:"Komižaviken, Vis",markers:[{x:56.9,y:57.69,text:"Liten avskärmning från omgivande terräng.",color:"#762a83"},{x:53.84,y:26.35,text:"Viss avskärmning från omgivande terräng.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Större avskärmning från omgivande terräng.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Havsbotten",title:"Sand eller sjögräs?",text:"Innan ankaret går i: lagret Havsbotten visar sand, lera, berg, sjögräs och korall längs kusten, från Medelhavet till tropikerna. I Palmabukten löper ett brett band av sjögräs längs stranden och sanden ligger längre ut. Att ankra på posidonia är förbjudet på allt fler platser, så det lönar sig att veta innan du kommer fram.",points:["Sand, lera, berg, sjögräs och korall","Europa och grunda tropiska kuster","Öppet för alla"],image:"seabed",alt:"Havsbotten i Palmabukten, Mallorca: ett brett band av sjögräs längs stranden, sand längre ut, punktinspektören visar sjögräs.",coords:"39°30′N · 002°37′E",caption:"Havsbotten, Palmabukten"}],story:{kicker:"Vår historia",title:"Det började med ett nära ögat.",text:"I oktober 2024 seglade vår familj i Joniska havet när blixten slog ner precis bredvid båten. Det ögonblicket väckte en enkel fråga: ligger vi säkrare här, eller på andra sidan viken? IncusGrid började som svaret — och växte till en karta med allt vi hade velat veta före den säsongen.",more:"Läs hela historien (på engelska)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Grekland",note:"Där idén föddes"},fromBlog:{kicker:"Från bloggen",title:"Datahistorier från sjön.",all:"Alla inlägg",note:"Inlägg på engelska."},devices:{kicker:"Webb & Android",title:"På däck eller vid navbordet.",text:"Använd IncusGrid i valfri webbläsare eller installera Android-appen. Sök fram ditt seglingsområde och utforska det i mobilen, på surfplattan eller datorn.",points:["Ingen installation i webbläsaren","Android-app på Google Play","Finns på 19 språk"],web:"Öppna i webbläsaren",android:"Hämta på Google Play",phoneAlt:"IncusGrids Android-app med båtpauser runt Joniska öarna."},final:{title:"Planera nästa säsong. Och nästa seglats.",text:"Rutter, båtpauser, vind, vågor och blixtar från många års verkliga data, plus 10-dagarsprognosen och seglatsplaneraren — på en karta.",cta:"Öppna kartan"},disclaimerLabel:"Observera",disclaimer:"IncusGrid är gjort för planering och är inget navigationshjälpmedel. Rutterna är schematiskt ritade, och båtpauser härleds ur uppehåll i båtarnas positionsrapporter, inte ur bekräftade båtplatser. Seglatsplaneraren använder ett enkelt polardiagram, utan strömmar eller vågornas inverkan på båtens fart, och routar dig inte in i hamnen. Kontrollera alltid aktuella prognoser, officiella sjökort och lokala förhållanden innan du går till sjöss.",footer:{blog:"Blogg",legal:"Juridisk information",privacy:"Integritetspolicy",terms:"Användarvillkor",cookies:"Cookieinställningar",support:"Support",madeWith:"Gjord med",made:"i Portugal",englishOnly:"Juridiska sidor på engelska."}},g={path:"/da",htmlLang:"da",ogLocale:"da_DK",meta:{title:"IncusGrid · Lokalkendskab og vejrrouting for sejlere",description:"Sejlruter og bådpauser fra rigtige overfarter, mange års vind-, bølge- og lyndata, plus 10-dages-prognosen og vejrrouting til din båd. Planlæg sæsonen og din passage på ét kort.",keywords:"vejrrouting, weather routing, passageplanlægning, ruteplanlægger, afgangsplanlægning, sejlervejr, vindprognose, polardiagram, sejlruter, langtursejlads, jordomsejling, ankerplads, lystbådehavn, marina, vinteroplag, vindstatistik, søgang, bølger, dønning, lyn, tordenvejr, tordenvejrsrisiko, lyntæthed, sejlads, sejlbåd, ruteplanlægning, havbund, ålegræs, posidonia, ankerbund"},nav:{routes:"Ruter",passages:"Passager",stays:"Bådpauser",weather:"Vejr",thunderstorms:"Lyn",blog:"Blog",openApp:"Åbn kortet"},hero:{position:"Sailing intelligence",lead:"IncusGrid gør års data til det lokalkendskab, enhver besætning har brug for, før den kaster los: rigtige bådbevægelser, vind, bølger og lyn på ét kort. Dertil prognosen for de næste 10 dage og en passageplanlægger, der router din båd gennem den forventede vind, time for time, med vindstød og bølger undervejs.",ctaApp:"Åbn kortet",ctaAndroid:"Android-app",heroAlt:"Sejlruter i Det Caribiske Hav, fra Hispaniola over De Små Antiller til Sydamerikas kyst, tegnet ud fra rigtige overfarter med langtursbåde.",heroCaption:"Sejlruter, Det Caribiske Hav · alle måneder",notes:[{label:"Både",value:"Tusindvis"},{label:"Bevægelser",value:"Millioner"},{label:"Lynnedslag",value:"Milliarder"},{label:"Prognose",value:"10 dage"},{label:"Dækning",value:"Hele verden"}]},contrast:{kicker:"Sæson og prognose",title:"Sæsonen fortæller dig hvilken måned. Prognosen fortæller dig hvilken dag.",text:"Hvilken overfart tager besætninger i juni? Hvor overvintrer bådene? Hvilken måned bringer meltemien, og hvilken vinterhavn får mindre tordenvejr i november? Svar, der først viser sig, når man ser på mange år på én gang. Når afgangen nærmer sig, regner passageplanlæggeren ud fra 10-dages-prognosen, hvornår du skal af sted, og hvornår du er fremme."},chapters:[{id:"routes",number:"01",kicker:"Sejlruter",title:"Planlæg overfarter med tusindvis af besætningers erfaring.",text:"Tusindvis af rigtige overfarter viser, hvornår en overfart giver mening, i hvilken retning, og hvor besætninger kaster los og ankommer. De fremherskende vinde, gode steder at vente på et vejrvindue og en sikker ansejling efter en nat på havet er allerede bygget ind. Fra Sicilien til De Joniske Øer sejler de fleste både for eksempel mod øst i maj og juni og tilbage igen i september.",points:["Popularitet pr. måned og retning","De mest populære ruter i dit aktuelle kortudsnit","Del en rute med din besætning"],image:"route-detail",alt:"Ruten fra Sicilien til De Joniske Øer valgt, med hvor populær den er i hver måned og retning.",coords:"38°12′N · 017°30′E",caption:"Sicilien → De Joniske Øer, efter måned og retning"},{id:"route-wind",number:"02",kicker:"Vind langs ruten",title:"Kend vinden, før du kaster los.",text:"Hver rute viser den vind, du kan forvente, måned for måned: hvor den kommer fra, hvor hårdt den blæser, hvor meget af overfarten du sejler i bidevind, halvvind eller rum vind, og hvor ofte søen forbliver rolig. Fra Sicilien til De Joniske Øer i maj: vind fra nordvest, 3 Beaufort, mere end halvdelen af vejen i rum vind.",points:["Fremherskende vind og vindstyrke i Beaufort for hver måned","Bidevind, halvvind eller rum vind på rutens kurs","Søgang langs ruten"],image:"route-wind",alt:"Rutekortet for Sicilien til De Joniske Øer: fremherskende vind, vindstyrke i Beaufort, styrke, kurs og søgang for hver måned, med maj valgt.",coords:"",caption:"Sicilien → De Joniske Øer, vind i maj",card:!0},{id:"passage",number:"03",kicker:"Passageplanlægger · vejrrouting",title:"Vid, hvornår du er fremme, før du kaster los.",text:"Vælg start og mål, vælg din båd, og passageplanlæggeren finder en hurtig rute gennem den forventede vind for de næste 10 dage, time for time, med vindstød og bølger undervejs. Fra Leros til Rhodos, 86 sømil, afgang onsdag kl. 20:00: én nat i rum vind med højst 15 knob, uden motor, fremme torsdag lige før elleve.",points:["Ankomst, kraftigste vind, vindstød og bølger, timer for sejl og for motor","Til din båd: type og størrelse, eller din egen polar","Undervejs din position ved siden af planen, og resten af ruten beregnet igen"],image:"passage",alt:"Passageplanlæggeren med ruten fra Leros til Rhodos på vindprognosen: waypoints med klokkeslæt, båden syd for Kos om natten, og ved siden af ankomst, kraftigste vind og timer for sejl og motor.",coords:"36°48′N · 027°50′E",caption:"Leros → Rhodos, afgang onsdag 20:00 · prognose fra 31. oktober"},{id:"departures",number:"04",kicker:"Sammenlign afgange",title:"Den rigtige dag at kaste los.",text:"Planlæggeren beregner den samme passage for op til tolv afgange med seks timers mellemrum og stiller ankomst, varighed, kraftigste vind og tid for motor op side om side. Sejler du fra Leros onsdag morgen, er du på Rhodos ved midnat; sejler du onsdag aften, næste morgen. Stjernen markerer afgangen med mindst tid for motor og i bidevind.",points:["Op til tolv afgange, hver sjette time","Tryk på en række for at se dens rute","Gem en passage, eller del den med besætningen, altid med den nyeste prognose"],image:"departures",alt:"Afgangstabellen for Leros til Rhodos, hver sjette time fra onsdag 08:00: ankomst, varighed, kraftigste vind og timer for motor, med den bedste afgang, torsdag kl. 14:00, markeret med en stjerne.",coords:"",caption:"Leros → Rhodos, afgange fra onsdag 08:00",card:!0},{id:"stays",number:"05",kicker:"Bådpauser",title:"Hvor andre både ligger.",text:"Hvor lader besætninger båden ligge i to måneder om sommeren, og hvor tilbringer de vinteren? Bådpauser viser de havne og ankerpladser, hvor både har holdt pause — fra nogle få dage til mere end seks måneder, efter sæson.",points:["Filtrer efter opholdets længde","Se, i hvilke måneder både ligger et sted","Find populære vinterhavne"],image:"stay-detail",alt:"Preveza: typisk opholdslængde og de måneder, hvor både ligger der.",coords:"38°57′N · 020°45′E",caption:"Preveza, opholdslængde og sæson"},{id:"hotspots",number:"06",kicker:"Hotspots",title:"Find den roligere ankerplads.",text:"Hvor trænges bådene i august, og hvor er der stadig plads? Hotspots viser måned for måned, hvor travlt hvert sejlområde er. Det Joniske Hav og Saronske Bugt lyser op, mens Andros, en dagssejlads fra Athen, forbliver roligt.",points:["Fra roligt til fyldt","Hver måned i året","Travleste og roligste måneder på ethvert punkt"],image:"hotspots",alt:"Hvor travle de græske sejlområder er i august: fyldt omkring De Joniske Øer og i Saronske Bugt, roligt ud for Andros, med punktinspektøren åben.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Grækenland, august"},{id:"spot",number:"07",kicker:"Stedprofil",title:"Alt om ét sted, i ét overblik.",text:"Hold fingeren på et sted på kortet, eller højreklik på det, så samler stedprofilen alt for den måned, du vælger: vind og søgang, tordenvejr, hvor godt terrænet beskytter stedet, og bådpauserne og ruterne i nærheden. Gaios på Paxos i september: for det meste stille eller svag vind, rolig til let sø og tordenvejr omkring hver sjette dag. Månedsbjælken viser, at november er måneden med mest tordenvejr.",points:["Vind, søgang og tordenvejr for ét sted og én måned","Bådpauser og ruter inden for 5 sømil","Hver måned vurderet i ét overblik, som link til din besætning"],image:"spot",alt:"Stedprofilen for Gaios på Paxos i september: vind og søgang, tordenvejr, terrænets beskyttelse, bådpauser og ruter i nærheden og hver måned vurderet i ét overblik.",coords:"",caption:"Gaios, Paxos, september",card:!0},{id:"wind",number:"08",kicker:"Vind",title:"Hvor meget nordenvind skal du regne med?",text:"Vælg en retning og en måned: i juli bliver det centrale Ægæiske Hav dybblåt. Det er meltemien. Tryk på et punkt ved Mykonos, og du ser, at vinden blæser fra nord i 60 % af alle timer i juli eller mere.",points:["Styrke og retning for hver måned","Vind efter tid på døgnet","Tryk på et punkt for at se tallene"],image:"wind",alt:"Hvor ofte vinden blæser fra nord i Det Ægæiske Hav i juli, med punktdetaljerne åbne ved Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vind fra nord, Det Ægæiske Hav, juli"},{id:"waves",number:"09",kicker:"Bølger",title:"Kend søgangen, før du stikker til søs.",text:"Hvor mange dage om måneden giver bølger på 2,5 m eller mere? I januar ser man tydeligt, hvor langt mistralen rækker ud over Lionbugten.",points:["Fra rolig til meget hård sø","Dønning og kort, stejl sø","Hver måned i året"],image:"waves",alt:"Dage med hård sø i det vestlige Middelhav i januar.",coords:"41°00′N · 005°00′E",caption:"Hårde dage, det vestlige Middelhav, januar"},{id:"risk",number:"10",kicker:"Tordenvejrsrisiko",title:"Hvilken havn får mindre tordenvejr?",text:"Tordenvejrsrisiko samler, hvor ofte der er tordenvejr, hvor voldsomt det er, og hvordan bjerge, næs og åbent hav former det — for hver måned og helt ned til den enkelte bugt. Tryk på ét sted og derefter på et andet, og du ser, hvor meget mere eller mindre risiko det andet har. Preveza og Messolonghi er begge populære steder at overvintre: i november har Messolonghi 27 % lavere tordenvejrsrisiko.",points:["Tordendage, lyntæthed og terræn i én værdi","Forskelle helt ned til den enkelte bugt","Tryk på to steder for at sammenligne dem"],image:"risk",alt:"Tordenvejrsrisiko i Det Joniske Hav i november: først Preveza, derefter Messolonghi, og punktinspektøren viser 27 % lavere risiko.",coords:"38°40′N · 021°10′E",caption:"Preveza vs. Messolonghi, november",markers:[{x:34.09,y:27.12,text:"Preveza, valgt først: risikoværdi 50 i november.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, 47 sm væk: 27 % lavere tordenvejrsrisiko.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Lyndata",title:"Hvor ofte, hvor voldsomt, hvor sandsynligt.",text:"Bag risikoen ligger tre lag, som du også kan åbne hver for sig, på samme skala i alle måneder. I september viser Middelhavet, hvorfor du har brug for alle tre: tordenvejr er hyppigst langs kysterne af Adriaterhavet og Det Joniske Hav, lynene er tættest over havet mellem Italien og Grækenland, og forhold, der fremmer tordenvejr, rækker langt mod syd.",points:["Tordendage: hvor ofte der er tordenvejr, 2013–2025","Lyntæthed: hvor voldsomt det er","Tordenpotentiale: hvor tordenvejr kan opstå, 1994–2023"],image:"days",alt:"Tordendage i Middelhavet i september.",coords:"40°00′N · 015°00′E",caption:"Tordendage, Middelhavet, september",panels:[{label:"Tordendage",image:"days",alt:"Tordendage i Middelhavet i september.",caption:"Tordendage, Middelhavet, september"},{label:"Lyntæthed",image:"density",alt:"Lyntæthed i Middelhavet i september.",caption:"Lyntæthed, Middelhavet, september"},{label:"Tordenpotentiale",image:"potential",alt:"Tordenpotentiale i Middelhavet i september.",caption:"Tordenpotentiale, Middelhavet, september"}]},{id:"terrain",number:"12",kicker:"Terræneksponering",title:"Samme bugt, forskelligt læ.",text:"Tordenvejrsrisiko fortæller dig, hvilken bugt. Terræneksponering fortæller dig, hvilken side af den: omkringliggende bakker kan skærme en ankerplads mod lyn, og laget viser, hvor godt terrænet beskytter hver del af en bugt — så du kan vælge det bedste sted, før ankeret går.",points:["Sammenlign steder i samme bugt","Detaljerede højdedata med 30 m opløsning"],image:"terrain",alt:"Terræneksponering i Komiža-bugten på Vis, Kroatien.",coords:"43°02′N · 016°05′E",caption:"Komiža-bugten, Vis",markers:[{x:56.9,y:57.69,text:"Ringe afskærmning fra det omgivende terræn.",color:"#762a83"},{x:53.84,y:26.35,text:"Nogen afskærmning fra det omgivende terræn.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Større afskærmning fra det omgivende terræn.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Havbund",title:"Sand eller havgræs?",text:"Før ankeret ryger i: laget Havbund viser sand, mudder, klippe, havgræs og koral langs kysten, fra Middelhavet til troperne. I Palmabugten løber et bredt bælte af havgræs langs kysten, og sandet ligger længere ude. Ankring på posidonia er forbudt flere og flere steder, så det betaler sig at vide det, før du ankommer.",points:["Sand, mudder, klippe, havgræs og koral","Europa og lave tropiske kyster","Åbent for alle"],image:"seabed",alt:"Havbunden i Palmabugten, Mallorca: et bredt bælte af havgræs langs kysten, sand længere ude, punktinspektøren viser havgræs.",coords:"39°30′N · 002°37′E",caption:"Havbund, Palmabugten"}],story:{kicker:"Vores historie",title:"Født af et skræmmende øjeblik.",text:"I oktober 2024 sejlede vores familie i Det Joniske Hav, da lynet slog ned lige ved siden af vores båd. Det øjeblik rejste et enkelt spørgsmål: Ligger vi mere sikkert her eller på den anden side af bugten? IncusGrid begyndte som svaret — og voksede til et kort med alt det, vi gerne ville have vidst før den sæson.",more:"Læs hele historien (på engelsk)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Grækenland",note:"Hvor idéen blev født"},fromBlog:{kicker:"Fra bloggen",title:"Datahistorier fra vandet.",all:"Alle indlæg",note:"Indlæg på engelsk."},devices:{kicker:"Web & Android",title:"På dækket eller ved kortbordet.",text:"Brug IncusGrid i enhver browser, eller installér Android-appen. Søg dit sejlområde frem, og udforsk det på telefon, tablet eller bærbar.",points:["Ingen installation i browseren","Android-app på Google Play","Fås på 19 sprog"],web:"Åbn i browseren",android:"Hent den på Google Play",phoneAlt:"IncusGrids Android-app med bådpauser omkring De Joniske Øer."},final:{title:"Planlæg din næste sæson. Og din næste passage.",text:"Ruter, bådpauser, vind, bølger og lyn fra mange års rigtige data, plus 10-dages-prognosen og passageplanlæggeren — på ét kort.",cta:"Åbn kortet"},disclaimerLabel:"Bemærk",disclaimer:"IncusGrid er lavet til planlægning og er ikke et navigationshjælpemiddel. Ruterne er tegnet skematisk, og bådpauser er udledt af pauser i bådenes positionsmeldinger, ikke af bekræftede bådpladser. Passageplanlæggeren bruger en simpel polar uden strøm og uden bølgernes indvirkning på bådens fart, og den router dig ikke ind i havnen. Tjek altid aktuelle vejrudsigter, officielle søkort og de lokale forhold, før du stikker til søs.",footer:{blog:"Blog",legal:"Juridisk information",privacy:"Privatlivspolitik",terms:"Brugsvilkår",cookies:"Cookieindstillinger",support:"Support",madeWith:"Lavet med",made:"i Portugal",englishOnly:"Juridiske sider på engelsk."}},c={path:"/nb",htmlLang:"nb",ogLocale:"nb_NO",meta:{title:"IncusGrid · Lokalkunnskap og værruting for seilere",description:"Seilruter og båtpauser fra ekte seilaser, mange års data om vind, bølger og lyn, pluss 10-dagersvarselet og værruting for båten din. Planlegg sesongen og seilasen på ett kart.",keywords:"værruting, weather routing, seilasplanlegging, ruteplanlegging, avgangsplanlegging, seilvær, vindvarsel, polardiagram, seilruter, langtur, langturseiling, ankringsplass, gjestehavn, marina, vinteropplag, vindstatistikk, sjøgang, bølger, lyn, tordenvær, tordenværsrisiko, lyntetthet, turplanlegging, seilbåt, seiling Middelhavet, havbunn, sjøgress, posidonia, ankringsbunn"},nav:{routes:"Ruter",passages:"Seilaser",stays:"Båtpauser",weather:"Vær",thunderstorms:"Lyn",blog:"Blogg",openApp:"Åpne kartet"},hero:{position:"Sailing intelligence",lead:"IncusGrid gjør år med data om til lokalkunnskapen ethvert mannskap trenger før de kaster loss: ekte båtbevegelser, vind, bølger og lyn på ett kart. I tillegg varselet for de neste 10 dagene og en seilasplanlegger som ruter båten din gjennom den varslede vinden, time for time, med vindkast og bølger underveis.",ctaApp:"Åpne kartet",ctaAndroid:"Android-app",heroAlt:"Seilruter i Det karibiske hav, fra Hispaniola til De små Antiller og kysten av Sør-Amerika, tegnet ut fra ekte seilaser med langturbåter.",heroCaption:"Seilruter, Det karibiske hav · alle måneder",notes:[{label:"Båter",value:"Tusenvis"},{label:"Bevegelser",value:"Millioner"},{label:"Lynnedslag",value:"Milliarder"},{label:"Varsel",value:"10 dager"},{label:"Dekning",value:"Hele verden"}]},contrast:{kicker:"Sesong og varsel",title:"Sesongen forteller deg hvilken måned. Varselet forteller deg hvilken dag.",text:"Hvilken overfart tar mannskapene i juni? Hvor ligger båtene om vinteren? Hvilken måned bringer meltemien, og hvilken vinterhavn får minst tordenvær i november? Svar som først viser seg når du ser mange år under ett. Når avreisen nærmer seg, regner seilasplanleggeren ut på 10-dagersvarselet når du bør legge ut og når du er fremme."},chapters:[{id:"routes",number:"01",kicker:"Seilruter",title:"Planlegg overfarter med erfaringen til tusenvis av mannskaper.",text:"Tusenvis av ekte seilaser viser når en overfart gir mening, i hvilken retning, og hvor mannskaper legger ut og kommer fram. De rådende vindene, gode steder å vente på et værvindu og en trygg landkjenning etter en natt på sjøen ligger allerede i dataene. Fra Sicilia til De joniske øyer seiler for eksempel de fleste båtene østover i mai og juni og tilbake i september.",points:["Popularitet per måned og retning","De mest populære rutene i kartutsnittet ditt","Del en rute med mannskapet ditt"],image:"route-detail",alt:"Ruten fra Sicilia til De joniske øyer valgt, med hvor populær den er i hver måned og retning.",coords:"38°12′N · 017°30′E",caption:"Sicilia → De joniske øyer, per måned og retning"},{id:"route-wind",number:"02",kicker:"Vind langs ruten",title:"Kjenn vinden før du legger ut.",text:"Hver rute viser vinden du kan vente deg, måned for måned: hvor den kommer fra, hvor hardt den blåser, hvor mye av overfarten du seiler i bidevind, halvvind eller undavind, og hvor ofte sjøen holder seg rolig. Fra Sicilia til De joniske øyer i mai: vind fra nordvest, 3 Beaufort, mer enn halve veien i undavind.",points:["Rådende vind og vindstyrke i Beaufort for hver måned","Bidevind, halvvind eller undavind på rutens kurs","Sjøgang langs ruten"],image:"route-wind",alt:"Rutekortet for Sicilia til De joniske øyer: rådende vind, vindstyrke i Beaufort, styrke, kurs og sjøgang for hver måned, med mai valgt.",coords:"",caption:"Sicilia → De joniske øyer, vind i mai",card:!0},{id:"passage",number:"03",kicker:"Seilasplanlegger · værruting",title:"Vit når du er fremme før du kaster loss.",text:"Velg start og mål, velg båten din, så finner seilasplanleggeren en rask rute gjennom den varslede vinden de neste 10 dagene, time for time, med vindkast og bølger underveis. Fra Leros til Rhodos, 86 nautiske mil, avgang onsdag kl. 20:00: én natt i undavind med maks 15 knop vind, uten motor, fremme torsdag like før elleve.",points:["Ankomst, sterkeste vind, vindkast og bølger, timer for seil og for motor","For båten din: type og størrelse, eller ditt eget polardiagram","Underveis posisjonen din ved siden av planen, og resten av ruten beregnet på nytt"],image:"passage",alt:"Seilasplanleggeren med ruten fra Leros til Rhodos på vindvarselet: veipunkter med klokkeslett, båten sør for Kos om natten, og ved siden av ankomst, sterkeste vind og timer for seil og motor.",coords:"36°48′N · 027°50′E",caption:"Leros → Rhodos, avgang onsdag 20:00 · varsel fra 31. oktober"},{id:"departures",number:"04",kicker:"Sammenlign avganger",title:"Riktig dag å kaste loss.",text:"Planleggeren beregner den samme seilasen for opptil tolv avganger med seks timers mellomrom og stiller opp ankomst, varighet, sterkeste vind og tid for motor side om side. Legger du ut fra Leros onsdag morgen, er du på Rhodos ved midnatt; legger du ut onsdag kveld, neste morgen. Stjernen markerer avgangen med minst tid for motor og i bidevind.",points:["Opptil tolv avganger, hver sjette time","Trykk på en rad for å se ruten","Lagre en seilas eller del den med mannskapet, alltid med det nyeste varselet"],image:"departures",alt:"Avgangstabellen for Leros til Rhodos, hver sjette time fra onsdag 08:00: ankomst, varighet, sterkeste vind og timer for motor, med beste avgang, torsdag kl. 14:00, merket med stjerne.",coords:"",caption:"Leros → Rhodos, avganger fra onsdag 08:00",card:!0},{id:"stays",number:"05",kicker:"Båtpauser",title:"Hvor andre båter ligger.",text:"Hvor lar mannskaper båten ligge i to måneder om sommeren, og hvor tilbringer de vinteren? Båtpauser viser havnene og ankringsplassene der båter har tatt pause — fra noen få dager til mer enn seks måneder, etter sesong.",points:["Filtrer etter liggetid","Se i hvilke måneder båter ligger på et sted","Finn populære vinterhavner"],image:"stay-detail",alt:"Preveza: typisk liggetid og månedene da båter ligger der.",coords:"38°57′N · 020°45′E",caption:"Preveza, liggetid og sesong"},{id:"hotspots",number:"06",kicker:"Hotspots",title:"Finn den roligere ankringsplassen.",text:"Hvor trenges båtene i august, og hvor er det fortsatt plass? Hotspots viser måned for måned hvor travelt hvert seilområde er. Det joniske hav og Saronbukta lyser opp, mens Andros, en dagsseilas fra Athen, forblir rolig.",points:["Fra rolig til fullt","Hver måned i året","Travleste og roligste måneder på ethvert punkt"],image:"hotspots",alt:"Hvor travle de greske seilområdene er i august: fullt rundt De joniske øyer og i Saronbukta, rolig utenfor Andros, med punktinspektøren åpen.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Hellas, august"},{id:"spot",number:"07",kicker:"Stedsprofil",title:"Alt om ett sted, i én oversikt.",text:"Hold fingeren på et sted på kartet, eller høyreklikk på det, så samler stedsprofilen alt for måneden du velger: vind og sjøgang, tordenvær, hvor godt terrenget beskytter stedet, og båtpausene og rutene i nærheten. Gaios på Paxos i september: for det meste stille eller svak vind, rolig til lett sjø og tordenvær omtrent hver sjette dag. Månedsstripen viser at november er måneden med mest tordenvær.",points:["Vind, sjøgang og tordenvær for ett sted og én måned","Båtpauser og ruter innenfor 5 nautiske mil","Hver måned vurdert i ett blikk, som lenke til mannskapet ditt"],image:"spot",alt:"Stedsprofilen for Gaios på Paxos i september: vind og sjøgang, tordenvær, terrengets beskyttelse, båtpauser og ruter i nærheten og hver måned vurdert i ett blikk.",coords:"",caption:"Gaios, Paxos, september",card:!0},{id:"wind",number:"08",kicker:"Vind",title:"Hvor mye nordavind kan du vente deg?",text:"Velg retning og måned: I juli blir det sentrale Egeerhavet dypblått. Det er meltemien. Trykk på et punkt ved Mykonos, og du ser at vinden kommer fra nord i 60 % eller mer av alle timene i juli.",points:["Styrke og retning for hver måned","Vind etter tid på døgnet","Trykk på et punkt for å se tallene"],image:"wind",alt:"Hvor ofte vinden blåser fra nord i Egeerhavet i juli, med punktdetaljene åpne ved Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vind fra nord, Egeerhavet, juli"},{id:"waves",number:"09",kicker:"Bølger",title:"Kjenn sjøgangen før du legger ut.",text:"Hvor mange dager i måneden gir bølger på 2,5 m eller mer? I januar ser du tydelig hvor langt mistralen når ut over Lionbukta.",points:["Fra rolig til svært grov sjø","Dønning og kort, bratt sjø","Hver måned i året"],image:"waves",alt:"Dager med grov sjø i det vestlige Middelhavet i januar.",coords:"41°00′N · 005°00′E",caption:"Dager med grov sjø, vestlige Middelhavet, januar"},{id:"risk",number:"10",kicker:"Tordenværsrisiko",title:"Hvilken havn får minst tordenvær?",text:"Tordenværsrisiko samler hvor ofte det blir tordenvær, hvor kraftig det er, og hvordan fjell, nes og åpent hav former det — for hver måned og helt ned til enkeltbukter. Trykk på ett sted og deretter på et annet, så ser du hvor mye mer eller mindre risiko det andre har. Preveza og Messolonghi er begge populære steder å ligge vinteren over: I november har Messolonghi 27 % lavere tordenværsrisiko.",points:["Tordendager, lyntetthet og terreng i én verdi","Forskjeller helt ned til enkeltbukter","Trykk på to steder for å sammenligne dem"],image:"risk",alt:"Tordenværsrisiko i Det joniske hav i november: først Preveza, så Messolonghi, og punktinspektøren viser 27 % lavere risiko.",coords:"38°40′N · 021°10′E",caption:"Preveza vs. Messolonghi, november",markers:[{x:34.09,y:27.12,text:"Preveza, valgt først: risikoverdi 50 i november.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, 47 nm unna: 27 % lavere tordenværsrisiko.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Lyndata",title:"Hvor ofte, hvor kraftig, hvor sannsynlig.",text:"Bak risikoen ligger tre lag som du også kan åpne hver for seg, på samme skala i alle måneder. I september viser Middelhavet hvorfor du trenger alle tre: Tordenvær er hyppigst langs kysten av Adriaterhavet og Det joniske hav, lynene er tettest over havet mellom Italia og Hellas, og forhold som fremmer tordenvær, når langt sørover.",points:["Tordendager: hvor ofte det blir tordenvær, 2013–2025","Lyntetthet: hvor kraftig det er","Tordenværpotensial: hvor tordenvær kan bygge seg opp, 1994–2023"],image:"days",alt:"Tordendager i Middelhavet i september.",coords:"40°00′N · 015°00′E",caption:"Tordendager, Middelhavet, september",panels:[{label:"Tordendager",image:"days",alt:"Tordendager i Middelhavet i september.",caption:"Tordendager, Middelhavet, september"},{label:"Lyntetthet",image:"density",alt:"Lyntetthet i Middelhavet i september.",caption:"Lyntetthet, Middelhavet, september"},{label:"Tordenværpotensial",image:"potential",alt:"Tordenværpotensial i Middelhavet i september.",caption:"Tordenværpotensial, Middelhavet, september"}]},{id:"terrain",number:"12",kicker:"Terrengeksponering",title:"Samme bukt, ulik skjerming.",text:"Tordenværsrisiko forteller deg hvilken bukt. Terrengeksponering forteller deg hvilken side av den: Åsene rundt kan skjerme en ankringsplass mot lyn, og laget viser hvor godt terrenget beskytter hver del av en bukt — så du kan velge det beste stedet før ankeret går.",points:["Sammenlign steder i samme bukt","Detaljerte høydedata med 30 m oppløsning"],image:"terrain",alt:"Terrengeksponering i bukta ved Komiža på Vis, Kroatia.",coords:"43°02′N · 016°05′E",caption:"Bukta ved Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Liten skjerming fra terrenget rundt.",color:"#762a83"},{x:53.84,y:26.35,text:"Noe skjerming fra terrenget rundt.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Sterkere skjerming fra terrenget rundt.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Havbunn",title:"Sand eller sjøgress?",text:"Før ankeret går: laget Havbunn viser sand, mudder, fjell, sjøgress og korall langs kysten, fra Middelhavet til tropene. I Palmabukta går et bredt belte av sjøgress langs land, og sanden ligger lenger ute. Ankring på posidonia er forbudt flere og flere steder, så det lønner seg å vite det før du kommer fram.",points:["Sand, mudder, fjell, sjøgress og korall","Europa og grunne tropiske kyster","Åpent for alle"],image:"seabed",alt:"Havbunnen i Palmabukta, Mallorca: et bredt belte av sjøgress langs land, sand lenger ute, punktinspektøren viser sjøgress.",coords:"39°30′N · 002°37′E",caption:"Havbunn, Palmabukta"}],story:{kicker:"Vår historie",title:"Født av en nestenulykke.",text:"I oktober 2024 seilte familien vår i Det joniske hav da lynet slo ned rett ved siden av båten. Det øyeblikket reiste et enkelt spørsmål: Er vi tryggere her, eller på den andre siden av bukta? IncusGrid begynte som svaret — og vokste til et kart over alt vi skulle ønske vi hadde visst før den sesongen.",more:"Les hele historien (på engelsk)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Hellas",note:"Der ideen ble født"},fromBlog:{kicker:"Fra bloggen",title:"Datahistorier fra sjøen.",all:"Alle innlegg",note:"Innlegg på engelsk."},devices:{kicker:"Web & Android",title:"På dekk eller ved kartbordet.",text:"Bruk IncusGrid i hvilken som helst nettleser, eller installer Android-appen. Søk opp seilområdet ditt og utforsk det på mobil, nettbrett eller laptop.",points:["Ingen installasjon i nettleseren","Android-app på Google Play","Tilgjengelig på 19 språk"],web:"Åpne i nettleseren",android:"Last ned på Google Play",phoneAlt:"IncusGrid-appen for Android med båtpauser rundt De joniske øyer."},final:{title:"Planlegg neste sesong. Og neste seilas.",text:"Ruter, båtpauser, vind, bølger og lyn fra mange år med ekte data, pluss 10-dagersvarselet og seilasplanleggeren — på ett kart.",cta:"Åpne kartet"},disclaimerLabel:"Viktig",disclaimer:"IncusGrid er laget for planlegging og er ikke et navigasjonshjelpemiddel. Rutene er tegnet skjematisk, og båtpauser er utledet fra pauser i båtenes posisjonsmeldinger, ikke fra bekreftede båtplasser. Seilasplanleggeren bruker et enkelt polardiagram, uten strøm eller bølgenes påvirkning på båtens fart, og ruter deg ikke inn i havnen. Sjekk alltid oppdaterte værmeldinger, offisielle sjøkart og lokale forhold før du legger ut.",footer:{blog:"Blogg",legal:"Juridisk informasjon",privacy:"Personvern",terms:"Vilkår for bruk",cookies:"Innstillinger for informasjonskapsler",support:"Brukerstøtte",madeWith:"Laget med",made:"i Portugal",englishOnly:"Juridiske sider er på engelsk."}},k={path:"/fi",htmlLang:"fi",ogLocale:"fi_FI",meta:{title:"IncusGrid · Paikallistuntemusta ja sääreititystä purjehtijoille",description:"Purjehdusreitit ja veneiden tauot todellisista purjehduksista, vuosien tuuli-, aalto- ja salamatiedot sekä 10 päivän ennuste ja sääreititys veneellesi. Suunnittele kautesi ja purjehduksesi yhdellä kartalla.",keywords:"sääreititys, weather routing, matkan suunnittelu, reittisuunnittelu, lähtöajan valinta, purjehdussää, tuuliennuste, polaarikäyrä, purjehdusreitit, matkapurjehdus, ankkuripaikka, vierassatama, marina, talvisäilytys, tuulitilasto, merenkäynti, aallokko, salamat, ukkonen, ukkosriski, salamatiheys, purjehduksen suunnittelu, purjevene, Välimeren purjehdus, merenpohja, meriruoho, posidonia, ankkurointipohja"},nav:{routes:"Reitit",passages:"Purjehdukset",stays:"Veneiden tauot",weather:"Sää",thunderstorms:"Salamat",blog:"Blogi",openApp:"Avaa kartta"},hero:{position:"Sailing intelligence",lead:"IncusGrid muuttaa vuosien datan paikallistuntemukseksi, jota jokainen miehistö tarvitsee ennen irrottautumista: todelliset veneliikkeet, tuuli, aallot ja salamat yhdellä kartalla. Lisäksi ennuste seuraaville 10 päivälle ja purjehdussuunnittelija, joka reitittää veneesi ennustetun tuulen läpi tunti tunnilta ja näyttää puuskat ja aallot matkan varrella.",ctaApp:"Avaa kartta",ctaAndroid:"Android-sovellus",heroAlt:"Purjehdusreitit Karibianmerellä Hispaniolalta Pienille Antilleille ja Etelä-Amerikan rannikolle, piirretty matkaveneiden todellisista purjehduksista.",heroCaption:"Purjehdusreitit, Karibianmeri · kaikki kuukaudet",notes:[{label:"Veneitä",value:"Tuhansia"},{label:"Liikkeitä",value:"Miljoonia"},{label:"Salamaniskuja",value:"Miljardeja"},{label:"Ennuste",value:"10 päivää"},{label:"Kattavuus",value:"Koko maailma"}]},contrast:{kicker:"Kausi ja ennuste",title:"Kausi kertoo, minä kuukautena. Ennuste kertoo, minä päivänä.",text:"Minkä ylityksen miehistöt tekevät kesäkuussa? Missä veneet talvehtivat? Mikä kuukausi tuo meltemin, ja missä talvisatamassa ukkostaa marraskuussa vähemmän? Vastaukset näkyvät vasta, kun katsoo monta vuotta kerralla. Kun lähtö lähestyy, purjehdussuunnittelija laskee 10 päivän ennusteesta, milloin kannattaa lähteä ja milloin olet perillä."},chapters:[{id:"routes",number:"01",kicker:"Purjehdusreitit",title:"Suunnittele ylitykset tuhansien miehistöjen kokemuksella.",text:"Tuhannet todelliset purjehdukset näyttävät, milloin ylitys on järkevä, mihin suuntaan, ja mistä miehistöt lähtevät ja minne saapuvat. Vallitsevat tuulet, hyvät paikat sääikkunan odottamiseen ja turvallinen maihintulo yön yli kestäneen osuuden jälkeen ovat jo mukana. Esimerkiksi Sisiliasta Joonian saarille useimmat veneet purjehtivat itään touko- ja kesäkuussa ja palaavat syyskuussa.",points:["Suosio kuukausittain ja suunnittain","Suosituimmat reitit nykyisessä karttanäkymässä","Jaa reitti miehistösi kanssa"],image:"route-detail",alt:"Valittuna reitti Sisiliasta Joonian saarille ja sen suosio kunakin kuukautena kumpaankin suuntaan.",coords:"38°12′N · 017°30′E",caption:"Sisilia → Joonian saaret, kuukausittain ja suunnittain"},{id:"route-wind",number:"02",kicker:"Tuuli reitin varrella",title:"Tunne tuuli ennen kuin irrotat köydet.",text:"Jokainen reitti näyttää kuukausittain, millaista tuulta sillä voi odottaa: mistä se puhaltaa, kuinka kovaa, kuinka suuri osa matkasta on vastaista, sivutuulta tai myötäistä ja kuinka usein meri pysyy tyynenä. Sisiliasta Joonian saarille toukokuussa: tuuli luoteesta, 3 boforia, yli puolet matkasta myötäistä.",points:["Vallitseva tuuli ja voimakkuus boforeina joka kuukaudelle","Vastaista, sivutuulta tai myötäistä reitin kurssilla","Aallokko reitin varrella"],image:"route-wind",alt:"Reittikortti Sisiliasta Joonian saarille: vallitseva tuuli, voimakkuus boforeina, tuulen voimakkuus, kurssi ja aallokko joka kuukaudelle, toukokuu valittuna.",coords:"",caption:"Sisilia → Joonian saaret, tuuli toukokuussa",card:!0},{id:"passage",number:"03",kicker:"Purjehdussuunnittelija · sääreititys",title:"Tiedä saapumisaikasi ennen kuin irrotat köydet.",text:"Valitse lähtöpaikka ja määränpää, valitse veneesi, ja purjehdussuunnittelija löytää nopean reitin seuraavan 10 päivän ennustetun tuulen läpi tunti tunnilta, puuskat ja aallot matkan varrella. Leroksesta Rodokselle, 86 meripeninkulmaa, lähtö keskiviikkona klo 20.00: yksi yö myötäisessä, tuulta enintään 15 solmua, ei lainkaan moottoriajoa, perillä torstaina vähän ennen yhtätoista.",points:["Saapuminen, kovin tuuli, puuskat ja aallot, tunnit purjein ja moottorilla","Veneellesi: tyyppi ja koko tai oma polaarikäyrä","Matkalla sijaintisi suunnitelman rinnalla ja loppureitti laskettuna uudelleen"],image:"passage",alt:"Purjehdussuunnittelija ja reitti Leroksesta Rodokselle tuuliennusteen päällä: reittipisteet kellonaikoineen, vene yöllä Kosin eteläpuolella ja vieressä saapumisaika, kovin tuuli sekä tunnit purjein ja moottorilla.",coords:"36°48′N · 027°50′E",caption:"Leros → Rodos, lähtö keskiviikkona klo 20.00 · ennuste 31. lokakuuta"},{id:"departures",number:"04",kicker:"Vertaa lähtöaikoja",title:"Oikea päivä irrottaa köydet.",text:"Suunnittelija laskee saman purjehduksen jopa kahdelletoista lähtöajalle kuuden tunnin välein ja asettaa rinnakkain saapumisajan, keston, kovimman tuulen ja moottoriajan. Kun lähdet Leroksesta keskiviikkoaamuna, olet Rodoksella keskiyöllä; keskiviikkoiltana lähtiessä seuraavana aamuna. Tähti merkitsee lähdön, jossa on vähiten moottoriajoa ja vastaista.",points:["Jopa kaksitoista lähtöaikaa kuuden tunnin välein","Napauta riviä nähdäksesi sen reitin","Tallenna purjehdus tai jaa se miehistölle, aina uusimmalla ennusteella"],image:"departures",alt:"Lähtöaikataulukko Leroksesta Rodokselle kuuden tunnin välein keskiviikosta klo 8.00 alkaen: saapuminen, kesto, kovin tuuli ja moottoritunnit, paras lähtö torstaina klo 14.00 tähdellä merkittynä.",coords:"",caption:"Leros → Rodos, lähdöt keskiviikosta klo 8.00 alkaen",card:!0},{id:"stays",number:"05",kicker:"Veneiden tauot",title:"Missä muut veneet viipyvät.",text:"Mihin miehistöt jättävät veneensä kahdeksi kesäkuukaudeksi, ja missä ne viettävät talven? Veneiden tauot näyttävät satamat ja ankkuripaikat, joissa veneet ovat pitäneet taukoa — muutamasta päivästä yli kuuteen kuukauteen, kausittain.",points:["Suodata tauon pituuden mukaan","Näe, minä kuukausina veneet viipyvät paikassa","Löydä suositut talvisatamat"],image:"stay-detail",alt:"Preveza: tyypillinen tauon pituus ja kuukaudet, joina veneet viipyvät siellä.",coords:"38°57′N · 020°45′E",caption:"Preveza, tauon pituus ja kausi"},{id:"hotspots",number:"06",kicker:"Hotspotit",title:"Löydä rauhallisempi ankkuripaikka.",text:"Missä veneet ruuhkautuvat elokuussa, ja missä on vielä tilaa? Hotspotit näyttää kuukausittain, kuinka vilkas kukin purjehdusalue on. Joonianmeri ja Saroninlahti hehkuvat, kun taas Andros, päivän purjehduksen päässä Ateenasta, pysyy rauhallisena.",points:["Rauhallisesta ruuhkaiseen","Vuoden jokainen kuukausi","Vilkkaimmat ja rauhallisimmat kuukaudet missä tahansa pisteessä"],image:"hotspots",alt:"Kreikan purjehdusalueiden vilkkaus elokuussa: ruuhkaista Joonianmeren saarten ympärillä ja Saroninlahdella, rauhallista Androksen edustalla, pistetarkastelu avoinna.",coords:"38°24′N · 023°36′E",caption:"Hotspotit, Kreikka, elokuu"},{id:"spot",number:"07",kicker:"Paikan tiedot",title:"Kaikki yhdestä paikasta yhdellä silmäyksellä.",text:"Pidä mitä tahansa kartan paikkaa painettuna tai napsauta sitä hiiren oikealla painikkeella, niin paikan tiedot kokoavat kaiken valitsemallesi kuukaudelle: tuulen ja aallokon, ukkosen, maaston suojan sekä lähistön veneiden tauot ja reitit. Gaios Paxoksella syyskuussa: useimmiten tyyntä tai heikkoa tuulta, tyyni tai heikko aallokko ja ukkosta noin joka kuudes päivä. Kuukausirivi näyttää, että marraskuussa on eniten ukkosta.",points:["Tuuli, aallokko ja ukkonen yhdelle paikalle ja kuukaudelle","Veneiden tauot ja reitit 5 meripeninkulman säteellä","Jokainen kuukausi arvioituna yhdellä silmäyksellä, linkkinä miehistöllesi"],image:"spot",alt:"Paikan tiedot Gaiosista Paxoksella syyskuussa: tuuli ja aallokko, ukkonen, maaston suoja, lähistön veneiden tauot ja reitit sekä jokainen kuukausi arvioituna yhdellä silmäyksellä.",coords:"",caption:"Gaios, Paxos, syyskuu",card:!0},{id:"wind",number:"08",kicker:"Tuuli",title:"Kuinka paljon pohjoistuulta on odotettavissa?",text:"Valitse suunta ja kuukausi: heinäkuussa Aigeianmeren keskiosa muuttuu syvän siniseksi. Se on meltemi. Napauta pistettä Mykonoksen lähellä, niin näet tuulen puhaltavan pohjoisesta vähintään 60 %:ssa heinäkuun tunneista.",points:["Voimakkuus ja suunta joka kuukaudelle","Tuuli vuorokaudenajan mukaan","Napauta mitä tahansa pistettä nähdäksesi sen luvut"],image:"wind",alt:"Kuinka usein tuuli puhaltaa pohjoisesta Aigeianmerellä heinäkuussa; pisteen tiedot auki Mykonoksen lähellä.",coords:"37°36′N · 025°00′E",caption:"Pohjoistuuli, Aigeianmeri, heinäkuu"},{id:"waves",number:"09",kicker:"Aallot",title:"Tunne merenkäynti ennen lähtöä.",text:"Kuinka monena päivänä kuukaudessa aallot nousevat 2,5 metriin tai yli? Tammikuussa näkyy selvästi, kuinka laajalle mistral ulottuu Leijonanlahdella.",points:["Tyynestä erittäin kovaan merenkäyntiin","Maininki ja lyhyt, jyrkkä aallokko","Vuoden jokainen kuukausi"],image:"waves",alt:"Kovan aallokon päivät läntisellä Välimerellä tammikuussa.",coords:"41°00′N · 005°00′E",caption:"Kovan aallokon päivät, läntinen Välimeri, tammikuu"},{id:"risk",number:"10",kicker:"Ukkosriski",title:"Missä satamassa ukkostaa vähemmän?",text:"Ukkosriski yhdistää sen, kuinka usein ukkosia esiintyy, kuinka rajuja ne ovat ja miten vuoret, niemet ja avomeri niihin vaikuttavat — jokaiselle kuukaudelle ja yksittäisten lahtien tarkkuudella. Napauta yhtä paikkaa ja sitten toista, niin näet, kuinka paljon suurempi tai pienempi riski toisella on. Preveza ja Messolonghi ovat molemmat suosittuja talvehtimispaikkoja: marraskuussa Messolonghin ukkosriski on 27 % pienempi.",points:["Ukkospäivät, salamatiheys ja maasto yhdessä arvossa","Erot yksittäisten lahtien tarkkuudella","Napauta kahta paikkaa vertaillaksesi niitä"],image:"risk",alt:"Ukkosriski Joonianmerellä marraskuussa: ensin napautettu Prevezaa, sitten Messolonghia, ja pistetarkastelu näyttää 27 % pienemmän riskin.",coords:"38°40′N · 021°10′E",caption:"Preveza vs. Messolonghi, marraskuu",markers:[{x:34.09,y:27.12,text:"Preveza, napautettu ensin: riskiarvo 50 marraskuussa.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, 47 mpk:n päässä: 27 % pienempi ukkosriski.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Salamatiedot",title:"Kuinka usein, kuinka rajusti, kuinka todennäköisesti.",text:"Riskin taustalla on kolme tasoa, jotka voit avata myös erikseen, joka kuukausi samalla asteikolla. Syyskuussa Välimeri näyttää, miksi tarvitset kaikki kolme: ukkosia on eniten Adrianmeren ja Joonianmeren rannikoilla, salamointi on tiheintä merellä Italian ja Kreikan välissä, ja ukkoselle suotuisat olot ulottuvat kauas etelään.",points:["Ukkospäivät: kuinka usein ukkosia esiintyy, 2013–2025","Salamatiheys: kuinka rajuja ne ovat","Ukkoselle suotuisat olot: missä ukkoset voivat syntyä, 1994–2023"],image:"days",alt:"Ukkospäivät Välimerellä syyskuussa.",coords:"40°00′N · 015°00′E",caption:"Ukkospäivät, Välimeri, syyskuu",panels:[{label:"Ukkospäivät",image:"days",alt:"Ukkospäivät Välimerellä syyskuussa.",caption:"Ukkospäivät, Välimeri, syyskuu"},{label:"Salamatiheys",image:"density",alt:"Salamatiheys Välimerellä syyskuussa.",caption:"Salamatiheys, Välimeri, syyskuu"},{label:"Ukkoselle suotuisat olot",image:"potential",alt:"Ukkoselle suotuisat olot Välimerellä syyskuussa.",caption:"Ukkoselle suotuisat olot, Välimeri, syyskuu"}]},{id:"terrain",number:"12",kicker:"Maaston vaikutus",title:"Sama lahti, eri suoja.",text:"Ukkosriski kertoo, mikä lahti. Maaston vaikutus kertoo, mikä puoli siitä: ympäröivät kukkulat voivat suojata ankkuripaikkaa salamoilta, ja taso näyttää, kuinka hyvin maasto suojaa lahden kutakin osaa — joten voit valita paremman kohdan ennen kuin lasket ankkurin.",points:["Vertaa kohtia saman lahden sisällä","Tarkka 30 metrin korkeusaineisto"],image:"terrain",alt:"Maaston vaikutus Komižan lahdella Visin saarella Kroatiassa.",coords:"43°02′N · 016°05′E",caption:"Komižan lahti, Vis",markers:[{x:56.9,y:57.69,text:"Ympäröivä maasto suojaa vain vähän.",color:"#762a83"},{x:53.84,y:26.35,text:"Ympäröivä maasto suojaa jonkin verran.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Ympäröivä maasto suojaa enemmän.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Merenpohja",title:"Hiekkaa vai meriruohoa?",text:"Ennen kuin ankkuri lasketaan: Merenpohja-taso näyttää hiekan, mudan, kallion, meriruohon ja korallin rannikolla Välimereltä tropiikkiin. Palman lahdella leveä meriruohovyö kulkee rannan suuntaisesti, ja hiekka on kauempana. Ankkurointi posidonian päälle on kielletty yhä useammassa paikassa, joten se kannattaa tietää ennen perillepääsyä.",points:["Hiekka, muta, kallio, meriruoho ja koralli","Eurooppa ja matalat trooppiset rannikot","Avoin kaikille"],image:"seabed",alt:"Merenpohja Palman lahdella, Mallorcalla: leveä meriruohovyö rannan tuntumassa, hiekkaa kauempana, pistetarkastin näyttää meriruohon.",coords:"39°30′N · 002°37′E",caption:"Merenpohja, Palman lahti"}],story:{kicker:"Tarinamme",title:"Syntyi läheltä piti -tilanteesta.",text:"Lokakuussa 2024 perheemme purjehti Joonianmerellä, kun salama iski aivan veneemme viereen. Siitä heräsi yksinkertainen kysymys: olemmeko turvallisemmassa paikassa täällä vai lahden toisella puolella? IncusGrid sai alkunsa vastauksena — ja kasvoi kartaksi kaikesta, mitä olisimme halunneet tietää ennen sitä kautta.",more:"Lue koko tarina (englanniksi)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Kreikka",note:"Täällä idea syntyi"},fromBlog:{kicker:"Blogista",title:"Datatarinoita vesiltä.",all:"Kaikki kirjoitukset",note:"Kirjoitukset englanniksi."},devices:{kicker:"Web & Android",title:"Kannella tai karttapöydän ääressä.",text:"Käytä IncusGridiä missä tahansa selaimessa tai asenna Android-sovellus. Hae purjehdusalueesi ja tutki sitä puhelimella, tabletilla tai kannettavalla.",points:["Selaimessa ilman asennusta","Android-sovellus Google Playssa","Saatavilla 19 kielellä"],web:"Avaa selaimessa",android:"Lataa Google Playsta",phoneAlt:"IncusGridin Android-sovellus, jossa näkyvät veneiden tauot Joonian saarten ympärillä."},final:{title:"Suunnittele seuraava kautesi. Ja seuraava purjehduksesi.",text:"Reitit, veneiden tauot, tuuli, aallot ja salamat vuosien todellisesta datasta sekä 10 päivän ennuste ja purjehdussuunnittelija — yhdellä kartalla.",cta:"Avaa kartta"},disclaimerLabel:"Huomio",disclaimer:"IncusGrid on tehty suunnitteluun, eikä se ole navigoinnin apuväline. Reitit on piirretty kaavamaisesti, ja veneiden tauot on päätelty veneiden sijainti-ilmoitusten katkoista, ei vahvistetuista laituripaikoista. Purjehdussuunnittelija käyttää yksinkertaista polaarikäyrää, eikä se huomioi virtoja tai aaltojen vaikutusta veneen nopeuteen eikä reititä satamaan asti. Tarkista aina ajantasaiset ennusteet, viralliset merikartat ja paikalliset olosuhteet ennen kuin lähdet merelle.",footer:{blog:"Blogi",legal:"Oikeudelliset tiedot",privacy:"Tietosuojaseloste",terms:"Käyttöehdot",cookies:"Evästeasetukset",support:"Tuki",madeWith:"Tehty",made:"Portugalissa",englishOnly:"Oikeudelliset sivut ovat englanniksi."}},v={path:"/el",htmlLang:"el",ogLocale:"el_GR",meta:{title:"IncusGrid · Τοπική γνώση και καιρική δρομολόγηση για ιστιοπλόους",description:"Ιστιοπλοϊκές διαδρομές και παύσεις σκαφών από πραγματικά ταξίδια, χρόνια δεδομένων ανέμου, κυμάτων και κεραυνών, συν την πρόγνωση 10 ημερών και καιρική δρομολόγηση για το σκάφος σου. Σχεδίασε τη σεζόν και την πλεύση σου σε έναν χάρτη.",keywords:"καιρική δρομολόγηση, weather routing, σχεδιασμός πλεύσης, σχεδιασμός διαδρομής, ώρα αναχώρησης, πρόγνωση καιρού για ιστιοπλοΐα, πρόγνωση ανέμου, πολικό διάγραμμα σκάφους, ιστιοπλοΐα, ιστιοπλοϊκές διαδρομές, ιστιοπλοϊκό ταξίδι, αγκυροβόλια, μαρίνα, διαχείμαση σκάφους, μελτέμι, στατιστικά ανέμου, κατάσταση θάλασσας, κύματα, κεραυνοί, καταιγίδες, κίνδυνος καταιγίδας, πυκνότητα κεραυνών, σχεδιασμός ταξιδιού, σκάφος, ιστιοπλοϊκό, βυθός, ποσειδώνια, θαλάσσια λιβάδια, βυθός αγκυροβολίας"},nav:{routes:"Διαδρομές",passages:"Πλεύσεις",stays:"Παύσεις σκαφών",weather:"Καιρός",thunderstorms:"Κεραυνοί",blog:"Blog",openApp:"Άνοιξε τον χάρτη"},hero:{position:"Sailing intelligence",lead:"Το IncusGrid μετατρέπει χρόνια δεδομένων στην τοπική γνώση που χρειάζεται κάθε πλήρωμα πριν λύσει κάβους: πραγματικές κινήσεις σκαφών, άνεμος, κύματα και κεραυνοί σε έναν χάρτη. Και επιπλέον η πρόγνωση για τις επόμενες 10 ημέρες και ένας σχεδιαστής πλεύσης που οδηγεί το σκάφος σου μέσα από τον προβλεπόμενο άνεμο, ώρα με την ώρα, με τις ριπές και τα κύματα στη διαδρομή.",ctaApp:"Άνοιξε τον χάρτη",ctaAndroid:"Εφαρμογή Android",heroAlt:"Ιστιοπλοϊκές διαδρομές στην Καραϊβική, από την Ισπανιόλα ως τις Μικρές Αντίλλες και τις ακτές της Νότιας Αμερικής, σχεδιασμένες από πραγματικά ταξίδια ιστιοπλοϊκών σκαφών.",heroCaption:"Ιστιοπλοϊκές διαδρομές, Καραϊβική Θάλασσα · όλοι οι μήνες",notes:[{label:"Σκάφη",value:"Χιλιάδες"},{label:"Κινήσεις",value:"Εκατομμύρια"},{label:"Πτώσεις κεραυνών",value:"Δισεκατομμύρια"},{label:"Πρόγνωση",value:"10 ημέρες"},{label:"Κάλυψη",value:"Παγκόσμια"}]},contrast:{kicker:"Σεζόν και πρόγνωση",title:"Η σεζόν σου λέει ποιον μήνα. Η πρόγνωση σου λέει ποια μέρα.",text:"Ποιο πέρασμα κάνουν τα πληρώματα τον Ιούνιο; Πού ξεχειμωνιάζουν τα σκάφη; Ποιος μήνας φέρνει το μελτέμι, και ποιο λιμάνι διαχείμασης βλέπει λιγότερες καταιγίδες τον Νοέμβριο; Απαντήσεις που φαίνονται μόνο όταν κοιτάς πολλά χρόνια μαζί. Όσο πλησιάζει η αναχώρηση, ο σχεδιαστής πλεύσης υπολογίζει με την πρόγνωση 10 ημερών πότε να φύγεις και πότε θα φτάσεις."},chapters:[{id:"routes",number:"01",kicker:"Ιστιοπλοϊκές διαδρομές",title:"Σχεδίασε περάσματα με την εμπειρία χιλιάδων πληρωμάτων.",text:"Χιλιάδες πραγματικά ταξίδια δείχνουν πότε ένα πέρασμα έχει νόημα, προς ποια κατεύθυνση, και από πού ξεκινούν και πού φτάνουν τα πληρώματα. Οι επικρατούντες άνεμοι, καλά σημεία για να περιμένεις ένα καιρικό παράθυρο και μια ασφαλής άφιξη μετά από μια νύχτα στη θάλασσα είναι ήδη μέσα. Από τη Σικελία προς τα Ιόνια νησιά, για παράδειγμα, τα περισσότερα σκάφη πλέουν ανατολικά τον Μάιο και τον Ιούνιο και επιστρέφουν τον Σεπτέμβριο.",points:["Δημοτικότητα ανά μήνα και κατεύθυνση","Οι πιο δημοφιλείς διαδρομές στην τρέχουσα προβολή του χάρτη","Μοιράσου μια διαδρομή με το πλήρωμά σου"],image:"route-detail",alt:"Επιλεγμένη η διαδρομή από τη Σικελία προς τα Ιόνια νησιά, με τη δημοτικότητά της ανά μήνα και κατεύθυνση.",coords:"38°12′N · 017°30′E",caption:"Σικελία → Ιόνια νησιά, ανά μήνα και κατεύθυνση"},{id:"route-wind",number:"02",kicker:"Ο άνεμος στη διαδρομή",title:"Μάθε τον άνεμο πριν λύσεις κάβους.",text:"Κάθε διαδρομή δείχνει τον άνεμο που μπορείς να περιμένεις, μήνα με μήνα: από πού φυσά, πόσο δυνατά, τι μέρος του περάσματος πλέεις όρτσα, τραβέρσο ή πρύμα, και πόσο συχνά η θάλασσα μένει ήρεμη. Από τη Σικελία προς τα Ιόνια νησιά τον Μάιο: βορειοδυτικός άνεμος, 3 Μποφόρ, πάνω από τη μισή διαδρομή πρύμα.",points:["Επικρατών άνεμος και ένταση σε Μποφόρ για κάθε μήνα","Όρτσα, τραβέρσο ή πρύμα στην πορεία της διαδρομής","Κατάσταση της θάλασσας κατά μήκος της διαδρομής"],image:"route-wind",alt:"Η κάρτα της διαδρομής από τη Σικελία προς τα Ιόνια νησιά: επικρατών άνεμος, ένταση σε Μποφόρ, ένταση ανέμου, πλεύση και κατάσταση της θάλασσας για κάθε μήνα, με επιλεγμένο τον Μάιο.",coords:"",caption:"Σικελία → Ιόνια νησιά, ο άνεμος τον Μάιο",card:!0},{id:"passage",number:"03",kicker:"Σχεδιαστής πλεύσης · καιρική δρομολόγηση",title:"Μάθε πότε φτάνεις πριν λύσεις κάβους.",text:"Όρισε αφετηρία και προορισμό, διάλεξε το σκάφος σου, και ο σχεδιαστής πλεύσης βρίσκει μια γρήγορη διαδρομή μέσα από τον προβλεπόμενο άνεμο των επόμενων 10 ημερών, ώρα με την ώρα, με τις ριπές και τα κύματα στη διαδρομή. Από τη Λέρο στη Ρόδο, 86 ναυτικά μίλια, με αναχώρηση την Τετάρτη στις 20:00: μία νύχτα πρύμα με όχι πάνω από 15 κόμβους ανέμου, χωρίς μηχανή, και άφιξη την Πέμπτη λίγο πριν τις έντεκα.",points:["Άφιξη, ισχυρότερος άνεμος, ριπές και κύματα, ώρες με πανιά και με μηχανή","Για το δικό σου σκάφος: τύπος και μέγεθος ή το δικό σου πολικό διάγραμμα","Εν πλω, η θέση σου δίπλα στο σχέδιο και η υπόλοιπη διαδρομή υπολογισμένη ξανά"],image:"passage",alt:"Ο σχεδιαστής πλεύσης με τη διαδρομή από τη Λέρο στη Ρόδο πάνω στην πρόγνωση ανέμου: σημεία διαδρομής με ώρες, το σκάφος νότια της Κω τη νύχτα, και δίπλα η άφιξη, ο ισχυρότερος άνεμος και οι ώρες με πανιά και με μηχανή.",coords:"36°48′N · 027°50′E",caption:"Λέρος → Ρόδος, αναχώρηση Τετάρτη 20:00 · πρόγνωση της 31ης Οκτωβρίου"},{id:"departures",number:"04",kicker:"Σύγκριση αναχωρήσεων",title:"Η σωστή μέρα για να λύσεις κάβους.",text:"Ο σχεδιαστής υπολογίζει την ίδια πλεύση για έως δώδεκα αναχωρήσεις, ανά έξι ώρες, και βάζει δίπλα δίπλα άφιξη, διάρκεια, ισχυρότερο άνεμο και χρόνο με μηχανή. Αν φύγεις από τη Λέρο την Τετάρτη το πρωί, φτάνεις στη Ρόδο τα μεσάνυχτα· αν φύγεις την Τετάρτη το βράδυ, το επόμενο πρωί. Το αστέρι σημειώνει την αναχώρηση με τον λιγότερο χρόνο με μηχανή και όρτσα.",points:["Έως δώδεκα αναχωρήσεις, κάθε έξι ώρες","Πάτησε μια γραμμή για να δεις τη διαδρομή της","Αποθήκευσε μια πλεύση ή μοιράσου τη με το πλήρωμά σου, πάντα με την πιο πρόσφατη πρόγνωση"],image:"departures",alt:"Ο πίνακας αναχωρήσεων από τη Λέρο στη Ρόδο, ανά έξι ώρες από την Τετάρτη 08:00: άφιξη, διάρκεια, ισχυρότερος άνεμος και ώρες με μηχανή, με την καλύτερη αναχώρηση, Πέμπτη στις 14:00, σημειωμένη με αστέρι.",coords:"",caption:"Λέρος → Ρόδος, αναχωρήσεις από Τετάρτη 08:00",card:!0},{id:"stays",number:"05",kicker:"Παύσεις σκαφών",title:"Πού μένουν τα άλλα σκάφη.",text:"Πού αφήνουν τα πληρώματα το σκάφος τους για δύο μήνες το καλοκαίρι, και πού περνούν τον χειμώνα; Οι παύσεις σκαφών δείχνουν τα λιμάνια και τα αγκυροβόλια όπου σταμάτησαν σκάφη — από λίγες μέρες έως πάνω από έξι μήνες, ανά εποχή.",points:["Φίλτρο ανά διάρκεια παραμονής","Δες ποιους μήνες μένουν σκάφη σε ένα σημείο","Βρες δημοφιλή λιμάνια διαχείμασης"],image:"stay-detail",alt:"Πρέβεζα: τυπική διάρκεια παραμονής και οι μήνες κατά τους οποίους μένουν εκεί σκάφη.",coords:"38°57′N · 020°45′E",caption:"Πρέβεζα, διάρκεια παραμονής και εποχή"},{id:"hotspots",number:"06",kicker:"Hotspots",title:"Βρείτε το πιο ήσυχο αγκυροβόλι.",text:"Πού συνωστίζονται τα σκάφη τον Αύγουστο και πού υπάρχει ακόμα χώρος; Τα Hotspots δείχνουν, μήνα με μήνα, πόσο πολυσύχναστη είναι κάθε ιστιοπλοϊκή περιοχή. Το Ιόνιο και ο Σαρωνικός λάμπουν, ενώ η Άνδρος, μια μέρα πλεύση από την Αθήνα, μένει ήσυχη.",points:["Από ήσυχο έως πολυσύχναστο","Κάθε μήνα του χρόνου","Οι πιο πολυσύχναστοι και οι πιο ήσυχοι μήνες σε κάθε σημείο"],image:"hotspots",alt:"Πόσο πολυσύχναστες είναι οι ελληνικές ιστιοπλοϊκές περιοχές τον Αύγουστο: γεμάτες γύρω από τα Ιόνια νησιά και στον Σαρωνικό, ήσυχες ανοιχτά της Άνδρου, με ανοιχτό τον επιθεωρητή σημείου.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Ελλάδα, Αύγουστος"},{id:"spot",number:"07",kicker:"Προφίλ σημείου",title:"Όλα για ένα σημείο, με μια ματιά.",text:"Κράτησε πατημένο οποιοδήποτε σημείο του χάρτη ή κάνε δεξί κλικ πάνω του, και το προφίλ σημείου συγκεντρώνει τα πάντα για τον μήνα που διαλέγεις: άνεμο και κατάσταση θάλασσας, καταιγίδες, πόσο το προστατεύει το ανάγλυφο, καθώς και τις παύσεις σκαφών και τις διαδρομές κοντά. Ο Γάιος στους Παξούς τον Σεπτέμβριο: τον περισσότερο χρόνο άπνοια ή ασθενής άνεμος, ήρεμη έως ελαφριά θάλασσα και καταιγίδες περίπου μία στις έξι ημέρες. Η λωρίδα των μηνών δείχνει ότι ο Νοέμβριος είναι ο μήνας με τις περισσότερες καταιγίδες.",points:["Άνεμος, κατάσταση θάλασσας και καταιγίδες για ένα σημείο και έναν μήνα","Παύσεις σκαφών και διαδρομές σε ακτίνα 5 ναυτικών μιλίων","Κάθε μήνας αξιολογημένος με μια ματιά, ως σύνδεσμος για το πλήρωμά σου"],image:"spot",alt:"Το προφίλ σημείου για τον Γάιο στους Παξούς τον Σεπτέμβριο: άνεμος και κατάσταση θάλασσας, καταιγίδες, προστασία από το ανάγλυφο, παύσεις σκαφών και διαδρομές κοντά, και κάθε μήνας αξιολογημένος με μια ματιά.",coords:"",caption:"Γάιος, Παξοί, Σεπτέμβριος",card:!0},{id:"wind",number:"08",kicker:"Άνεμος",title:"Πόσο βοριά να περιμένεις;",text:"Διάλεξε κατεύθυνση και μήνα: τον Ιούλιο το κεντρικό Αιγαίο βάφεται βαθύ μπλε. Αυτό είναι το μελτέμι. Πάτησε σε ένα σημείο κοντά στη Μύκονο και θα δεις ότι τον Ιούλιο φυσάει από βορρά στο 60% των ωρών ή και παραπάνω.",points:["Ένταση και κατεύθυνση για κάθε μήνα","Άνεμος ανά ώρα της ημέρας","Πάτησε σε ένα σημείο για τις τιμές του"],image:"wind",alt:"Πόσο συχνά φυσάει βοριάς στο Αιγαίο τον Ιούλιο, με ανοιχτή την επιθεώρηση σημείου κοντά στη Μύκονο.",coords:"37°36′N · 025°00′E",caption:"Βόρειος άνεμος, Αιγαίο, Ιούλιος"},{id:"waves",number:"09",kicker:"Κύματα",title:"Μάθε τη θάλασσα πριν ξεκινήσεις.",text:"Πόσες μέρες τον μήνα φέρνουν κύματα 2,5 m και πάνω; Τον Ιανουάριο φαίνεται καθαρά πόσο μακριά φτάνει ο μιστράλ πάνω από τον Κόλπο του Λέοντος.",points:["Από ήρεμη έως πολύ τρικυμιώδη θάλασσα","Φουσκοθαλασσιά και κοντός, απότομος κυματισμός","Κάθε μήνας του χρόνου"],image:"waves",alt:"Ημέρες τρικυμίας στη δυτική Μεσόγειο τον Ιανουάριο.",coords:"41°00′N · 005°00′E",caption:"Ημέρες τρικυμίας, δυτική Μεσόγειος, Ιανουάριος"},{id:"risk",number:"10",kicker:"Κίνδυνος καταιγίδας",title:"Ποιο λιμάνι βλέπει λιγότερες καταιγίδες;",text:"Ο κίνδυνος καταιγίδας συνδυάζει πόσο συχνά ξεσπούν καταιγίδες, πόσο βίαιες είναι και πώς τις διαμορφώνουν τα βουνά, τα ακρωτήρια και η ανοιχτή θάλασσα — για κάθε μήνα και ακόμη και από κόλπο σε κόλπο. Πάτησε σε ένα σημείο, μετά σε ένα δεύτερο, και δες πόσο μεγαλύτερο ή μικρότερο κίνδυνο έχει το δεύτερο. Η Πρέβεζα και το Μεσολόγγι είναι και τα δύο δημοφιλή για διαχείμαση: τον Νοέμβριο, το Μεσολόγγι έχει 27% μικρότερο κίνδυνο καταιγίδας.",points:["Ημέρες καταιγίδας, πυκνότητα κεραυνών και ανάγλυφο σε μία τιμή","Διαφορές ακόμη και από κόλπο σε κόλπο","Πάτησε σε δύο σημεία για να τα συγκρίνεις"],image:"risk",alt:"Κίνδυνος καταιγίδας στο Ιόνιο τον Νοέμβριο: πρώτα επιλεγμένη η Πρέβεζα, μετά το Μεσολόγγι, και η κάρτα του σημείου δείχνει 27% μικρότερο κίνδυνο.",coords:"38°40′N · 021°10′E",caption:"Πρέβεζα έναντι Μεσολογγίου, Νοέμβριος",markers:[{x:34.09,y:27.12,text:"Πρέβεζα, πρώτη επιλογή: τιμή κινδύνου 50 τον Νοέμβριο.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Μεσολόγγι, 47 ν.μ. μακριά: 27% μικρότερος κίνδυνος καταιγίδας.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Δεδομένα κεραυνών",title:"Πόσο συχνά, πόσο βίαια, πόσο πιθανά.",text:"Πίσω από τον κίνδυνο βρίσκονται τρία επίπεδα που μπορείς να ανοίξεις και ξεχωριστά, με την ίδια κλίμακα κάθε μήνα. Τον Σεπτέμβριο η Μεσόγειος δείχνει γιατί χρειάζονται και τα τρία: οι καταιγίδες είναι συχνότερες κατά μήκος των ακτών της Αδριατικής και του Ιονίου, οι κεραυνοί πυκνότεροι πάνω από τη θάλασσα ανάμεσα σε Ιταλία και Ελλάδα, και οι συνθήκες που ευνοούν τις καταιγίδες απλώνονται πολύ νότια.",points:["Ημέρες καταιγίδας: πόσο συχνά ξεσπούν καταιγίδες, 2013–2025","Πυκνότητα κεραυνών: πόσο βίαιες είναι","Συνθήκες καταιγίδων: πού μπορούν να σχηματιστούν, 1994–2023"],image:"days",alt:"Ημέρες καταιγίδας στη Μεσόγειο τον Σεπτέμβριο.",coords:"40°00′N · 015°00′E",caption:"Ημέρες καταιγίδας, Μεσόγειος, Σεπτέμβριος",panels:[{label:"Ημέρες καταιγίδας",image:"days",alt:"Ημέρες καταιγίδας στη Μεσόγειο τον Σεπτέμβριο.",caption:"Ημέρες καταιγίδας, Μεσόγειος, Σεπτέμβριος"},{label:"Πυκνότητα κεραυνών",image:"density",alt:"Πυκνότητα κεραυνών στη Μεσόγειο τον Σεπτέμβριο.",caption:"Πυκνότητα κεραυνών, Μεσόγειος, Σεπτέμβριος"},{label:"Συνθήκες καταιγίδων",image:"potential",alt:"Συνθήκες καταιγίδων στη Μεσόγειο τον Σεπτέμβριο.",caption:"Συνθήκες καταιγίδων, Μεσόγειος, Σεπτέμβριος"}]},{id:"terrain",number:"12",kicker:"Έκθεση λόγω αναγλύφου",title:"Ίδιος κόλπος, άλλη θωράκιση.",text:"Ο κίνδυνος καταιγίδας σου λέει ποιον κόλπο. Η έκθεση λόγω αναγλύφου σου λέει ποια πλευρά του: οι γύρω λόφοι μπορούν να θωρακίσουν ένα αγκυροβόλιο από τους κεραυνούς, και το επίπεδο δείχνει πόσο καλά προστατεύει το ανάγλυφο κάθε σημείο ενός κόλπου, για να διαλέξεις το καλύτερο σημείο πριν ρίξεις άγκυρα.",points:["Σύγκρινε σημεία μέσα στον ίδιο κόλπο","Λεπτομερή υψομετρικά δεδομένα ανάλυσης 30 m"],image:"terrain",alt:"Έκθεση λόγω αναγλύφου στον κόλπο της Κόμιζα στο Βις της Κροατίας.",coords:"43°02′N · 016°05′E",caption:"Κόλπος της Κόμιζα, Βις",markers:[{x:56.9,y:57.69,text:"Μικρή θωράκιση από το γύρω ανάγλυφο.",color:"#762a83"},{x:53.84,y:26.35,text:"Κάποια θωράκιση από το γύρω ανάγλυφο.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Μεγαλύτερη θωράκιση από το γύρω ανάγλυφο.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Βυθός",title:"Άμμος ή ποσειδώνια;",text:"Πριν ρίξεις άγκυρα: το επίπεδο Βυθός δείχνει άμμο, λάσπη, βράχο, θαλάσσια λιβάδια και κοράλλια κατά μήκος της ακτής, από τη Μεσόγειο ως τους τροπικούς. Στον κόλπο της Πάλμα μια φαρδιά ζώνη λιβαδιού απλώνεται κατά μήκος της ακτής και η άμμος βρίσκεται πιο έξω. Η αγκυροβολία πάνω σε ποσειδώνια απαγορεύεται σε όλο και περισσότερα μέρη, οπότε αξίζει να το ξέρεις πριν φτάσεις.",points:["Άμμος, λάσπη, βράχος, λιβάδια και κοράλλια","Ευρώπη και ρηχές τροπικές ακτές","Ανοιχτό σε όλους"],image:"seabed",alt:"Ο βυθός στον κόλπο της Πάλμα, Μαγιόρκα: φαρδιά ζώνη θαλάσσιου λιβαδιού κατά μήκος της ακτής, άμμος πιο έξω, ο επιθεωρητής σημείου δείχνει λιβάδι.",coords:"39°30′N · 002°37′E",caption:"Βυθός, κόλπος της Πάλμα"}],story:{kicker:"Η ιστορία μας",title:"Γεννήθηκε από μια στιγμή τρόμου.",text:"Τον Οκτώβριο του 2024 η οικογένειά μας έπλεε στο Ιόνιο, όταν ένας κεραυνός έπεσε ακριβώς δίπλα στο σκάφος μας. Εκείνη η στιγμή γέννησε ένα απλό ερώτημα: είμαστε πιο ασφαλείς εδώ ή στην άλλη πλευρά του κόλπου; Το IncusGrid ξεκίνησε ως η απάντηση — και έγινε ένας χάρτης με όλα όσα θα θέλαμε να ξέρουμε πριν από εκείνη τη σεζόν.",more:"Διάβασε όλη την ιστορία (στα αγγλικά)",link:`${e}/blog/introducing-incusgrid/`,place:"Ηγουμενίτσα, Ελλάδα",note:"Εκεί γεννήθηκε η ιδέα"},fromBlog:{kicker:"Από το blog",title:"Ιστορίες δεδομένων από τη θάλασσα.",all:"Όλα τα άρθρα",note:"Άρθρα στα αγγλικά."},devices:{kicker:"Web & Android",title:"Στο κατάστρωμα ή στο τραπέζι χαρτών.",text:"Χρησιμοποίησε το IncusGrid σε οποιονδήποτε browser ή εγκατάστησε την εφαρμογή Android. Αναζήτησε την περιοχή όπου πλέεις και εξερεύνησέ την σε κινητό, tablet ή laptop.",points:["Χωρίς εγκατάσταση στον browser","Εφαρμογή Android στο Google Play","Διαθέσιμο σε 19 γλώσσες"],web:"Άνοιξε στον browser",android:"Κατέβασέ το από το Google Play",phoneAlt:"Η εφαρμογή Android του IncusGrid με παύσεις σκαφών γύρω από τα Ιόνια νησιά."},final:{title:"Σχεδίασε την επόμενη σεζόν σου. Και την επόμενη πλεύση σου.",text:"Διαδρομές, παύσεις σκαφών, άνεμος, κύματα και κεραυνοί από πολλά χρόνια πραγματικών δεδομένων, συν την πρόγνωση 10 ημερών και τον σχεδιαστή πλεύσης — σε έναν χάρτη.",cta:"Άνοιξε τον χάρτη"},disclaimerLabel:"Προσοχή",disclaimer:"Το IncusGrid είναι φτιαγμένο για τον σχεδιασμό και δεν είναι βοήθημα ναυσιπλοΐας. Οι διαδρομές είναι σχηματικές, και οι παύσεις σκαφών προκύπτουν από διακοπές στις αναφορές θέσης, όχι από επιβεβαιωμένες θέσεις ελλιμενισμού. Ο σχεδιαστής πλεύσης χρησιμοποιεί ένα απλό πολικό διάγραμμα, χωρίς ρεύματα και χωρίς την επίδραση των κυμάτων στην ταχύτητα του σκάφους, και δεν σε οδηγεί μέσα στο λιμάνι. Πριν βγεις στη θάλασσα, έλεγξε πάντα τις τρέχουσες προγνώσεις, τους επίσημους ναυτικούς χάρτες και τις τοπικές συνθήκες.",footer:{blog:"Blog",legal:"Νομικές πληροφορίες",privacy:"Πολιτική απορρήτου",terms:"Όροι χρήσης",cookies:"Ρυθμίσεις cookies",support:"Υποστήριξη",madeWith:"Φτιαγμένο με",made:"στην Πορτογαλία",englishOnly:"Οι νομικές σελίδες είναι στα αγγλικά."}},h={path:"/hr",htmlLang:"hr",ogLocale:"hr_HR",meta:{title:"IncusGrid · Lokalno znanje i rute prema prognozi za jedriličare",description:"Jedriličarske rute i stanke brodova iz stvarnih plovidbi, godine podataka o vjetru, valovima i munjama, uz prognozu za 10 dana i planiranje rute prema vremenu za tvoj brod. Planiraj sezonu i plovidbu na jednoj karti.",keywords:"weather routing, ruta prema prognozi, planer plovidbe, planiranje rute, planiranje isplovljavanja, nautička prognoza, prognoza vjetra, polarni dijagram jedrilice, jedriličarske rute, krstarenje jedrilicom, sidrište, marina, zimovanje broda, statistika vjetra, stanje mora, valovi, munje, grmljavina, rizik od grmljavine, gustoća munja, planiranje plovidbe, jedrilica, nautika, jedrenje Sredozemljem, morsko dno, posidonija, morska cvjetnica, sidrenje na pijesku"},nav:{routes:"Rute",passages:"Plovidbe",stays:"Stanke brodova",weather:"Vrijeme",thunderstorms:"Munje",blog:"Blog",openApp:"Otvori kartu"},hero:{position:"Sailing intelligence",lead:"IncusGrid pretvara godine podataka u lokalno znanje koje svakoj posadi treba prije isplovljavanja: stvarna kretanja brodova, vjetar, valovi i munje na jednoj karti. Uz to prognoza za sljedećih 10 dana i planer plovidbe koji tvoj brod vodi kroz prognozirani vjetar, sat po sat, s udarima vjetra i valovima duž rute.",ctaApp:"Otvori kartu",ctaAndroid:"Android aplikacija",heroAlt:"Jedriličarske rute Karipskim morem, od Hispaniole do Malih Antila i obale Južne Amerike, iscrtane prema stvarnim plovidbama brodova na krstarenju.",heroCaption:"Jedriličarske rute, Karipsko more · svi mjeseci",notes:[{label:"Brodovi",value:"Tisuće"},{label:"Kretanja",value:"Milijuni"},{label:"Udari munja",value:"Milijarde"},{label:"Prognoza",value:"10 dana"},{label:"Pokrivenost",value:"Cijeli svijet"}]},contrast:{kicker:"Sezona i prognoza",title:"Sezona ti kaže koji mjesec. Prognoza ti kaže koji dan.",text:"Kojim prijelazom posade plove u lipnju? Gdje brodovi zimuju? Koji mjesec donosi meltemi, i koja luka za zimovanje ima manje grmljavine u studenom? Odgovori koji se pokažu tek kad gledaš mnogo godina odjednom. Kako se isplovljavanje približava, planer plovidbe na temelju prognoze za 10 dana izračuna kada krenuti i kada stižeš."},chapters:[{id:"routes",number:"01",kicker:"Jedriličarske rute",title:"Planiraj prijelaze s iskustvom tisuća posada.",text:"Tisuće stvarnih plovidbi pokazuju kada prijelaz ima smisla, u kojem smjeru, i gdje posade isplovljavaju i stižu. Prevladavajući vjetrovi, dobra mjesta za čekanje vremenskog prozora i sigurno pristajanje nakon noći na moru već su ugrađeni. Od Sicilije do Jonskih otoka, na primjer, većina brodova u svibnju i lipnju plovi na istok, a u rujnu se vraća.",points:["Popularnost po mjesecu i smjeru","Najpopularnije rute u trenutnom prikazu karte","Podijeli rutu sa svojom posadom"],image:"route-detail",alt:"Odabrana ruta od Sicilije do Jonskih otoka, s popularnošću u svakom mjesecu i smjeru.",coords:"38°12′N · 017°30′E",caption:"Sicilija → Jonski otoci, po mjesecu i smjeru"},{id:"route-wind",number:"02",kicker:"Vjetar duž rute",title:"Upoznaj vjetar prije nego što isploviš.",text:"Svaka ruta pokazuje vjetar koji na njoj možeš očekivati, mjesec po mjesec: odakle puše, koliko jako, koliki dio prijelaza ploviš u orcu, s bočnim ili krmenim vjetrom i koliko je često more mirno. Od Sicilije do Jonskih otoka u svibnju: vjetar sa sjeverozapada, 3 Bf, više od pola puta s krmenim vjetrom.",points:["Prevladavajući vjetar i jačina u Beaufortima za svaki mjesec","U orcu, s bočnim ili krmenim vjetrom na kursu rute","Stanje mora duž rute"],image:"route-wind",alt:"Kartica rute od Sicilije do Jonskih otoka: prevladavajući vjetar, jačina u Beaufortima, jačina vjetra, kurs i stanje mora za svaki mjesec, s odabranim svibnjem.",coords:"",caption:"Sicilija → Jonski otoci, vjetar u svibnju",card:!0},{id:"passage",number:"03",kicker:"Planer plovidbe · ruta prema prognozi",title:"Znaj kada stižeš prije nego što isploviš.",text:"Zadaj polazište i odredište, odaberi svoj brod, i planer plovidbe pronalazi brzu rutu kroz prognozirani vjetar sljedećih 10 dana, sat po sat, s udarima vjetra i valovima duž rute. S Lerosa na Rodos, 86 nautičkih milja, polazak u srijedu u 20:00: jedna noć s krmenim vjetrom do najviše 15 čvorova, bez motora, dolazak u četvrtak nešto prije jedanaest.",points:["Dolazak, najjači vjetar, udari i valovi, sati pod jedrima i pod motorom","Za tvoj brod: tip i veličina ili vlastiti polarni dijagram","U plovidbi tvoj položaj uz plan, a ostatak rute ponovno izračunat"],image:"passage",alt:"Planer plovidbe s rutom od Lerosa do Rodosa na prognozi vjetra: točke rute s vremenima, brod noću južno od Kosa, a pokraj toga dolazak, najjači vjetar te sati jedrenja i motora.",coords:"36°48′N · 027°50′E",caption:"Leros → Rodos, polazak u srijedu u 20:00 · prognoza od 31. listopada"},{id:"departures",number:"04",kicker:"Usporedi polaske",title:"Pravi dan za isplovljavanje.",text:"Planer računa istu plovidbu za do dvanaest polazaka u razmaku od šest sati i stavlja jedno uz drugo dolazak, trajanje, najjači vjetar i vrijeme pod motorom. Ako s Lerosa isploviš u srijedu ujutro, na Rodos stižeš u ponoć; ako isploviš u srijedu navečer, sljedećeg jutra. Zvjezdica označava polazak s najmanje vremena pod motorom i u orcu.",points:["Do dvanaest polazaka, svakih šest sati","Dodirni redak da vidiš njegovu rutu","Spremi plovidbu ili je podijeli s posadom, uvijek na najnovijoj prognozi"],image:"departures",alt:"Tablica polazaka od Lerosa do Rodosa, svakih šest sati od srijede u 08:00: dolazak, trajanje, najjači vjetar i sati pod motorom, s najboljim polaskom, u četvrtak u 14:00, označenim zvjezdicom.",coords:"",caption:"Leros → Rodos, polasci od srijede u 08:00",card:!0},{id:"stays",number:"05",kicker:"Stanke brodova",title:"Gdje drugi brodovi ostaju.",text:"Gdje posade ostavljaju brod na dva ljetna mjeseca, a gdje provode zimu? Stanke brodova pokazuju luke i sidrišta u kojima su brodovi napravili stanku — od nekoliko dana do više od šest mjeseci, po sezoni.",points:["Filtriraj po trajanju stanke","Pogledaj u kojim mjesecima brodovi ostaju na nekom mjestu","Pronađi popularne luke za zimovanje"],image:"stay-detail",alt:"Preveza: uobičajeno trajanje stanke i mjeseci u kojima brodovi ondje ostaju.",coords:"38°57′N · 020°45′E",caption:"Preveza, trajanje stanke i sezona"},{id:"hotspots",number:"06",kicker:"Hotspotovi",title:"Pronađite mirnije sidrište.",text:"Gdje se brodovi gužvaju u kolovozu, a gdje još ima mjesta? Hotspotovi iz mjeseca u mjesec pokazuju koliko je koje nautičko područje prometno. Jonsko more i Saronski zaljev svijetle, dok Andros, dan plovidbe od Atene, ostaje miran.",points:["Od mirnog do prepunog","Svaki mjesec u godini","Najprometniji i najmirniji mjeseci na svakoj točki"],image:"hotspots",alt:"Koliko su grčka nautička područja prometna u kolovozu: gužva oko Jonskih otoka i u Saronskom zaljevu, mirno uz Andros, s otvorenim inspektorom točke.",coords:"38°24′N · 023°36′E",caption:"Hotspotovi, Grčka, kolovoz"},{id:"spot",number:"07",kicker:"Profil mjesta",title:"Sve o jednom mjestu, na prvi pogled.",text:"Drži prst na bilo kojem mjestu na karti ili klikni na njega desnom tipkom miša, i profil mjesta objedinjuje sve za mjesec koji odabereš: vjetar i stanje mora, grmljavinska nevremena, koliko ga teren štiti te stanke brodova i rute u blizini. Gaios na Paksosu u rujnu: većinom tišina ili slab vjetar, mirno do malo valovito more i grmljavina otprilike svaki šesti dan. Traka mjeseci pokazuje da studeni donosi najviše grmljavinskih nevremena.",points:["Vjetar, stanje mora i grmljavinska nevremena za jedno mjesto i mjesec","Stanke brodova i rute u krugu od 5 nautičkih milja","Svaki mjesec ocijenjen na prvi pogled, kao poveznica za tvoju posadu"],image:"spot",alt:"Profil mjesta za Gaios na Paksosu u rujnu: vjetar i stanje mora, grmljavinska nevremena, zaštita terena, stanke brodova i rute u blizini te svaki mjesec ocijenjen na prvi pogled.",coords:"",caption:"Gaios, Paksos, rujan",card:!0},{id:"wind",number:"08",kicker:"Vjetar",title:"Koliko sjevernog vjetra možeš očekivati?",text:"Odaberi smjer i mjesec: u srpnju središnji Egej postaje tamnoplav. To je meltemi. Dodirni točku kod Mikonosa i vidjet ćeš da u srpnju vjetar puše sa sjevera u 60 % svih sati ili više.",points:["Jačina i smjer za svaki mjesec","Vjetar po dobu dana","Dodirni bilo koju točku za njezine vrijednosti"],image:"wind",alt:"Koliko često u srpnju vjetar puše sa sjevera u Egejskom moru, s otvorenim detaljima točke kod Mikonosa.",coords:"37°36′N · 025°00′E",caption:"Vjetar sa sjevera, Egejsko more, srpanj"},{id:"waves",number:"09",kicker:"Valovi",title:"Upoznaj stanje mora prije isplovljavanja.",text:"Koliko dana u mjesecu donosi valove od 2,5 m ili više? U siječnju se jasno vidi dokle mistral seže preko Lionskog zaljeva.",points:["Od mirnog do vrlo uzburkanog mora","Mrtvo more i kratko, strmo more","Svaki mjesec u godini"],image:"waves",alt:"Dani s uzburkanim morem u zapadnom Sredozemlju u siječnju.",coords:"41°00′N · 005°00′E",caption:"Dani uzburkanog mora, zapadno Sredozemlje, siječanj"},{id:"risk",number:"10",kicker:"Rizik od grmljavine",title:"Koja luka ima manje grmljavine?",text:"Rizik od grmljavine objedinjuje koliko se često grmljavina javlja, koliko je žestoka i kako je oblikuju planine, rtovi i otvoreno more — za svaki mjesec i sve do pojedinačnih uvala. Dodirni jedno mjesto, zatim drugo, i vidjet ćeš koliko je rizik na drugom veći ili manji. Preveza i Mesolongi popularni su za zimovanje: u studenom Mesolongi ima 27 % manji rizik od grmljavine.",points:["Dani s grmljavinom, gustoća munja i teren u jednoj vrijednosti","Razlike sve do pojedinačnih uvala","Dodirni dva mjesta i usporedi ih"],image:"risk",alt:"Rizik od grmljavine u Jonskom moru u studenom: prvo dodirnuta Preveza, zatim Mesolongi, a prikaz točke pokazuje 27 % manji rizik.",coords:"38°40′N · 021°10′E",caption:"Preveza naspram Mesolongija, studeni",markers:[{x:34.09,y:27.12,text:"Preveza, dodirnuta prva: vrijednost rizika 50 u studenom.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Mesolongi, 47 NM dalje: 27 % manji rizik od grmljavine.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Podaci o munjama",title:"Koliko često, koliko žestoko, koliko vjerojatno.",text:"Iza rizika stoje tri sloja koje možeš otvoriti i zasebno, u svakom mjesecu na istoj skali. U rujnu Sredozemlje pokazuje zašto trebaju sva tri: grmljavina je najčešća uz jadransku i jonsku obalu, munje su najgušće nad morem između Italije i Grčke, a uvjeti povoljni za grmljavinu sežu daleko na jug.",points:["Dani s grmljavinom: koliko se često javlja, 2013–2025","Gustoća munja: koliko je žestoka","Uvjeti za grmljavinu: gdje se može razviti, 1994–2023"],image:"days",alt:"Dani s grmljavinom na Sredozemlju u rujnu.",coords:"40°00′N · 015°00′E",caption:"Dani s grmljavinom, Sredozemlje, rujan",panels:[{label:"Dani s grmljavinom",image:"days",alt:"Dani s grmljavinom na Sredozemlju u rujnu.",caption:"Dani s grmljavinom, Sredozemlje, rujan"},{label:"Gustoća munja",image:"density",alt:"Gustoća munja na Sredozemlju u rujnu.",caption:"Gustoća munja, Sredozemlje, rujan"},{label:"Uvjeti za grmljavinu",image:"potential",alt:"Uvjeti za grmljavinu na Sredozemlju u rujnu.",caption:"Uvjeti za grmljavinu, Sredozemlje, rujan"}]},{id:"terrain",number:"12",kicker:"Izloženost terenu",title:"Ista uvala, drukčiji zaklon.",text:"Rizik od grmljavine kaže ti koju uvalu odabrati. Izloženost terenu kaže ti koju stranu uvale: okolna brda mogu zakloniti sidrište od munja, a sloj pokazuje koliko dobro teren štiti svaki dio uvale, pa možeš odabrati bolje mjesto prije nego što baciš sidro.",points:["Usporedi mjesta unutar iste uvale","Detaljni podaci o visinama u rezoluciji 30 m"],image:"terrain",alt:"Izloženost terenu u uvali Komiža na Visu.",coords:"43°02′N · 016°05′E",caption:"Uvala Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Malo zaklanjanja okolnim terenom.",color:"#762a83"},{x:53.84,y:26.35,text:"Djelomično zaklanjanje okolnim terenom.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Veće zaklanjanje okolnim terenom.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Morsko dno",title:"Pijesak ili morska cvjetnica?",text:"Prije nego što spustiš sidro: sloj Morsko dno prikazuje pijesak, mulj, stijenu, livade morskih cvjetnica i koralje uz obalu, od Sredozemlja do tropa. U zaljevu Palme širok pojas livade proteže se uz obalu, a pijesak je dalje od nje. Sidrenje na posidoniji zabranjeno je na sve više mjesta, pa se isplati znati prije dolaska.",points:["Pijesak, mulj, stijena, livade i koralji","Europa i plitke tropske obale","Otvoreno za sve"],image:"seabed",alt:"Morsko dno u zaljevu Palme, Mallorca: širok pojas livade uz obalu, dalje pijesak, inspektor točke prikazuje morsku cvjetnicu.",coords:"39°30′N · 002°37′E",caption:"Morsko dno, zaljev Palme"}],story:{kicker:"Naša priča",title:"Nastalo iz trenutka straha.",text:"U listopadu 2024. naša je obitelj plovila Jonskim morem kad je munja udarila tik uz naš brod. Taj je trenutak otvorio jednostavno pitanje: jesmo li sigurniji ovdje ili na drugoj strani uvale? IncusGrid je počeo kao odgovor — i izrastao u kartu svega što bismo voljeli da smo znali prije te sezone.",more:"Pročitaj cijelu priču (na engleskom)",link:`${e}/blog/introducing-incusgrid/`,place:"Igumenica, Grčka",note:"Gdje je ideja nastala"},fromBlog:{kicker:"S bloga",title:"Priče iz podataka, s mora.",all:"Svi članci",note:"Članci na engleskom."},devices:{kicker:"Web & Android",title:"Na palubi ili za kartografskim stolom.",text:"Koristi IncusGrid u bilo kojem pregledniku ili instaliraj Android aplikaciju. Pronađi svoje područje plovidbe i istražuj ga na mobitelu, tabletu ili laptopu.",points:["U pregledniku bez instalacije","Android aplikacija na Google Playu","Dostupno na 19 jezika"],web:"Otvori u pregledniku",android:"Preuzmi na Google Playu",phoneAlt:"IncusGrid Android aplikacija sa stankama brodova oko Jonskih otoka."},final:{title:"Planiraj sljedeću sezonu. I sljedeću plovidbu.",text:"Rute, stanke brodova, vjetar, valovi i munje iz mnogo godina stvarnih podataka, uz prognozu za 10 dana i planer plovidbe — na jednoj karti.",cta:"Otvori kartu"},disclaimerLabel:"Napomena",disclaimer:"IncusGrid je napravljen za planiranje i nije navigacijsko pomagalo. Rute su ucrtane shematski. Stanke brodova izvedene su iz prekida u javljanju položaja brodova, a ne iz potvrđenih vezova. Planer plovidbe koristi jednostavan polarni dijagram, bez struja i bez utjecaja valova na brzinu broda, i ne vodi te do same luke. Prije isplovljavanja uvijek provjeri aktualne prognoze, službene pomorske karte i lokalne uvjete.",footer:{blog:"Blog",legal:"Impresum",privacy:"Pravila privatnosti",terms:"Uvjeti korištenja",cookies:"Postavke kolačića",support:"Podrška",madeWith:"Napravljeno s",made:"u Portugalu",englishOnly:"Pravne stranice su na engleskom."}},b={path:"/tr",htmlLang:"tr",ogLocale:"tr_TR",meta:{title:"IncusGrid · Denizciler için yerel bilgi ve hava durumuna göre rota",description:"Gerçek seyirlerden yelken rotaları ve tekne molaları, yıllara yayılan rüzgâr, dalga ve yıldırım verileri, artı 10 günlük tahmin ve teknene özel hava durumuna göre rota planlama. Sezonunu ve seyrini tek haritada planla.",keywords:"hava durumuna göre rota, weather routing, seyir rotası planlama, rota planlama, kalkış zamanı planlama, yelken hava tahmini, rüzgâr tahmini, tekne polar diyagramı, yelken rotaları, yelkenli gezi, mavi yolculuk, koy, demir yeri, marina, kışlama, rüzgâr istatistiği, meltem, dalga, deniz durumu, yıldırım, fırtına, fırtına riski, yıldırım yoğunluğu, seyir planlama, yelkenli, tekne, deniz tabanı, deniz çayırı, posidonia, demirleme zemini"},nav:{routes:"Rotalar",passages:"Seyir planı",stays:"Tekne molaları",weather:"Hava",thunderstorms:"Yıldırım",blog:"Blog",openApp:"Haritayı aç"},hero:{position:"Sailing intelligence",lead:"IncusGrid, yıllara yayılan verileri her mürettebatın demir almadan önce bilmesi gereken yerel bilgiye dönüştürür: gerçek tekne hareketleri, rüzgâr, dalgalar ve yıldırımlar tek bir haritada. Üstelik önümüzdeki 10 günün tahmini ve tekneni tahmin edilen rüzgârla saat saat yönlendiren bir seyir planlayıcı; rüzgâr hamleleri ve dalgalar da yol boyunca görünür.",ctaApp:"Haritayı aç",ctaAndroid:"Android uygulaması",heroAlt:"Karayip Denizi’nde, Hispaniola’dan Küçük Antiller’e ve Güney Amerika kıyılarına uzanan, gezi teknelerinin gerçek seyirlerinden çizilmiş yelken rotaları.",heroCaption:"Yelken rotaları, Karayip Denizi · tüm aylar",notes:[{label:"Tekne",value:"Binlerce"},{label:"Hareket",value:"Milyonlarca"},{label:"Yıldırım düşmesi",value:"Milyarlarca"},{label:"Tahmin",value:"10 gün"},{label:"Kapsam",value:"Dünya geneli"}]},contrast:{kicker:"Sezon ve tahmin",title:"Sezon sana hangi ayı söyler. Tahmin ise hangi günü.",text:"Mürettebatlar haziranda hangi geçişi yapıyor? Tekneler kışı nerede geçiriyor? Meltem hangi ay başlıyor, kasımda hangi kışlama limanında daha az fırtına oluyor? Bu cevaplar ancak birçok yıla birden baktığında ortaya çıkar. Kalkış yaklaştıkça seyir planlayıcı, 10 günlük tahmine göre ne zaman çıkacağını ve ne zaman varacağını hesaplar."},chapters:[{id:"routes",number:"01",kicker:"Yelken rotaları",title:"Geçişleri binlerce mürettebatın deneyimiyle planla.",text:"Binlerce gerçek seyir, bir geçişin ne zaman mantıklı olduğunu, hangi yönde yapıldığını ve mürettebatların nereden ayrılıp nereye vardığını gösterir. Hâkim rüzgârlar, hava penceresi beklemek için iyi yerler ve denizde geçen bir gecenin ardından güvenli bir varış noktası zaten bu verinin içinde. Örneğin Sicilya’dan İyon Adaları’na teknelerin çoğu mayıs ve haziranda doğuya gider, eylülde geri döner.",points:["Aya ve yöne göre popülerlik","Harita görünümündeki en popüler rotalar","Bir rotayı mürettebatınla paylaş"],image:"route-detail",alt:"Sicilya’dan İyon Adaları’na giden rota seçili; her ay ve yöndeki popülerliğiyle birlikte.",coords:"38°12′N · 017°30′E",caption:"Sicilya → İyon Adaları, aya ve yöne göre"},{id:"route-wind",number:"02",kicker:"Rota boyunca rüzgâr",title:"Halatları çözmeden önce rüzgârı tanı.",text:"Her rota, ay ay bekleyebileceğin rüzgârı gösterir: nereden estiğini, ne kadar sert estiğini, geçişin ne kadarını orsa, apaz veya pupa seyirde geçireceğini ve denizin ne sıklıkla sakin kaldığını. Mayısta Sicilya’dan İyon Adaları’na: kuzeybatıdan rüzgâr, 3 Beaufort, yolun yarısından fazlası pupa.",points:["Her ay için hâkim rüzgâr ve Beaufort kuvveti","Rotanın yönünde orsa, apaz veya pupa","Rota boyunca deniz durumu"],image:"route-wind",alt:"Sicilya’dan İyon Adaları’na rota kartı: her ay için hâkim rüzgâr, Beaufort kuvveti, rüzgâr kuvveti, seyir ve deniz durumu; mayıs seçili.",coords:"",caption:"Sicilya → İyon Adaları, mayısta rüzgâr",card:!0},{id:"passage",number:"03",kicker:"Seyir planlayıcı · hava durumuna göre rota",title:"Demir almadan önce ne zaman varacağını bil.",text:"Başlangıç ve varış noktasını belirle, tekneni seç; seyir planlayıcı önümüzdeki 10 günün tahmin edilen rüzgârında saat saat hızlı bir rota bulur, yol boyunca rüzgâr hamlelerini ve dalgaları da gösterir. Leros’tan Rodos’a, 86 deniz mili, çarşamba 20:00’de kalkış: en fazla 15 knot rüzgârla pupa geçen bir gece, motor yok, perşembe saat on birden az önce varış.",points:["Varış, en güçlü rüzgâr, hamleler ve dalgalar, yelkenle ve motorla geçen saatler","Teknene göre: tip ve boy ya da kendi polar diyagramın","Seyir sırasında konumun planın yanında, rotanın geri kalanı yeniden hesaplanır"],image:"passage",alt:"Rüzgâr tahmini üzerinde Leros’tan Rodos’a rotayla seyir planlayıcı: saatli ara noktalar, gece Kos’un güneyindeki tekne ve yanında varış, en güçlü rüzgâr, yelken ve motor saatleri.",coords:"36°48′N · 027°50′E",caption:"Leros → Rodos, çarşamba 20:00 kalkış · 31 Ekim tarihli tahmin"},{id:"departures",number:"04",kicker:"Kalkışları karşılaştır",title:"Demir almak için doğru gün.",text:"Planlayıcı aynı seyri altı saat arayla en fazla on iki kalkış için hesaplar ve varışı, süreyi, en güçlü rüzgârı ve motorla geçen süreyi yan yana koyar. Leros’tan çarşamba sabahı çıkarsan Rodos’a gece yarısı, çarşamba akşamı çıkarsan ertesi sabah varırsın. Yıldız, motorla ve orsada en az zaman geçirilen kalkışı işaretler.",points:["Altı saatte bir, en fazla on iki kalkış","Rotasını görmek için bir satıra dokun","Bir seyri kaydet ya da mürettebatınla paylaş, her zaman en güncel tahminle"],image:"departures",alt:"Leros’tan Rodos’a kalkış tablosu, çarşamba 08:00’den itibaren altı saatte bir: varış, süre, en güçlü rüzgâr ve motor saatleri; en iyi kalkış, perşembe 14:00, yıldızla işaretli.",coords:"",caption:"Leros → Rodos, çarşamba 08:00’den itibaren kalkışlar",card:!0},{id:"stays",number:"05",kicker:"Tekne molaları",title:"Diğer tekneler nerede kalıyor?",text:"Mürettebatlar yazın teknelerini iki aylığına nerede bırakıyor, kışı nerede geçiriyor? Tekne molaları, teknelerin birkaç günden altı aydan uzun sürelere kadar mola verdiği limanları ve demir yerlerini mevsime göre gösterir.",points:["Kalış süresine göre filtrele","Teknelerin bir yerde hangi aylarda kaldığını gör","Popüler kışlama limanlarını keşfet"],image:"stay-detail",alt:"Preveze: tipik kalış süresi ve teknelerin orada kaldığı aylar.",coords:"38°57′N · 020°45′E",caption:"Preveze, kalış süresi ve mevsim"},{id:"hotspots",number:"06",kicker:"Hotspotlar",title:"Daha sakin koyu bulun.",text:"Ağustosta tekneler nerede kalabalıklaşıyor, nerede hâlâ yer var? Hotspotlar her seyir bölgesinin ne kadar yoğun olduğunu ay ay gösterir. İyon Denizi ve Saronik Körfezi parlarken Atina’ya bir günlük seyir mesafesindeki Andros sakin kalır.",points:["Sakinden kalabalığa","Yılın her ayı","Her noktada en yoğun ve en sakin aylar"],image:"hotspots",alt:"Yunan seyir bölgelerinin ağustostaki yoğunluğu: İyon Adaları çevresinde ve Saronik Körfezi’nde kalabalık, Andros açıklarında sakin, nokta denetçisi açık.",coords:"38°24′N · 023°36′E",caption:"Hotspotlar, Yunanistan, ağustos"},{id:"spot",number:"07",kicker:"Yer profili",title:"Bir yer hakkında her şey, tek bakışta.",text:"Haritada herhangi bir yere basılı tut ya da sağ tıkla; yer profili seçtiğin ay için her şeyi bir araya getirir: rüzgâr ve deniz durumu, gök gürültülü fırtınalar, arazinin orayı ne kadar koruduğu, yakındaki tekne molaları ve rotalar. Eylülde Paksos’taki Gaios: çoğu zaman sakin ya da hafif rüzgâr, sakin ya da hafif dalgalı deniz ve yaklaşık altı günde bir gök gürültülü fırtına. Ay şeridi, en çok gök gürültülü fırtınanın kasımda olduğunu gösterir.",points:["Bir yer ve bir ay için rüzgâr, deniz durumu ve gök gürültülü fırtınalar","5 deniz mili içindeki tekne molaları ve rotalar","Her ay tek bakışta değerlendirilmiş, mürettebatın için bir bağlantı olarak"],image:"spot",alt:"Eylülde Paksos’taki Gaios için yer profili: rüzgâr ve deniz durumu, gök gürültülü fırtınalar, arazinin koruması, yakındaki tekne molaları ve rotalar ve tek bakışta değerlendirilmiş her ay.",coords:"",caption:"Gaios, Paksos, eylül",card:!0},{id:"wind",number:"08",kicker:"Rüzgâr",title:"Ne kadar kuzey rüzgârı beklemelisin?",text:"Bir yön ve bir ay seç: temmuzda Ege’nin ortası koyu maviye döner. İşte meltem bu. Mikonos yakınında bir noktaya dokun; temmuzda rüzgârın saatlerin %60’ında ya da daha fazlasında kuzeyden estiğini görürsün.",points:["Her ay için kuvvet ve yön","Günün saatine göre rüzgâr","Değerlerini görmek için herhangi bir noktaya dokun"],image:"wind",alt:"Temmuzda Ege Denizi’nde rüzgârın ne sıklıkla kuzeyden estiği; Mikonos yakınında nokta incelemesi açık.",coords:"37°36′N · 025°00′E",caption:"Kuzeyden rüzgâr, Ege Denizi, temmuz"},{id:"waves",number:"09",kicker:"Dalgalar",title:"Yola çıkmadan denizi tanı.",text:"Ayda kaç gün 2,5 m ve üzeri dalga getiriyor? Ocakta Mistral’in Lion Körfezi üzerinden ne kadar uzağa ulaştığı açıkça görülür.",points:["Sakin denizden çok dalgalı denize","Ölü dalga ve kısa, dik dalgalar","Yılın her ayı"],image:"waves",alt:"Ocakta Batı Akdeniz’de dalgalı geçen günler.",coords:"41°00′N · 005°00′E",caption:"Dalgalı günler, Batı Akdeniz, ocak"},{id:"risk",number:"10",kicker:"Fırtına riski",title:"Hangi limanda daha az fırtına olur?",text:"Fırtına riski, fırtınaların ne sıklıkta görüldüğünü, ne kadar şiddetli olduklarını ve dağların, burunların ve açık denizin onları nasıl şekillendirdiğini her ay için ve tek tek koylara kadar tek bir değerde toplar. Önce bir yere, sonra başka bir yere dokun; ikincisinde riskin ne kadar yüksek ya da düşük olduğunu gör. Preveze ve Mesolongi kışlama için ikisi de sevilen yerler: kasımda Mesolongi’de fırtına riski %27 daha düşük.",points:["Fırtınalı günler, yıldırım yoğunluğu ve arazi tek bir değerde","Tek tek koylara kadar farklar","Karşılaştırmak için iki yere dokun"],image:"risk",alt:"Kasımda İyon Denizi’nde fırtına riski: önce Preveze’ye, sonra Mesolongi’ye dokunulmuş; nokta penceresi %27 daha düşük risk gösteriyor.",coords:"38°40′N · 021°10′E",caption:"Preveze ile Mesolongi, kasım",markers:[{x:34.09,y:27.12,text:"Preveze, ilk dokunulan: kasımda risk değeri 50.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Mesolongi, 47 deniz mili ötede: fırtına riski %27 daha düşük.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Yıldırım verileri",title:"Ne sıklıkta, ne şiddette, ne olasılıkla.",text:"Riskin arkasında, tek tek de açabileceğin ve her ay aynı ölçekte gösterilen üç katman var. Eylülde Akdeniz, üçüne birden neden ihtiyaç olduğunu gösteriyor: fırtınalar en sık Adriyatik ve İyon kıyılarında görülüyor, yıldırımlar en yoğun İtalya ile Yunanistan arasındaki denizde düşüyor, fırtınaya elverişli koşullar ise çok güneye kadar uzanıyor.",points:["Fırtınalı günler: fırtınalar ne sıklıkta görülüyor, 2013–2025","Yıldırım yoğunluğu: ne kadar şiddetliler","Gök gürültülü fırtına potansiyeli: nerede oluşabilirler, 1994–2023"],image:"days",alt:"Eylülde Akdeniz’de fırtınalı günler.",coords:"40°00′N · 015°00′E",caption:"Fırtınalı günler, Akdeniz, eylül",panels:[{label:"Fırtınalı günler",image:"days",alt:"Eylülde Akdeniz’de fırtınalı günler.",caption:"Fırtınalı günler, Akdeniz, eylül"},{label:"Yıldırım yoğunluğu",image:"density",alt:"Eylülde Akdeniz’de yıldırım yoğunluğu.",caption:"Yıldırım yoğunluğu, Akdeniz, eylül"},{label:"Gök gürültülü fırtına potansiyeli",image:"potential",alt:"Eylülde Akdeniz’de gök gürültülü fırtına potansiyeli.",caption:"Gök gürültülü fırtına potansiyeli, Akdeniz, eylül"}]},{id:"terrain",number:"12",kicker:"Araziye bağlı maruziyet",title:"Aynı koy, farklı perdeleme.",text:"Fırtına riski sana hangi koyu seçeceğini söyler, araziye bağlı maruziyet ise koyun hangi tarafını: çevredeki tepeler bir demir yerini yıldırıma karşı perdeleyebilir ve bu katman, arazinin bir koyun her bölümünü ne kadar iyi koruduğunu gösterir; böylece demir atmadan önce daha iyi yeri seçebilirsin.",points:["Aynı koy içindeki noktaları karşılaştır","30 m çözünürlüklü ayrıntılı yükseklik verisi"],image:"terrain",alt:"Hırvatistan’da, Vis adasındaki Komiža koyunda araziye bağlı maruziyet.",coords:"43°02′N · 016°05′E",caption:"Komiža koyu, Vis",markers:[{x:56.9,y:57.69,text:"Çevredeki araziden az perdeleme.",color:"#762a83"},{x:53.84,y:26.35,text:"Çevredeki araziden bir miktar perdeleme.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Çevredeki araziden daha güçlü perdeleme.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Deniz tabanı",title:"Kum mu, deniz çayırı mı?",text:"Demir atmadan önce: Deniz tabanı katmanı kıyı boyunca kumu, çamuru, kayayı, deniz çayırını ve mercanı gösterir; Akdeniz’den tropiklere kadar. Palma Körfezi’nde kıyı boyunca geniş bir deniz çayırı kuşağı uzanır, kum daha açıktadır. Posidonia üzerine demirlemek giderek daha fazla yerde yasak, bu yüzden varmadan önce bilmek işe yarar.",points:["Kum, çamur, kaya, deniz çayırı ve mercan","Avrupa ve sığ tropik kıyılar","Herkese açık"],image:"seabed",alt:"Palma Körfezi’nde deniz tabanı, Mallorca: kıyı boyunca geniş bir deniz çayırı kuşağı, daha açıkta kum, nokta denetçisi deniz çayırını gösteriyor.",coords:"39°30′N · 002°37′E",caption:"Deniz tabanı, Palma Körfezi"}],story:{kicker:"Hikâyemiz",title:"Kıl payı atlatılan bir anda doğdu.",text:"Ekim 2024’te ailemizle İyon Denizi’nde seyrederken teknemizin hemen yanına yıldırım düştü. O an basit bir soru doğurdu: Burada mı daha güvendeyiz, yoksa koyun öbür tarafında mı? IncusGrid bu sorunun cevabı olarak başladı — ve o sezondan önce bilmek isteyeceğimiz her şeyin haritasına dönüştü.",more:"Hikâyenin tamamını oku (İngilizce)",link:`${e}/blog/introducing-incusgrid/`,place:"İgumenitsa, Yunanistan",note:"Fikrin doğduğu yer"},fromBlog:{kicker:"Blogdan",title:"Denizden veri hikâyeleri.",all:"Tüm yazılar",note:"Yazılar İngilizce."},devices:{kicker:"Web & Android",title:"Güvertede ya da harita masasında.",text:"IncusGrid’i herhangi bir tarayıcıda kullan ya da Android uygulamasını yükle. Seyir bölgeni ara ve telefonda, tablette veya dizüstü bilgisayarda keşfet.",points:["Tarayıcıda kurulum gerektirmez","Google Play’de Android uygulaması","19 dilde kullanılabilir"],web:"Tarayıcıda aç",android:"Google Play’den indir",phoneAlt:"İyon Adaları çevresindeki tekne molalarını gösteren IncusGrid Android uygulaması."},final:{title:"Bir sonraki sezonunu planla. Bir sonraki seyrini de.",text:"Uzun yılların gerçek verisinden rotalar, tekne molaları, rüzgâr, dalgalar ve yıldırımlar, artı 10 günlük tahmin ve seyir planlayıcı — tek bir haritada.",cta:"Haritayı aç"},disclaimerLabel:"Dikkat",disclaimer:"IncusGrid planlama için yapılmıştır ve seyir yardımcısı değildir. Rotalar şematik olarak çizilmiştir; tekne molaları ise doğrulanmış bağlama yerlerinden değil, tekne bildirimlerindeki aralardan çıkarılır. Seyir planlayıcı basit bir polar kullanır; akıntıları ve dalgaların tekne hızına etkisini hesaba katmaz ve seni limanın içine kadar yönlendirmez. Denize açılmadan önce her zaman güncel tahminleri, resmi deniz haritalarını ve yerel koşulları kontrol et.",footer:{blog:"Blog",legal:"Yasal Bilgiler",privacy:"Gizlilik Politikası",terms:"Kullanım Koşulları",cookies:"Çerez Ayarları",support:"Destek",madeWith:"Portekiz’de",made:"ile yapıldı",englishOnly:"Yasal sayfalar İngilizcedir."}},y={path:"/pt-br",htmlLang:"pt-BR",ogLocale:"pt_BR",meta:{title:"IncusGrid · Conhecimento local e roteamento meteorológico para velejadores",description:"Rotas de navegação e pausas dos barcos de travessias reais, anos de dados de vento, ondas e raios, mais a previsão de 10 dias e o roteamento meteorológico para o seu barco. Planeje sua temporada e sua travessia em um só mapa.",keywords:"roteamento meteorológico, weather routing, planejamento de travessia, planejamento de rota, planejamento da partida, previsão do tempo para velejar, previsão de vento, polar do barco, rotas de navegação, rotas de veleiro, velejar, cruzeiro à vela, vida a bordo, ancoradouro, fundeadouro, marina, invernagem, estatísticas de vento, estado do mar, ondas, raios, tempestades, risco de tempestade, densidade de raios, planejamento de velejada, veleiro, fundo do mar, pradaria marinha, posidonia, fundo para ancorar"},nav:{routes:"Rotas",passages:"Travessias",stays:"Pausas dos barcos",weather:"Tempo",thunderstorms:"Raios",blog:"Blog",openApp:"Abrir o mapa"},hero:{position:"Sailing intelligence",lead:"O IncusGrid transforma anos de dados no conhecimento local de que toda tripulação precisa antes de soltar as amarras: movimentos reais de barcos, vento, ondas e raios em um só mapa. E ainda a previsão para os próximos 10 dias e um planejador de travessias que traça a rota do seu barco pelo vento previsto, hora a hora, com rajadas e ondas ao longo do caminho.",ctaApp:"Abrir o mapa",ctaAndroid:"App para Android",heroAlt:"Rotas de navegação pelo Mar do Caribe, de Hispaniola às Pequenas Antilhas e à costa da América do Sul, traçadas a partir de travessias reais de veleiros de cruzeiro.",heroCaption:"Rotas de navegação, Mar do Caribe · todos os meses",notes:[{label:"Barcos",value:"Milhares"},{label:"Movimentos",value:"Milhões"},{label:"Descargas de raios",value:"Bilhões"},{label:"Previsão",value:"10 dias"},{label:"Cobertura",value:"Mundial"}]},contrast:{kicker:"Temporada e previsão",title:"A temporada diz qual mês. A previsão diz qual dia.",text:"Que travessia as tripulações fazem em junho? Onde os barcos passam o inverno? Que mês traz o meltemi, e qual porto de invernagem tem menos tempestades em novembro? Respostas que só aparecem quando você olha muitos anos de uma vez. Quando a partida se aproxima, o planejador de travessias calcula com a previsão de 10 dias quando sair e quando você chega."},chapters:[{id:"routes",number:"01",kicker:"Rotas de navegação",title:"Planeje travessias com a experiência de milhares de tripulações.",text:"Milhares de viagens reais mostram quando uma travessia faz sentido, em que sentido, e onde as tripulações partem e chegam. Os ventos predominantes, bons lugares para esperar uma janela de tempo e uma chegada segura depois de uma noite no mar já estão ali. Da Sicília às Ilhas Jônicas, por exemplo, a maioria dos barcos segue para leste em maio e junho e volta em setembro.",points:["Popularidade por mês e sentido","As rotas mais populares na área visível do mapa","Compartilhe uma rota com sua tripulação"],image:"route-detail",alt:"A rota da Sicília às Ilhas Jônicas selecionada, com a popularidade em cada mês e sentido.",coords:"38°12′N · 017°30′E",caption:"Sicília → Ilhas Jônicas, por mês e sentido"},{id:"route-wind",number:"02",kicker:"O vento na rota",title:"Conheça o vento antes de soltar as amarras.",text:"Cada rota mostra o vento que você pode esperar nela, mês a mês: de onde ele vem, com que força sopra, quanto da travessia você navega em orça, de través ou de popa, e com que frequência o mar fica calmo. Da Sicília às Ilhas Jônicas em maio: vento de noroeste, força 3 Beaufort, mais da metade do caminho de popa.",points:["Vento predominante e força Beaufort para cada mês","Orça, través ou popa no rumo da rota","Estado do mar ao longo da rota"],image:"route-wind",alt:"O cartão da rota da Sicília às Ilhas Jônicas: vento predominante, força Beaufort, força do vento, mareação e estado do mar para cada mês, com maio selecionado.",coords:"",caption:"Sicília → Ilhas Jônicas, vento em maio",card:!0},{id:"passage",number:"03",kicker:"Planejador de travessias · roteamento meteorológico",title:"Saiba quando vai chegar antes de soltar as amarras.",text:"Defina uma origem e um destino, escolha seu barco, e o planejador de travessias encontra uma rota rápida pelo vento previsto dos próximos 10 dias, hora a hora, com rajadas e ondas ao longo do caminho. De Leros a Rodes, 86 milhas náuticas, saindo na quarta-feira às 20:00: uma noite de popa com no máximo 15 nós de vento, sem motor, chegando na quinta-feira pouco antes das onze.",points:["Chegada, vento mais forte, rajadas e ondas, horas à vela e a motor","Para o seu barco: tipo e tamanho, ou sua própria polar","Navegando, sua posição em relação à rota planejada e o resto do percurso recalculado"],image:"passage",alt:"O planejador de travessias com a rota de Leros a Rodes sobre a previsão de vento: waypoints com horários, o barco ao sul de Kos à noite e, ao lado, a chegada, o vento mais forte e as horas à vela e a motor.",coords:"36°48′N · 027°50′E",caption:"Leros → Rodes, saída quarta-feira 20:00 · previsão de 31 de outubro"},{id:"departures",number:"04",kicker:"Comparar partidas",title:"O dia certo para soltar as amarras.",text:"O planejador calcula a mesma travessia para até doze partidas, com seis horas de intervalo, e compara chegada, duração, vento mais forte e tempo a motor. Saindo de Leros na quarta-feira de manhã, você chega a Rodes à meia-noite; saindo na quarta-feira à noite, na manhã seguinte. A estrela marca a partida com menos tempo a motor e em orça.",points:["Até doze partidas, a cada seis horas","Toque em uma linha para ver a rota","Salve uma travessia ou compartilhe com sua tripulação, sempre com a previsão mais recente"],image:"departures",alt:"A tabela de partidas de Leros a Rodes, a cada seis horas a partir de quarta-feira às 08:00: chegada, duração, vento mais forte e horas a motor, com a melhor partida, quinta-feira às 14:00, marcada com uma estrela.",coords:"",caption:"Leros → Rodes, partidas a partir de quarta-feira 08:00",card:!0},{id:"stays",number:"05",kicker:"Pausas dos barcos",title:"Onde os outros barcos ficam.",text:"Onde as tripulações deixam o barco por dois meses no verão, e onde passam o inverno? As pausas dos barcos mostram os portos e ancoradouros onde barcos ficaram parados — de poucos dias a mais de seis meses, por temporada.",points:["Filtre pela duração da permanência","Veja em que meses os barcos ficam em um lugar","Descubra portos populares para invernar"],image:"stay-detail",alt:"Preveza: permanência típica e os meses em que os barcos ficam ali.",coords:"38°57′N · 020°45′E",caption:"Preveza, permanência e temporada"},{id:"hotspots",number:"06",kicker:"Hotspots",title:"Encontre o ancoradouro mais tranquilo.",text:"Onde os barcos se aglomeram em agosto, e onde ainda há espaço? Hotspots mostra, mês a mês, o movimento de cada área de navegação. O mar Jônico e o golfo Sarônico brilham, enquanto Andros, a um dia de navegação de Atenas, continua tranquila.",points:["De tranquilo a lotado","Todos os meses do ano","Meses mais e menos movimentados em qualquer ponto"],image:"hotspots",alt:"O movimento das áreas de navegação gregas em agosto: lotado em torno das ilhas Jônicas e no golfo Sarônico, tranquilo perto de Andros, com o inspetor de ponto aberto.",coords:"38°24′N · 023°36′E",caption:"Hotspots, Grécia, agosto"},{id:"spot",number:"07",kicker:"Ficha do lugar",title:"Tudo sobre um lugar, em uma só ficha.",text:"Mantenha pressionado qualquer lugar do mapa, ou clique nele com o botão direito, e a ficha do lugar reúne tudo para o mês que você escolher: vento e estado do mar, tempestades, o quanto o relevo protege o local, e as pausas dos barcos e rotas por perto. Gaios, em Paxos, em setembro: na maior parte do tempo calmaria ou vento fraco, mar calmo a pouco agitado e tempestades em cerca de um a cada seis dias. A faixa dos meses mostra que novembro é o mês com mais tempestades.",points:["Vento, estado do mar e tempestades para um lugar e um mês","Pausas dos barcos e rotas num raio de 5 milhas náuticas","Cada mês avaliado de relance, como link para a sua tripulação"],image:"spot",alt:"A ficha do lugar para Gaios, em Paxos, em setembro: vento e estado do mar, tempestades, proteção do relevo, pausas dos barcos e rotas por perto e cada mês avaliado de relance.",coords:"",caption:"Gaios, Paxos, setembro",card:!0},{id:"wind",number:"08",kicker:"Vento",title:"Quanto vento norte esperar?",text:"Escolha uma direção e um mês: em julho, o centro do Egeu fica azul-escuro. É o meltemi. Toque em um ponto perto de Mykonos e você vê o vento soprar do norte em 60% de todas as horas de julho, ou mais.",points:["Intensidade e direção para cada mês","Vento por horário","Toque em qualquer ponto para ver os números"],image:"wind",alt:"Com que frequência o vento sopra do norte no Mar Egeu em julho, com o inspetor de ponto aberto perto de Mykonos.",coords:"37°36′N · 025°00′E",caption:"Vento norte, Mar Egeu, julho"},{id:"waves",number:"09",kicker:"Ondas",title:"Conheça o mar antes de sair.",text:"Quantos dias por mês trazem ondas de 2,5 m ou mais? Em janeiro, o alcance do mistral sobre o Golfo de Leão aparece com clareza.",points:["De mar calmo a muito agitado","Ondulação e mar curto e íngreme","Todos os meses do ano"],image:"waves",alt:"Dias de mar agitado no Mediterrâneo ocidental em janeiro.",coords:"41°00′N · 005°00′E",caption:"Dias agitados, Mediterrâneo ocidental, janeiro"},{id:"risk",number:"10",kicker:"Risco de tempestade",title:"Qual porto tem menos tempestades?",text:"O risco de tempestade reúne a frequência das tempestades, a violência delas e o modo como montanhas, cabos e mar aberto as moldam — para cada mês e até o nível de cada baía. Toque em um lugar, depois em outro, e veja quanto risco a mais ou a menos o segundo tem. Preveza e Messolonghi são dois lugares populares para passar o inverno: em novembro, Messolonghi tem 27% menos risco de tempestade.",points:["Dias de tempestade, densidade de raios e relevo em um só valor","Diferenças até o nível de cada baía","Toque em dois lugares para compará-los"],image:"risk",alt:"Risco de tempestade no Mar Jônico em novembro: primeiro Preveza, depois Messolonghi, com o inspetor de pontos mostrando 27% menos risco.",coords:"38°40′N · 021°10′E",caption:"Preveza x Messolonghi, novembro",markers:[{x:34.09,y:27.12,text:"Preveza, tocada primeiro: valor de risco 50 em novembro.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Messolonghi, a 47 mn: 27% menos risco de tempestade.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Dados de raios",title:"Com que frequência, com que força, com que chance.",text:"Por trás do risco há três camadas que você também pode abrir separadamente, na mesma escala em todos os meses. Em setembro, o Mediterrâneo mostra por que você precisa das três: as tempestades são mais frequentes ao longo das costas do Adriático e do Jônico, os raios são mais densos sobre o mar entre a Itália e a Grécia, e as condições favoráveis a tempestades chegam bem ao sul.",points:["Dias de tempestade: com que frequência ocorrem, 2013–2025","Densidade de raios: com que violência","Potencial de tempestades: onde podem se formar, 1994–2023"],image:"days",alt:"Dias de tempestade no Mediterrâneo em setembro.",coords:"40°00′N · 015°00′E",caption:"Dias de tempestade, Mediterrâneo, setembro",panels:[{label:"Dias de tempestade",image:"days",alt:"Dias de tempestade no Mediterrâneo em setembro.",caption:"Dias de tempestade, Mediterrâneo, setembro"},{label:"Densidade de raios",image:"density",alt:"Densidade de raios no Mediterrâneo em setembro.",caption:"Densidade de raios, Mediterrâneo, setembro"},{label:"Potencial de tempestades",image:"potential",alt:"Potencial de tempestades no Mediterrâneo em setembro.",caption:"Potencial de tempestades, Mediterrâneo, setembro"}]},{id:"terrain",number:"12",kicker:"Exposição do terreno",title:"Mesma baía, outra proteção.",text:"O risco de tempestade diz qual baía. A exposição do terreno diz qual lado dela: os morros ao redor podem proteger um ancoradouro dos raios, e a camada mostra o quanto o relevo protege cada parte de uma baía, para você escolher o melhor ponto antes de lançar a âncora.",points:["Compare pontos dentro da mesma baía","Dados de elevação detalhados de 30 m"],image:"terrain",alt:"Exposição do terreno na baía de Komiža, em Vis, Croácia.",coords:"43°02′N · 016°05′E",caption:"Baía de Komiža, Vis",markers:[{x:56.9,y:57.69,text:"Pouca proteção do relevo ao redor.",color:"#762a83"},{x:53.84,y:26.35,text:"Alguma proteção do relevo ao redor.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Maior proteção do relevo ao redor.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Fundo do mar",title:"Areia ou pradaria marinha?",text:"Antes de lançar a âncora: a camada Fundo do mar mostra areia, lama, rocha, pradarias marinhas e coral ao longo da costa, do Mediterrâneo aos trópicos. Na baía de Palma uma faixa larga de pradaria acompanha a costa, e a areia fica mais afastada. Ancorar sobre a posidônia é proibido em cada vez mais lugares, então vale a pena saber antes de chegar.",points:["Areia, lama, rocha, pradarias e coral","Europa e costas tropicais rasas","Aberto a todos"],image:"seabed",alt:"O fundo do mar na baía de Palma, Maiorca: uma faixa larga de pradaria junto à costa, areia mais afastada, com o inspetor mostrando pradaria marinha.",coords:"39°30′N · 002°37′E",caption:"Fundo do mar, baía de Palma"}],story:{kicker:"Nossa história",title:"Nasceu de um susto.",text:"Em outubro de 2024, nossa família velejava no Mar Jônico quando um raio caiu bem ao lado do nosso barco. Aquele momento levantou uma pergunta simples: estamos mais seguros aqui ou do outro lado da baía? O IncusGrid começou como a resposta — e virou um mapa de tudo o que gostaríamos de ter sabido antes daquela temporada.",more:"Leia a história completa (em inglês)",link:`${e}/blog/introducing-incusgrid/`,place:"Igoumenitsa, Grécia",note:"Onde a ideia nasceu"},fromBlog:{kicker:"Do blog",title:"Histórias de dados direto do mar.",all:"Todos os posts",note:"Posts em inglês."},devices:{kicker:"Web & Android",title:"No convés ou na mesa de navegação.",text:"Use o IncusGrid em qualquer navegador ou instale o app para Android. Busque sua área de navegação e explore no celular, no tablet ou no notebook.",points:["Sem instalação no navegador","App para Android no Google Play","Disponível em 19 idiomas"],web:"Abrir no navegador",android:"Baixar no Google Play",phoneAlt:"App do IncusGrid para Android mostrando pausas dos barcos ao redor das Ilhas Jônicas."},final:{title:"Planeje sua próxima temporada. E sua próxima travessia.",text:"Rotas, pausas dos barcos, vento, ondas e raios de muitos anos de dados reais, mais a previsão de 10 dias e o planejador de travessias — em um só mapa.",cta:"Abrir o mapa"},disclaimerLabel:"Atenção",disclaimer:"O IncusGrid foi feito para planejamento e não é auxílio à navegação. As rotas são traçadas de forma esquemática, e as pausas dos barcos são deduzidas de interrupções nos registros de posição, não de vagas confirmadas. O planejador de travessias usa uma polar simples, sem correntes nem o efeito das ondas na velocidade do barco, e não leva você até dentro do porto. Sempre confira as previsões atuais, as cartas náuticas oficiais e as condições locais antes de sair para o mar.",footer:{blog:"Blog",legal:"Aviso legal",privacy:"Política de privacidade",terms:"Termos de uso",cookies:"Configurações de cookies",support:"Suporte",madeWith:"Feito com",made:"em Portugal",englishOnly:"As páginas jurídicas estão em inglês."}},f={path:"/ru",htmlLang:"ru",ogLocale:"ru_RU",meta:{title:"IncusGrid · Местные знания и погодная маршрутизация для яхтсменов",description:"Парусные маршруты и стоянки судов по реальным переходам, многолетние данные о ветре, волнах и молниях, а также прогноз на 10 дней и погодная маршрутизация для вашей яхты. Планируйте сезон и переход на одной карте.",keywords:"погодная маршрутизация, weather routing, планирование перехода, прокладка маршрута, время выхода, прогноз погоды для яхтсменов, прогноз ветра, поляра яхты, парусные маршруты, яхтенные маршруты, планирование яхтенного похода, якорная стоянка, марина, зимовка яхты, статистика ветра, волнение моря, волны, грозы, молнии, риск гроз, плотность молний, мельтеми, яхтинг, парусный туризм, круизный яхтинг, морское дно, морская трава, посидония, грунт для якоря"},nav:{routes:"Маршруты",passages:"Переходы",stays:"Стоянки",weather:"Погода",thunderstorms:"Молнии",blog:"Блог",openApp:"Открыть карту"},hero:{position:"Sailing intelligence",lead:"IncusGrid превращает годы данных в местные знания, которые нужны каждому экипажу до отхода: реальные перемещения судов, ветер, волны и молнии на одной карте. А ещё прогноз на ближайшие 10 дней и планировщик переходов, который ведёт вашу яхту по прогнозному ветру, час за часом, с порывами и волнами по пути.",ctaApp:"Открыть карту",ctaAndroid:"Приложение для Android",heroAlt:"Парусные маршруты в Карибском море — от острова Гаити до Малых Антильских островов и побережья Южной Америки, построенные по реальным переходам крейсерских яхт.",heroCaption:"Парусные маршруты, Карибское море · все месяцы",notes:[{label:"Суда",value:"Тысячи"},{label:"Перемещения",value:"Миллионы"},{label:"Удары молний",value:"Миллиарды"},{label:"Прогноз",value:"10 дней"},{label:"Охват",value:"Весь мир"}]},contrast:{kicker:"Сезон и прогноз",title:"Сезон подскажет месяц. Прогноз подскажет день.",text:"Каким переходом экипажи идут в июне? Где суда зимуют? В каком месяце дует мельтеми и в какой гавани для зимовки меньше гроз в ноябре? Такие ответы видны, только когда смотришь сразу на много лет. Когда выход уже близко, планировщик переходов по прогнозу на 10 дней рассчитает, когда выходить и когда вы придёте."},chapters:[{id:"routes",number:"01",kicker:"Парусные маршруты",title:"Планируйте переходы на опыте тысяч экипажей.",text:"Тысячи реальных переходов показывают, когда переход имеет смысл, в каком направлении, откуда экипажи выходят и куда приходят. Преобладающие ветры, удобные места, чтобы дождаться погодного окна, и безопасный подход к берегу после ночи в море уже учтены. Например, от Сицилии к Ионическим островам большинство судов идёт на восток в мае и июне, а возвращается в сентябре.",points:["Популярность по месяцам и направлениям","Самые популярные маршруты в текущей области карты","Делитесь маршрутом со своим экипажем"],image:"route-detail",alt:"Выбран маршрут от Сицилии к Ионическим островам: его популярность по месяцам и направлениям.",coords:"38°12′N · 017°30′E",caption:"Сицилия → Ионические острова, по месяцам и направлениям"},{id:"route-wind",number:"02",kicker:"Ветер на маршруте",title:"Знайте ветер до того, как отдать швартовы.",text:"Каждый маршрут показывает, какого ветра на нём ждать, месяц за месяцем: откуда он дует, насколько сильно, какую часть перехода вы идёте в бейдевинд, галфвинд или попутным ветром и как часто море остаётся спокойным. От Сицилии к Ионическим островам в мае: ветер с северо-запада, 3 балла по Бофорту, больше половины пути попутным ветром.",points:["Преобладающий ветер и сила по Бофорту для каждого месяца","Бейдевинд, галфвинд или попутный ветер на курсе маршрута","Состояние моря вдоль маршрута"],image:"route-wind",alt:"Карточка маршрута от Сицилии к Ионическим островам: преобладающий ветер, сила по Бофорту, сила ветра, курс и состояние моря для каждого месяца, выбран май.",coords:"",caption:"Сицилия → Ионические острова, ветер в мае",card:!0},{id:"passage",number:"03",kicker:"Планировщик переходов · погодная маршрутизация",title:"Знайте время прихода до того, как отдать швартовы.",text:"Задайте точку старта и назначения, выберите свою яхту, и планировщик переходов найдёт быстрый маршрут по прогнозному ветру на ближайшие 10 дней, час за часом, с порывами и волнами по пути. От Лероса до Родоса, 86 морских миль, выход в среду в 20:00: одна ночь попутным ветром не сильнее 15 узлов, без мотора, приход в четверг незадолго до одиннадцати.",points:["Приход, самый сильный ветер, порывы и волны, часы под парусами и под мотором","Для вашей яхты: тип и размер или собственная поляра","В пути ваша позиция рядом с планом и пересчитанный остаток маршрута"],image:"passage",alt:"Планировщик переходов с маршрутом от Лероса до Родоса на прогнозе ветра: путевые точки со временем, яхта ночью южнее Коса, а рядом приход, самый сильный ветер и часы под парусами и под мотором.",coords:"36°48′N · 027°50′E",caption:"Лерос → Родос, выход в среду в 20:00 · прогноз от 31 октября"},{id:"departures",number:"04",kicker:"Сравнение времени выхода",title:"Правильный день, чтобы отдать швартовы.",text:"Планировщик рассчитывает один и тот же переход для нескольких вариантов выхода, до двенадцати, с интервалом в шесть часов и сводит рядом время прихода, продолжительность, самый сильный ветер и время под мотором. Если выйти с Лероса в среду утром, вы придёте на Родос в полночь; если в среду вечером, то на следующее утро. Звёздочкой отмечен выход с наименьшим временем под мотором и в бейдевинд.",points:["До двенадцати вариантов выхода, каждые шесть часов","Коснитесь строки, чтобы увидеть её маршрут","Сохраните переход или поделитесь им с экипажем, всегда по свежему прогнозу"],image:"departures",alt:"Таблица вариантов выхода от Лероса до Родоса, каждые шесть часов начиная со среды 08:00: приход, продолжительность, самый сильный ветер и часы под мотором; лучший выход, в четверг в 14:00, отмечен звёздочкой.",coords:"",caption:"Лерос → Родос, выходы со среды 08:00",card:!0},{id:"stays",number:"05",kicker:"Стоянки судов",title:"Где стоят другие суда.",text:"Где экипажи оставляют лодку на два летних месяца и где проводят зиму? Стоянки судов показывают гавани и якорные стоянки, где суда делали паузу, — от нескольких дней до более чем полугода, по сезонам.",points:["Фильтр по длительности стоянки","В какие месяцы суда стоят в этом месте","Популярные гавани для зимовки"],image:"stay-detail",alt:"Превеза: типичная длительность стоянки и месяцы, когда там стоят суда.",coords:"38°57′N · 020°45′E",caption:"Превеза, длительность стоянки и сезон"},{id:"hotspots",number:"06",kicker:"Хотспоты",title:"Найдите стоянку потише.",text:"Где в августе тесно от яхт, а где ещё есть место? Хотспоты показывают по месяцам, насколько оживлён каждый район плавания. Ионическое море и Сароникос светятся, а Андрос, в дне перехода от Афин, остаётся спокойным.",points:["От спокойного до переполненного","Каждый месяц года","Самые оживлённые и самые спокойные месяцы в любой точке"],image:"hotspots",alt:"Насколько оживлены районы плавания Греции в августе: многолюдно у Ионических островов и в заливе Сароникос, спокойно у Андроса, открыт инспектор точки.",coords:"38°24′N · 023°36′E",caption:"Хотспоты, Греция, август"},{id:"spot",number:"07",kicker:"Профиль места",title:"Всё об одном месте — в одной карточке.",text:"Нажмите и удерживайте любое место на карте или щёлкните по нему правой кнопкой мыши — профиль места соберёт всё за выбранный месяц: ветер и волнение, грозы, насколько рельеф защищает это место, а также стоянки судов и маршруты поблизости. Гайос на Паксосе в сентябре: чаще всего штиль или слабый ветер, спокойное море или слабое волнение и грозы примерно в один день из шести. Полоса месяцев показывает, что больше всего гроз в ноябре.",points:["Ветер, волнение и грозы для одного места и месяца","Стоянки судов и маршруты в радиусе 5 морских миль","Оценка каждого месяца одним взглядом — ссылкой для вашего экипажа"],image:"spot",alt:"Профиль места для Гайоса на Паксосе в сентябре: ветер и волнение, грозы, защита рельефом, стоянки судов и маршруты поблизости и оценка каждого месяца одним взглядом.",coords:"",caption:"Гайос, Паксос, сентябрь",card:!0},{id:"wind",number:"08",kicker:"Ветер",title:"Сколько северного ветра ждать?",text:"Выберите направление и месяц: в июле центральная часть Эгейского моря окрашивается в тёмно-синий. Это мельтеми. Нажмите на точку у Миконоса — и увидите, что в июле ветер дует с севера в 60% всех часов или чаще.",points:["Сила и направление для каждого месяца","Ветер по времени суток","Нажмите на точку, чтобы увидеть её значения"],image:"wind",alt:"Как часто в июле в Эгейском море дует ветер с севера; инспектор точки открыт у Миконоса.",coords:"37°36′N · 025°00′E",caption:"Ветер с севера, Эгейское море, июль"},{id:"waves",number:"09",kicker:"Волны",title:"Знайте волнение до выхода в море.",text:"Сколько дней в месяц приносят волны 2,5 м и выше? В январе хорошо видно, как далеко над Лионским заливом достаёт мистраль.",points:["От спокойного до очень неспокойного моря","Зыбь и короткая крутая волна","Каждый месяц года"],image:"waves",alt:"Дни с сильным волнением в западном Средиземноморье в январе.",coords:"41°00′N · 005°00′E",caption:"Дни с сильным волнением, западное Средиземноморье, январь"},{id:"risk",number:"10",kicker:"Риск гроз",title:"В какой гавани меньше гроз?",text:"Риск гроз объединяет, как часто случаются грозы, насколько они сильны и как их формируют горы, мысы и открытое море, — для каждого месяца и вплоть до отдельных бухт. Нажмите на одно место, затем на другое — и увидите, насколько выше или ниже риск во втором. Превеза и Месолонгион одинаково популярны для зимовки: в ноябре риск гроз в Месолонгионе на 27% ниже.",points:["Грозовые дни, плотность молний и рельеф в одном значении","Различия вплоть до отдельных бухт","Нажмите на два места, чтобы сравнить их"],image:"risk",alt:"Риск гроз в Ионическом море в ноябре: сначала выбрана Превеза, затем Месолонгион, инспектор точки показывает риск на 27% ниже.",coords:"38°40′N · 021°10′E",caption:"Превеза и Месолонгион в сравнении, ноябрь",markers:[{x:34.09,y:27.12,text:"Превеза, выбрана первой: значение риска 50 в ноябре.",color:"#7b2a83"},{x:58.05,y:72.78,text:"Месолонгион, в 47 морских милях: риск гроз на 27% ниже.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"Данные о молниях",title:"Как часто, как сильно, насколько вероятно.",text:"За риском стоят три слоя, которые можно открыть и по отдельности, — в каждом месяце на одной и той же шкале. В сентябре Средиземное море показывает, зачем нужны все три: чаще всего грозы бывают вдоль адриатического и ионического побережий, плотнее всего молнии бьют над морем между Италией и Грецией, а благоприятные для гроз условия простираются далеко на юг.",points:["Грозовые дни: как часто бывают грозы, 2013–2025","Плотность молний: насколько они сильны","Грозовой потенциал: где они могут сформироваться, 1994–2023"],image:"days",alt:"Грозовые дни в Средиземном море в сентябре.",coords:"40°00′N · 015°00′E",caption:"Грозовые дни, Средиземное море, сентябрь",panels:[{label:"Грозовые дни",image:"days",alt:"Грозовые дни в Средиземном море в сентябре.",caption:"Грозовые дни, Средиземное море, сентябрь"},{label:"Плотность молний",image:"density",alt:"Плотность молний в Средиземном море в сентябре.",caption:"Плотность молний, Средиземное море, сентябрь"},{label:"Грозовой потенциал",image:"potential",alt:"Грозовой потенциал в Средиземном море в сентябре.",caption:"Грозовой потенциал, Средиземное море, сентябрь"}]},{id:"terrain",number:"12",kicker:"Открытость рельефа",title:"Одна бухта — разная защита.",text:"Риск гроз подскажет, какую бухту выбрать. Открытость рельефа — какую её сторону: окружающие холмы могут экранировать якорную стоянку от молний, а слой показывает, насколько хорошо рельеф защищает каждую часть бухты, — чтобы выбрать лучшее место ещё до того, как отдать якорь.",points:["Сравнивайте места в пределах одной бухты","Подробные данные о высотах с разрешением 30 м"],image:"terrain",alt:"Открытость рельефа в бухте Комижа на острове Вис, Хорватия.",coords:"43°02′N · 016°05′E",caption:"Бухта Комижа, остров Вис",markers:[{x:56.9,y:57.69,text:"Слабое экранирование окружающим рельефом.",color:"#762a83"},{x:53.84,y:26.35,text:"Некоторое экранирование окружающим рельефом.",color:"#ecd27a"},{x:35.86,y:27.83,text:"Более сильное экранирование окружающим рельефом.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"Морское дно",title:"Песок или морская трава?",text:"Прежде чем отдать якорь: слой «Морское дно» показывает песок, ил, скалы, заросли морской травы и кораллы вдоль побережья, от Средиземного моря до тропиков. В бухте Пальмы вдоль берега тянется широкая полоса морской травы, а песок лежит дальше от берега. Становиться на якорь на посидонии запрещено во всё большем числе мест, поэтому лучше знать это заранее.",points:["Песок, ил, скалы, морская трава и кораллы","Европа и мелководные тропические побережья","Открыто для всех"],image:"seabed",alt:"Морское дно в бухте Пальмы, Майорка: широкая полоса морской травы вдоль берега, дальше песок, инспектор точки показывает морскую траву.",coords:"39°30′N · 002°37′E",caption:"Морское дно, бухта Пальмы"}],story:{kicker:"Наша история",title:"Всё началось с опасного момента.",text:"В октябре 2024 года наша семья ходила по Ионическому морю, когда молния ударила совсем рядом с нашей лодкой. После этого встал простой вопрос: здесь мы в большей безопасности или на другой стороне бухты? IncusGrid начался как ответ на него — и вырос в карту всего, что нам хотелось бы знать до того сезона.",more:"Читать всю историю (на английском)",link:`${e}/blog/introducing-incusgrid/`,place:"Игуменица, Греция",note:"Где родилась идея"},fromBlog:{kicker:"Из блога",title:"Истории о море в данных.",all:"Все статьи",note:"Статьи на английском."},devices:{kicker:"Веб и Android",title:"На палубе или за штурманским столом.",text:"Пользуйтесь IncusGrid в любом браузере или установите приложение для Android. Найдите свой район плавания и изучайте его на телефоне, планшете или ноутбуке.",points:["В браузере без установки","Приложение для Android в Google Play","Доступно на 19 языках"],web:"Открыть в браузере",android:"Скачать в Google Play",phoneAlt:"Приложение IncusGrid для Android: стоянки судов у Ионических островов."},final:{title:"Спланируйте следующий сезон. И следующий переход.",text:"Маршруты, стоянки судов, ветер, волны и молнии по многолетним реальным данным, а также прогноз на 10 дней и планировщик переходов — на одной карте.",cta:"Открыть карту"},disclaimerLabel:"Внимание",disclaimer:"IncusGrid создан для планирования и не является навигационным пособием. Маршруты нарисованы схематично, а стоянки судов выведены из пауз в сообщениях с судов, а не из подтверждённых мест стоянки. Планировщик переходов использует упрощённую поляру, не учитывает течения и влияние волн на скорость яхты и не прокладывает маршрут в саму гавань. Перед выходом в море всегда проверяйте актуальные прогнозы, официальные карты и местные условия.",footer:{blog:"Блог",legal:"Правовая информация",privacy:"Политика конфиденциальности",terms:"Условия использования",cookies:"Настройки cookie",support:"Поддержка",madeWith:"Сделано с",made:"в Португалии",englishOnly:"Юридические страницы — на английском."}},j={path:"/zh-hans",htmlLang:"zh-Hans",ogLocale:"zh_CN",meta:{title:"IncusGrid · 为帆船手打造的本地知识与气象导航",description:"来自真实航程的航行路线和船舶停留候选地、多年的风、浪和雷电数据，再加上10天预报和为你的船量身计算的气象导航。在一张地图上规划你的航海季和下一段航程。",keywords:"气象导航, 气象航线, 航程规划, 航线规划, 出发时间规划, 帆船天气预报, 风预报, 帆船极曲线, 帆船, 帆船航行, 帆船航线, 巡航, 航海规划, 远洋航行, 锚地, 游艇码头, 帆船过冬, 风况统计, 海况, 海浪, 涌浪, 雷电, 雷暴, 雷暴风险, 闪电密度, 游艇, 地中海帆船, 海底, 海草, 波西多尼亚海草, 锚地底质"},nav:{routes:"路线",passages:"航程规划",stays:"船舶停留候选地",weather:"天气",thunderstorms:"雷电",blog:"博客",openApp:"打开地图"},hero:{position:"Sailing intelligence",lead:"IncusGrid 将多年数据转化为每位船员出航前都需要的本地知识：真实的船只移动、风、浪和雷电尽在一张地图。此外还有未来10天的预报，以及航程规划器：它在预报风中逐小时为你的船规划航线，并显示沿途的阵风和海浪。",ctaApp:"打开地图",ctaAndroid:"Android 应用",heroAlt:"加勒比海的航行路线，从伊斯帕尼奥拉岛经小安的列斯群岛延伸到南美洲海岸，根据巡航帆船的真实航程绘制。",heroCaption:"航行路线，加勒比海 · 全部月份",notes:[{label:"船只",value:"数千艘"},{label:"移动",value:"数百万次"},{label:"雷击",value:"数十亿次"},{label:"预报",value:"10天"},{label:"覆盖范围",value:"全球"}]},contrast:{kicker:"季节与预报",title:"季节告诉你哪个月。预报告诉你哪一天。",text:"六月，船员们走哪条航线？船只在哪里过冬？梅尔特米风在哪个月到来？哪个过冬港在十一月雷暴更少？这些答案，只有把许多年放在一起看时才会浮现。临近出发时，航程规划器会根据10天预报算出何时出发、何时抵达。"},chapters:[{id:"routes",number:"01",kicker:"航行路线",title:"借助数千个船组的经验规划跨海航行。",text:"数千段真实航程告诉你，跨海航行何时合适、朝哪个方向，以及船员从哪里出发、在哪里抵达。盛行风、等待天气窗口的好去处、夜航后安全的登陆点，都已包含其中。比如从西西里岛到爱奥尼亚群岛，大多数船只在五六月向东航行，九月返航。",points:["按月份和方向的热度","当前地图视野内最热门的航线","与船员分享航线"],image:"route-detail",alt:"已选中从西西里岛到爱奥尼亚群岛的航线，显示其按月份和方向的热度。",coords:"38°12′N · 017°30′E",caption:"西西里岛 → 爱奥尼亚群岛，按月份和方向"},{id:"route-wind",number:"02",kicker:"沿途风况",title:"解缆之前，先了解风。",text:"每条航线都按月显示你可以预期的风：从哪里吹来、风力多大、航程中有多少是迎风、横风或顺风航行，以及海面保持平静的频率。比如五月从西西里岛到爱奥尼亚群岛：西北风，蒲福3级，一半以上的航程为顺风。",points:["每月的盛行风和蒲福风级","本航线航向上的迎风、横风或顺风","沿航线的海况"],image:"route-wind",alt:"从西西里岛到爱奥尼亚群岛的航线卡片：每月的盛行风、蒲福风级、风力、航向和海况，已选中五月。",coords:"",caption:"西西里岛 → 爱奥尼亚群岛，五月的风",card:!0},{id:"passage",number:"03",kicker:"航程规划器 · 气象导航",title:"解缆之前，就知道何时抵达。",text:"设定起点和目的地，选择你的船，航程规划器便会在未来10天的预报风中逐小时找出一条快速航线，并显示沿途的阵风和海浪。从莱罗斯岛到罗得岛，86海里，周三20:00出发：顺风航行一夜，风力不超过15节，无需开机，周四11点前不久抵达。",points:["抵达时间、最强风、阵风和海浪、帆航和机航时长","适配你的船：船型和尺寸，或你自己的极曲线","航行途中，你的位置与计划并排显示，剩余航线重新计算"],image:"passage",alt:"航程规划器在风预报上显示从莱罗斯岛到罗得岛的航线：带时间的航点、夜间位于科斯岛以南的船，旁边是抵达时间、最强风以及帆航和机航时长。",coords:"36°48′N · 027°50′E",caption:"莱罗斯岛 → 罗得岛，周三20:00出发 · 10月31日的预报"},{id:"departures",number:"04",kicker:"比较出发时间",title:"选对解缆的日子。",text:"规划器会为同一段航程计算最多十二个出发时间，每个间隔六小时，并把抵达时间、航行时长、最强风和机航时间并排列出。周三上午从莱罗斯岛出发，午夜抵达罗得岛；周三傍晚出发，则次日上午抵达。星标表示机航和迎风时间最少的出发时间。",points:["最多十二个出发时间，每六小时一个","点按一行即可查看其航线","保存航程或与船员分享，始终基于最新预报"],image:"departures",alt:"从莱罗斯岛到罗得岛的出发时间表，自周三08:00起每六小时一个：抵达时间、航行时长、最强风和机航时长，最佳出发时间周四14:00标有星标。",coords:"",caption:"莱罗斯岛 → 罗得岛，自周三08:00起的出发时间",card:!0},{id:"stays",number:"05",kicker:"船舶停留候选地",title:"其他船停在哪里。",text:"夏天船员们把船留在哪里两个月？冬天又在哪里度过？船舶停留候选地显示船只真正停留在哪里、停留多久：来自数千次真实船只移动的集体智慧。从几天到六个月以上，按季节呈现港口和锚地。",points:["按停留时长筛选","查看船只在哪些月份停留在此","发现热门的过冬港口"],image:"stay-detail",alt:"普雷韦扎：典型停留时长，以及船只停留在此的月份。",coords:"38°57′N · 020°45′E",caption:"普雷韦扎，停留时长与季节"},{id:"hotspots",number:"06",kicker:"热点",title:"找一处更安静的锚地。",text:"八月里哪里船多拥挤，哪里还有空位？热点按月显示每片航行海域的繁忙程度。爱奥尼亚海和萨罗尼科斯湾一片亮色，而距雅典一天航程的安德罗斯岛依然清静。",points:["从清静到拥挤","一年中的每个月","任意地点最繁忙和最清静的月份"],image:"hotspots",alt:"希腊航行海域八月的繁忙程度：爱奥尼亚群岛周边和萨罗尼科斯湾十分拥挤，安德罗斯岛附近清静，地点查看器已打开。",coords:"38°24′N · 023°36′E",caption:"热点，希腊，八月"},{id:"spot",number:"07",kicker:"地点概况",title:"一个地点的一切，尽在一张卡片。",text:"在地图上长按任意地点，或用鼠标右键单击，地点概况就会汇总你所选月份的一切：风与海况、雷暴、地形对此处的遮挡程度，以及附近的船舶停留和航线。九月的帕克索斯岛盖奥斯：大部分时间静风或轻风，海面平静至小浪，大约每六天中有一天出现雷暴。月份条显示，十一月是雷暴最多的月份。",points:["一个地点、一个月份的风、海况和雷暴","5 海里范围内的船舶停留和航线","每个月份的评级一目了然，可作为链接分享给你的船员"],image:"spot",alt:"九月帕克索斯岛盖奥斯的地点概况：风与海况、雷暴、地形遮挡、附近的船舶停留和航线，以及一目了然的每月评级。",coords:"",caption:"盖奥斯，帕克索斯岛，九月",card:!0},{id:"wind",number:"08",kicker:"风",title:"北风会有多少？",text:"选择风向和月份：七月，爱琴海中部变成深蓝色。这就是梅尔特米风。点按米科诺斯岛附近的一个点，你会看到七月里有 60% 甚至更多的时间风从北方吹来。",points:["每个月的风力和风向","按时段查看风况","点按任意地点查看数据"],image:"wind",alt:"七月爱琴海北风出现的频率，米科诺斯岛附近的地点详情已打开。",coords:"37°36′N · 025°00′E",caption:"北风，爱琴海，七月"},{id:"waves",number:"09",kicker:"海浪",title:"出航之前，先知海况。",text:"每个月有多少天浪高达到 2.5 米或以上？一月里，密史脱拉风在利翁湾上的影响范围清晰可见。",points:["从平静到巨浪","涌浪与短而陡的浪","一年中的每个月"],image:"waves",alt:"一月地中海西部的大浪天数。",coords:"41°00′N · 005°00′E",caption:"大浪天数，地中海西部，一月"},{id:"risk",number:"10",kicker:"雷暴风险",title:"哪个港口的雷暴更少？",text:"雷暴风险综合了雷暴发生的频率、强度，以及山地、岬角和开阔海面对雷暴的影响，按月呈现，细到每一个海湾。先点按一个地点，再点按另一个，就能看到第二个地点的风险高出或低出多少。普雷韦扎和迈索隆吉都是热门的过冬地：十一月，迈索隆吉的雷暴风险低 27%。",points:["雷暴日、闪电密度和地形，合成一个数值","差异细到每一个海湾","点按两个地点进行比较"],image:"risk",alt:"十一月爱奥尼亚海的雷暴风险：先点按普雷韦扎，再点按迈索隆吉，地点信息显示风险低 27%。",coords:"38°40′N · 021°10′E",caption:"普雷韦扎对比迈索隆吉，十一月",markers:[{x:34.09,y:27.12,text:"普雷韦扎，首先点按：十一月风险值为 50。",color:"#7b2a83"},{x:58.05,y:72.78,text:"迈索隆吉，相距 47 海里：雷暴风险低 27%。",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"雷电数据",title:"多频繁，多猛烈，多可能。",text:"风险背后是三个可以单独打开的图层，每个月都使用相同的色标。九月的地中海说明了为什么三者缺一不可：雷暴在亚得里亚海和爱奥尼亚海沿岸最为频繁，闪电在意大利与希腊之间的海面上最为密集，而有利于雷暴形成的条件一直延伸到遥远的南方。",points:["雷暴日：雷暴发生的频率，2013–2025 年","闪电密度：雷暴的猛烈程度","雷暴潜势：雷暴可能形成的地方，1994–2023 年"],image:"days",alt:"九月地中海的雷暴日。",coords:"40°00′N · 015°00′E",caption:"雷暴日，地中海，九月",panels:[{label:"雷暴日",image:"days",alt:"九月地中海的雷暴日。",caption:"雷暴日，地中海，九月"},{label:"闪电密度",image:"density",alt:"九月地中海的闪电密度。",caption:"闪电密度，地中海，九月"},{label:"雷暴潜势",image:"potential",alt:"九月地中海的雷暴潜势。",caption:"雷暴潜势，地中海，九月"}]},{id:"terrain",number:"12",kicker:"地形暴露度",title:"同一个海湾，屏蔽各不相同。",text:"雷暴风险告诉你选哪个海湾，地形暴露度告诉你选海湾的哪一侧：周围的山丘可以帮锚地挡住雷电，这个图层显示地形对海湾每个位置的保护程度，让你在下锚前选好更有利的位置。",points:["比较同一海湾内的不同位置","精细的 30 米高程数据"],image:"terrain",alt:"克罗地亚维斯岛科米扎湾的地形暴露度。",coords:"43°02′N · 016°05′E",caption:"维斯岛科米扎湾",markers:[{x:56.9,y:57.69,text:"周围地形的屏蔽作用较弱。",color:"#762a83"},{x:53.84,y:26.35,text:"周围地形有一定的屏蔽作用。",color:"#ecd27a"},{x:35.86,y:27.83,text:"周围地形的屏蔽作用较强。",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"海底",title:"沙底还是海草？",text:"下锚之前：“海底”图层显示沿岸的沙、泥、岩石、海草和珊瑚，从地中海到热带海域。在帕尔马湾，一条宽阔的海草带沿岸延伸，沙底则在更外侧。越来越多的地方禁止在波西多尼亚海草上锚泊，所以最好在抵达前就了解清楚。",points:["沙、泥、岩石、海草和珊瑚","欧洲和热带浅海沿岸","向所有人开放"],image:"seabed",alt:"马略卡岛帕尔马湾的海底：沿岸是一条宽阔的海草带，外侧是沙底，点位检查器显示为海草。",coords:"39°30′N · 002°37′E",caption:"海底，帕尔马湾"}],story:{kicker:"我们的故事",title:"源于一次惊险时刻。",text:"2024 年 10 月，我们一家在爱奥尼亚海航行时，一道闪电就落在我们的船旁边。那一刻，一个简单的问题摆在眼前：我们待在这里更安全，还是去海湾另一侧更安全？IncusGrid 由此起步，并逐渐成长为一张地图，装下了那个航海季之前我们希望早已知道的一切。",more:"阅读完整故事（英文）",link:`${e}/blog/introducing-incusgrid/`,place:"希腊，伊古迈尼察",note:"想法诞生的地方"},fromBlog:{kicker:"博客",title:"来自海上的数据故事。",all:"全部文章",note:"文章为英文。"},devices:{kicker:"Web & Android",title:"甲板上，或海图桌前。",text:"在任意浏览器中使用 IncusGrid，或安装 Android 应用。搜索你的航行区域，在手机、平板或笔记本电脑上探索。",points:["浏览器中无需安装","Google Play 上的 Android 应用","支持 19 种语言"],web:"在浏览器中打开",android:"在 Google Play 获取",phoneAlt:"IncusGrid Android 应用显示爱奥尼亚群岛周边的船舶停留候选地。"},final:{title:"规划你的下一个航海季，以及下一段航程。",text:"来自多年真实数据的路线、船舶停留候选地、风、浪和雷电，再加上10天预报和航程规划器——尽在一张地图。",cta:"打开地图"},disclaimerLabel:"注意",disclaimer:"IncusGrid 为规划而打造，不是导航工具。路线为示意绘制，船舶停留候选地由船只位置报告中的中断推断而来，并非确认的泊位。航程规划器使用简化的极曲线，不考虑洋流以及海浪对船速的影响，也不会把航线规划进港内。出海前请务必查看最新预报、官方海图和当地情况。",footer:{blog:"博客",legal:"法律声明",privacy:"隐私政策",terms:"服务条款",cookies:"Cookie 设置",support:"支持",madeWith:"在葡萄牙用",made:"打造",englishOnly:"法律页面仅提供英文版。"}},z={path:"/hi",htmlLang:"hi",ogLocale:"hi_IN",meta:{title:"IncusGrid · नाविकों के लिए स्थानीय जानकारी और वेदर रूटिंग",description:"असली यात्राओं से बने नौकायन मार्ग और नावों के ठहराव, वर्षों का हवा, लहरों और बिजली का डेटा, साथ में 10 दिन का पूर्वानुमान और आपकी नाव के लिए वेदर रूटिंग। अपने सीज़न और अपनी अगली यात्रा की योजना एक ही मानचित्र पर बनाएँ।",keywords:"वेदर रूटिंग, weather routing, यात्रा योजना, मार्ग योजना, रवानगी योजना, नौकायन पूर्वानुमान, हवा का पूर्वानुमान, नाव पोलर, नौकायन मार्ग, सेलिंग रूट, नौकायन योजना, यॉट, सेलबोट, लंगरगाह, मरीना, हवा के आँकड़े, समुद्र की स्थिति, लहरें, बिजली, तड़ित-झंझा, आंधी-तूफ़ान, आंधी-तूफ़ान जोखिम, बिजली घनत्व, नौकायन, sailing routes, yacht cruising, समुद्र तल, समुद्री घास, पोसिडोनिया, लंगर का तल"},nav:{routes:"मार्ग",passages:"यात्रा योजना",stays:"ठहराव",weather:"मौसम",thunderstorms:"बिजली",blog:"ब्लॉग",openApp:"मानचित्र खोलें"},hero:{position:"Sailing intelligence",lead:"IncusGrid वर्षों के डेटा को वह स्थानीय जानकारी बनाता है जिसकी हर क्रू को रवाना होने से पहले ज़रूरत होती है: असली नाव गतिविधियाँ, हवा, लहरें और बिजली — सब एक मानचित्र पर। साथ में अगले 10 दिनों का पूर्वानुमान और एक यात्रा प्लानर, जो पूर्वानुमानित हवा में घंटे-दर-घंटे आपकी नाव का मार्ग तय करता है और रास्ते भर के झोंके और लहरें दिखाता है।",ctaApp:"मानचित्र खोलें",ctaAndroid:"Android ऐप",heroAlt:"कैरिबियन सागर में नौकायन मार्ग, हिस्पानियोला से लेसर एंटिलीज़ और दक्षिण अमेरिका के तट तक, क्रूज़िंग नावों की असली यात्राओं से बने।",heroCaption:"नौकायन मार्ग, कैरिबियन सागर · सभी महीने",notes:[{label:"नावें",value:"हज़ारों"},{label:"गतिविधियाँ",value:"लाखों"},{label:"बिजली गिरने की घटनाएँ",value:"अरबों"},{label:"पूर्वानुमान",value:"10 दिन"},{label:"कवरेज",value:"दुनिया भर में"}]},contrast:{kicker:"सीज़न और पूर्वानुमान",title:"सीज़न बताता है कौन-सा महीना। पूर्वानुमान बताता है कौन-सा दिन।",text:"जून में क्रू कौन-सा मार्ग चुनते हैं? नावें सर्दियाँ कहाँ बिताती हैं? मेल्टेमी किस महीने आती है, और सर्दियाँ बिताने वाले किस बंदरगाह पर नवंबर में कम आंधी-तूफ़ान आते हैं? ऐसे जवाब तभी दिखते हैं जब आप कई वर्षों को एक साथ देखते हैं। जैसे-जैसे रवानगी नज़दीक आती है, यात्रा प्लानर 10 दिन के पूर्वानुमान पर हिसाब लगाता है कि कब निकलें और कब पहुँचेंगे।"},chapters:[{id:"routes",number:"01",kicker:"नौकायन मार्ग",title:"हज़ारों क्रू के अनुभव से पारगमन की योजना बनाएँ।",text:"हज़ारों असली यात्राएँ दिखाती हैं कि पारगमन कब समझदारी है, किस दिशा में, और क्रू कहाँ से निकलते हैं और कहाँ पहुँचते हैं। प्रचलित हवाएँ, मौसम की अनुकूल खिड़की का इंतज़ार करने की अच्छी जगहें और समुद्र में एक रात के बाद सुरक्षित तट-आगमन — सब पहले से इसमें शामिल हैं। उदाहरण के लिए, सिसिली से आयोनियन द्वीपों तक ज़्यादातर नावें मई और जून में पूर्व की ओर जाती हैं और सितंबर में लौटती हैं।",points:["हर महीने और दिशा के अनुसार लोकप्रियता","मौजूदा मानचित्र दृश्य के सबसे लोकप्रिय मार्ग","अपनी क्रू के साथ मार्ग साझा करें"],image:"route-detail",alt:"सिसिली से आयोनियन द्वीपों तक का चुना हुआ मार्ग, हर महीने और दिशा में उसकी लोकप्रियता के साथ।",coords:"38°12′N · 017°30′E",caption:"सिसिली → आयोनियन द्वीप, महीने और दिशा के अनुसार"},{id:"route-wind",number:"02",kicker:"मार्ग पर हवा",title:"रवाना होने से पहले हवा को जानें।",text:"हर मार्ग महीने-दर-महीने दिखाता है कि उस पर कैसी हवा की उम्मीद करें: वह कहाँ से आती है, कितनी तेज़ बहती है, यात्रा का कितना हिस्सा आप हवा के विरुद्ध, आड़ी हवा में या हवा के साथ तय करते हैं, और समुद्र कितनी बार शांत रहता है। मई में सिसिली से आयोनियन द्वीपों तक: उत्तर-पश्चिम से हवा, ब्यूफ़ोर्ट 3, आधे से ज़्यादा रास्ता हवा के साथ।",points:["हर महीने की प्रचलित हवा और ब्यूफ़ोर्ट बल","मार्ग के कोर्स पर हवा के विरुद्ध, आड़ी हवा या हवा के साथ","मार्ग पर समुद्र की स्थिति"],image:"route-wind",alt:"सिसिली से आयोनियन द्वीपों तक का मार्ग कार्ड: हर महीने की प्रचलित हवा, ब्यूफ़ोर्ट बल, हवा की तीव्रता, कोर्स और समुद्र की स्थिति, मई चुना हुआ।",coords:"",caption:"सिसिली → आयोनियन द्वीप, मई में हवा",card:!0},{id:"passage",number:"03",kicker:"यात्रा प्लानर · वेदर रूटिंग",title:"रवाना होने से पहले जानें कि कब पहुँचेंगे।",text:"शुरुआत और मंज़िल तय करें, अपनी नाव चुनें, और यात्रा प्लानर अगले 10 दिनों की पूर्वानुमानित हवा में घंटे-दर-घंटे एक तेज़ मार्ग ढूँढ़ता है, साथ में रास्ते भर के झोंके और लहरें। लेरोस से रोड्स तक, 86 समुद्री मील, बुधवार 20:00 बजे रवानगी: हवा के साथ एक रात, 15 नॉट से ज़्यादा हवा नहीं, इंजन चलाने की ज़रूरत नहीं, और गुरुवार को ग्यारह बजे से ठीक पहले पहुँच।",points:["पहुँचने का समय, सबसे तेज़ हवा, झोंके और लहरें, पाल और इंजन से चलने के घंटे","आपकी नाव के लिए: प्रकार और आकार, या आपका अपना पोलर","रास्ते में योजना के साथ आपकी स्थिति, और बाकी मार्ग की नए सिरे से गणना"],image:"passage",alt:"हवा के पूर्वानुमान पर लेरोस से रोड्स तक के मार्ग के साथ यात्रा प्लानर: समय के साथ वेपॉइंट, रात में कोस के दक्षिण में नाव, और बगल में पहुँचने का समय, सबसे तेज़ हवा, और पाल व इंजन से चलने के घंटे।",coords:"36°48′N · 027°50′E",caption:"लेरोस → रोड्स, बुधवार 20:00 बजे रवानगी · 31 अक्टूबर का पूर्वानुमान"},{id:"departures",number:"04",kicker:"रवानगी की तुलना करें",title:"रवाना होने का सही दिन।",text:"प्लानर एक ही यात्रा को छह-छह घंटे के अंतर पर अधिकतम बारह रवानगियों के लिए गिनता है, और पहुँचने का समय, अवधि, सबसे तेज़ हवा और इंजन पर बिताया समय साथ-साथ रखता है। बुधवार सुबह लेरोस से निकलें तो आधी रात को रोड्स पहुँचते हैं; बुधवार शाम निकलें तो अगली सुबह। तारा उस रवानगी को दिखाता है जिसमें इंजन पर और हवा के विरुद्ध सबसे कम समय लगता है।",points:["अधिकतम बारह रवानगियाँ, हर छह घंटे पर","किसी पंक्ति पर टैप करके उसका मार्ग देखें","यात्रा सहेजें या अपने क्रू के साथ साझा करें, हमेशा ताज़ा पूर्वानुमान पर"],image:"departures",alt:"लेरोस से रोड्स तक की रवानगी तालिका, बुधवार 08:00 बजे से हर छह घंटे पर: पहुँचने का समय, अवधि, सबसे तेज़ हवा और इंजन पर घंटे, और सबसे अच्छी रवानगी, गुरुवार 14:00 बजे, पर तारा।",coords:"",caption:"लेरोस → रोड्स, बुधवार 08:00 बजे से रवानगियाँ",card:!0},{id:"stays",number:"05",kicker:"नावों के ठहराव",title:"दूसरी नावें कहाँ ठहरती हैं।",text:"गर्मियों में क्रू अपनी नाव दो महीने के लिए कहाँ छोड़ते हैं, और सर्दियाँ कहाँ बिताते हैं? नावों के ठहराव वे बंदरगाह और लंगरगाह दिखाते हैं जहाँ नावें रुकीं — कुछ दिनों से लेकर छह महीने से ज़्यादा तक, सीज़न के अनुसार।",points:["ठहराव की अवधि से फ़िल्टर करें","देखें कि किन महीनों में नावें किसी जगह ठहरती हैं","सर्दियाँ बिताने के लोकप्रिय बंदरगाह खोजें"],image:"stay-detail",alt:"प्रेवेज़ा: ठहराव की आम अवधि और वे महीने जिनमें नावें वहाँ ठहरती हैं।",coords:"38°57′N · 020°45′E",caption:"प्रेवेज़ा, ठहराव की अवधि और सीज़न"},{id:"hotspots",number:"06",kicker:"हॉटस्पॉट",title:"ज़्यादा शांत लंगरगाह खोजें।",text:"अगस्त में नावें कहाँ भीड़ लगाती हैं, और कहाँ अब भी जगह है? हॉटस्पॉट हर महीने दिखाता है कि हर नौकायन क्षेत्र कितना व्यस्त है। आयोनियन सागर और सारोनिक खाड़ी चमकते हैं, जबकि एथेंस से एक दिन की नौकायन दूरी पर एंड्रोस शांत रहता है।",points:["शांत से भीड़भाड़ तक","साल का हर महीना","किसी भी बिंदु पर सबसे व्यस्त और सबसे शांत महीने"],image:"hotspots",alt:"अगस्त में यूनानी नौकायन क्षेत्र कितने व्यस्त हैं: आयोनियन द्वीपों के आसपास और सारोनिक खाड़ी में भीड़, एंड्रोस के पास शांति, पॉइंट इंस्पेक्टर खुला हुआ।",coords:"38°24′N · 023°36′E",caption:"हॉटस्पॉट, यूनान, अगस्त"},{id:"spot",number:"07",kicker:"जगह का विवरण",title:"एक जगह के बारे में सब कुछ, एक कार्ड में।",text:"मानचित्र पर किसी भी जगह को दबाकर रखें या उस पर राइट-क्लिक करें, और जगह का विवरण आपके चुने महीने के लिए सब कुछ एक साथ दिखाता है: हवा और समुद्र की स्थिति, आंधी-तूफ़ान, भूभाग उस जगह को कितना बचाता है, और पास के नावों के ठहराव और मार्ग। सितंबर में पैक्सोस का गायोस: ज़्यादातर समय शांत या हल्की हवा, शांत से हल्का समुद्र, और लगभग हर छठे दिन आंधी-तूफ़ान। महीनों की पट्टी दिखाती है कि नवंबर में सबसे ज़्यादा आंधी-तूफ़ान आते हैं।",points:["एक जगह और एक महीने के लिए हवा, समुद्र की स्थिति और आंधी-तूफ़ान","5 समुद्री मील के भीतर नावों के ठहराव और मार्ग","हर महीने का आकलन एक नज़र में, आपकी क्रू के लिए लिंक के रूप में"],image:"spot",alt:"सितंबर में पैक्सोस के गायोस का जगह का विवरण: हवा और समुद्र की स्थिति, आंधी-तूफ़ान, भूभाग से सुरक्षा, पास के नावों के ठहराव और मार्ग, और हर महीने का आकलन एक नज़र में।",coords:"",caption:"गायोस, पैक्सोस, सितंबर",card:!0},{id:"wind",number:"08",kicker:"हवा",title:"उत्तरी हवा कितनी मिलेगी?",text:"दिशा और महीना चुनें: जुलाई में मध्य एजियन सागर गहरा नीला हो जाता है। यही मेल्टेमी है। मायकोनोस के पास किसी बिंदु पर टैप करें, और आप देखेंगे कि जुलाई के 60% या उससे अधिक घंटों में हवा उत्तर से चलती है।",points:["हर महीने की ताकत और दिशा","दिन के समय के अनुसार हवा","किसी भी बिंदु के आँकड़े देखने के लिए टैप करें"],image:"wind",alt:"जुलाई में एजियन सागर में हवा कितनी बार उत्तर से चलती है, मायकोनोस के पास बिंदु-निरीक्षक खुला हुआ।",coords:"37°36′N · 025°00′E",caption:"उत्तर से हवा, एजियन सागर, जुलाई"},{id:"waves",number:"09",kicker:"लहरें",title:"निकलने से पहले समुद्र की स्थिति जानें।",text:"महीने में कितने दिन 2.5 m या उससे ऊँची लहरें आती हैं? जनवरी में लायन की खाड़ी के पार मिस्ट्रल की पहुँच साफ़ दिखती है।",points:["शांत से लेकर बहुत उग्र समुद्र तक","स्वेल और छोटी, खड़ी लहरें","साल का हर महीना"],image:"waves",alt:"जनवरी में पश्चिमी भूमध्य सागर में उग्र समुद्र वाले दिन।",coords:"41°00′N · 005°00′E",caption:"उग्र दिन, पश्चिमी भूमध्य सागर, जनवरी"},{id:"risk",number:"10",kicker:"आंधी-तूफ़ान जोखिम",title:"किस बंदरगाह पर कम आंधी-तूफ़ान आते हैं?",text:"आंधी-तूफ़ान जोखिम एक साथ दिखाता है कि तूफ़ान कितनी बार आते हैं, कितने प्रचंड होते हैं और पहाड़, अंतरीप और खुला समुद्र उन्हें कैसे प्रभावित करते हैं — हर महीने के लिए, अलग-अलग खाड़ियों के स्तर तक। एक जगह पर टैप करें, फिर दूसरी पर, और देखें कि दूसरी जगह पर जोखिम कितना ज़्यादा या कम है। प्रेवेज़ा और मेसोलोंगी दोनों सर्दियाँ बिताने के लिए लोकप्रिय हैं: नवंबर में मेसोलोंगी में आंधी-तूफ़ान जोखिम 27% कम है।",points:["तड़ित-झंझा वाले दिन, बिजली घनत्व और भूभाग, एक ही मान में","अलग-अलग खाड़ियों के स्तर तक अंतर","तुलना के लिए दो जगहों पर टैप करें"],image:"risk",alt:"नवंबर में आयोनियन सागर में आंधी-तूफ़ान जोखिम: पहले प्रेवेज़ा पर टैप, फिर मेसोलोंगी पर, और पॉइंट इंस्पेक्टर 27% कम जोखिम दिखा रहा है।",coords:"38°40′N · 021°10′E",caption:"प्रेवेज़ा बनाम मेसोलोंगी, नवंबर",markers:[{x:34.09,y:27.12,text:"प्रेवेज़ा, पहले टैप किया गया: नवंबर में जोखिम मान 50।",color:"#7b2a83"},{x:58.05,y:72.78,text:"मेसोलोंगी, 47 समुद्री मील दूर: 27% कम आंधी-तूफ़ान जोखिम।",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"बिजली के आँकड़े",title:"कितनी बार, कितने प्रचंड, कितनी संभावना।",text:"जोखिम के पीछे तीन लेयर हैं जिन्हें आप अलग-अलग भी खोल सकते हैं, हर महीने एक ही पैमाने पर। सितंबर में भूमध्य सागर दिखाता है कि तीनों क्यों ज़रूरी हैं: तड़ित-झंझा एड्रियाटिक और आयोनियन तटों पर सबसे ज़्यादा आते हैं, बिजली इटली और यूनान के बीच समुद्र के ऊपर सबसे घनी होती है, और तूफ़ान के अनुकूल परिस्थितियाँ दूर दक्षिण तक फैली होती हैं।",points:["तड़ित-झंझा वाले दिन: तूफ़ान कितनी बार आते हैं, 2013–2025","बिजली घनत्व: वे कितने प्रचंड होते हैं","तड़ित-झंझा की संभावना: वे कहाँ बन सकते हैं, 1994–2023"],image:"days",alt:"सितंबर में भूमध्य सागर में तड़ित-झंझा वाले दिन।",coords:"40°00′N · 015°00′E",caption:"तड़ित-झंझा वाले दिन, भूमध्य सागर, सितंबर",panels:[{label:"तड़ित-झंझा वाले दिन",image:"days",alt:"सितंबर में भूमध्य सागर में तड़ित-झंझा वाले दिन।",caption:"तड़ित-झंझा वाले दिन, भूमध्य सागर, सितंबर"},{label:"बिजली घनत्व",image:"density",alt:"सितंबर में भूमध्य सागर में बिजली घनत्व।",caption:"बिजली घनत्व, भूमध्य सागर, सितंबर"},{label:"तड़ित-झंझा की संभावना",image:"potential",alt:"सितंबर में भूमध्य सागर में तड़ित-झंझा की संभावना।",caption:"तड़ित-झंझा की संभावना, भूमध्य सागर, सितंबर"}]},{id:"terrain",number:"12",kicker:"भूभाग जोखिम",title:"एक ही खाड़ी, अलग-अलग आड़।",text:"आंधी-तूफ़ान जोखिम बताता है कि कौन-सी खाड़ी चुनें। भूभाग जोखिम बताता है कि उसका कौन-सा किनारा: आसपास की पहाड़ियाँ किसी लंगरगाह को बिजली से आड़ दे सकती हैं, और यह लेयर दिखाती है कि भूभाग खाड़ी के हर हिस्से को कितनी अच्छी तरह बचाता है, ताकि लंगर डालने से पहले आप बेहतर जगह चुन सकें।",points:["एक ही खाड़ी के भीतर जगहों की तुलना करें","30 m का विस्तृत ऊँचाई डेटा"],image:"terrain",alt:"क्रोएशिया के विस द्वीप पर कोमिज़ा खाड़ी में भूभाग जोखिम।",coords:"43°02′N · 016°05′E",caption:"कोमिज़ा खाड़ी, विस",markers:[{x:56.9,y:57.69,text:"आसपास के भूभाग से कम आड़।",color:"#762a83"},{x:53.84,y:26.35,text:"आसपास के भूभाग से कुछ आड़।",color:"#ecd27a"},{x:35.86,y:27.83,text:"आसपास के भूभाग से अधिक आड़।",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"समुद्र तल",title:"रेत या समुद्री घास?",text:"लंगर डालने से पहले: समुद्र तल परत तट के साथ रेत, कीचड़, चट्टान, समुद्री घास और मूंगा दिखाती है, भूमध्य सागर से उष्णकटिबंधीय क्षेत्रों तक। पाल्मा की खाड़ी में तट के साथ समुद्री घास की एक चौड़ी पट्टी फैली है और रेत आगे की ओर है। पोसिडोनिया पर लंगर डालना अधिक से अधिक जगहों पर प्रतिबंधित है, इसलिए पहुँचने से पहले जानना फायदेमंद है।",points:["रेत, कीचड़, चट्टान, समुद्री घास और मूंगा","यूरोप और उथले उष्णकटिबंधीय तट","सभी के लिए खुला"],image:"seabed",alt:"मायोर्का में पाल्मा की खाड़ी का समुद्र तल: तट के साथ समुद्री घास की चौड़ी पट्टी, आगे रेत, पॉइंट इंस्पेक्टर समुद्री घास दिखा रहा है।",coords:"39°30′N · 002°37′E",caption:"समुद्र तल, पाल्मा की खाड़ी"}],story:{kicker:"हमारी कहानी",title:"बाल-बाल बचने से जन्मा।",text:"अक्टूबर 2024 में हमारा परिवार आयोनियन सागर में नौकायन कर रहा था, जब हमारी नाव के ठीक बगल में बिजली गिरी। उस पल ने एक सीधा-सा सवाल खड़ा किया: क्या हम यहाँ ज़्यादा सुरक्षित हैं, या खाड़ी के दूसरी ओर? IncusGrid उसी सवाल के जवाब के रूप में शुरू हुआ — और बढ़कर एक ऐसा मानचित्र बन गया जिसमें वह सब है जो काश हमें उस सीज़न से पहले पता होता।",more:"पूरी कहानी पढ़ें (अंग्रेज़ी में)",link:`${e}/blog/introducing-incusgrid/`,place:"इगूमेनित्सा, ग्रीस",note:"जहाँ यह विचार जन्मा"},fromBlog:{kicker:"ब्लॉग से",title:"पानी से जुड़ी डेटा कहानियाँ।",all:"सभी लेख",note:"लेख अंग्रेज़ी में हैं।"},devices:{kicker:"वेब और Android",title:"डेक पर हों या चार्ट टेबल पर।",text:"IncusGrid को किसी भी ब्राउज़र में इस्तेमाल करें या Android ऐप इंस्टॉल करें। अपना नौकायन क्षेत्र खोजें और फ़ोन, टैबलेट या लैपटॉप पर उसे जानें-परखें।",points:["ब्राउज़र में इंस्टॉल करने की ज़रूरत नहीं","Google Play पर Android ऐप","19 भाषाओं में उपलब्ध"],web:"ब्राउज़र में खोलें",android:"Google Play पर पाएँ",phoneAlt:"IncusGrid का Android ऐप, आयोनियन द्वीपों के आसपास नावों के ठहराव दिखाते हुए।"},final:{title:"अपने अगले सीज़न की योजना बनाएँ। और अपनी अगली यात्रा की भी।",text:"कई वर्षों के असली डेटा से मार्ग, नावों के ठहराव, हवा, लहरें और बिजली, साथ में 10 दिन का पूर्वानुमान और यात्रा प्लानर — सब एक मानचित्र पर।",cta:"मानचित्र खोलें"},disclaimerLabel:"सावधानी",disclaimer:"IncusGrid योजना बनाने के लिए है और यह नौवहन सहायक नहीं है। मार्ग सांकेतिक रूप से बनाए गए हैं, और नावों के ठहराव नावों की रिपोर्टों में आए अंतरालों से निकाले जाते हैं, पुष्ट बर्थ से नहीं। यात्रा प्लानर एक सरल पोलर का उपयोग करता है, धाराओं या नाव की गति पर लहरों के असर को नहीं गिनता, और बंदरगाह के भीतर तक मार्ग नहीं बनाता। समुद्र में जाने से पहले हमेशा ताज़ा पूर्वानुमान, आधिकारिक समुद्री चार्ट और स्थानीय परिस्थितियाँ जाँचें।",footer:{blog:"ब्लॉग",legal:"कानूनी सूचना",privacy:"गोपनीयता नीति",terms:"सेवा की शर्तें",cookies:"कुकी सेटिंग्स",support:"सहायता",madeWith:"पुर्तगाल में",made:"से बनाया गया",englishOnly:"कानूनी पेज अंग्रेज़ी में हैं।"}},w={path:"/ja",htmlLang:"ja",ogLocale:"ja_JP",meta:{title:"IncusGrid · セーラーのための現地の知識とウェザールーティング",description:"実際の航海から導いた航行ルートと船の滞在候補、長年の風・波・雷のデータに加えて、10日間予報とあなたの艇のためのウェザールーティング。シーズンも次の航海も、ひとつの地図で計画できます。",keywords:"ウェザールーティング, 航海計画, 航路計画, 出航計画, 出航タイミング, セーリング 天気予報, 風予報, ポーラーダイアグラム, セーリング, ヨット, クルージング, 航行ルート, 外洋航海, 錨泊地, マリーナ, 越冬, 上架, 風統計, 海況, 波, うねり, 雷, 雷雨, 雷雨リスク, 落雷密度, ヨット 地中海, ロングクルーズ, 海底, 海草, ポシドニア, 底質"},nav:{routes:"ルート",passages:"航海計画",stays:"船の滞在候補",weather:"気象",thunderstorms:"雷",blog:"ブログ",openApp:"地図を開く"},hero:{position:"Sailing intelligence",lead:"IncusGrid は長年のデータを、出航前にどのクルーにも欠かせない現地の知識に変えます。実際の船の動き、風、波、雷をひとつの地図に。さらに10日先までの予報と、予報の風の中を1時間ごとに艇のルートを導き出す航海プランナー。途中のガストと波もあわせて表示します。",ctaApp:"地図を開く",ctaAndroid:"Android アプリ",heroAlt:"イスパニョーラ島から小アンティル諸島、南米沿岸へと続くカリブ海の航行ルート。クルージング艇の実際の航海から描かれています。",heroCaption:"航行ルート、カリブ海 · 全月",notes:[{label:"船",value:"数千隻"},{label:"移動",value:"数百万件"},{label:"落雷",value:"数十億回"},{label:"予報",value:"10日間"},{label:"対象範囲",value:"全世界"}]},contrast:{kicker:"シーズンと予報",title:"何月に行くかはシーズンが、何日に出るかは予報が教えてくれる。",text:"6月、クルーはどの航路をとるのか。船はどこで冬を越すのか。メルテミが吹くのは何月か。11月に雷雨が少ないのはどちらの越冬港か。何年分ものデータを重ねて初めて見えてくる答えです。出航が近づいたら、航海プランナーが10日間予報をもとに、いつ出ていつ着くかを計算します。"},chapters:[{id:"routes",number:"01",kicker:"航行ルート",title:"数千のクルーの経験で横断を計画。",text:"数千の実際の航海から、いつ横断するのが理にかなうか、どの方向か、クルーがどこを出てどこに着くかがわかります。卓越風、ウェザーウィンドウを待つのに適した場所、夜間航海のあとの安全なランドフォールも、すでにそこに織り込まれています。たとえばシチリア島からイオニア諸島へは、多くの船が5月と6月に東へ向かい、9月に戻ってきます。",points:["月別・方向別の人気度","表示中の地図範囲で人気のルート","ルートをクルーと共有"],image:"route-detail",alt:"シチリア島からイオニア諸島へのルートを選択し、月別・方向別の人気度を表示した画面。",coords:"38°12′N · 017°30′E",caption:"シチリア島 → イオニア諸島、月別・方向別"},{id:"route-wind",number:"02",kicker:"ルート上の風",title:"出航前に風を知る。",text:"どのルートでも、予想される風が月ごとにわかります。どこから吹くか、どれくらい強いか、航程のうち風上・横風・追い風で走る割合、そして海が穏やかな頻度まで。たとえば5月のシチリア島からイオニア諸島へは、北西の風、ビューフォート風力3、航程の半分以上が追い風です。",points:["毎月の卓越風とビューフォート風力","ルートの針路に対する風上・横風・追い風","ルート沿いの海況"],image:"route-wind",alt:"シチリア島からイオニア諸島へのルートカード：毎月の卓越風、ビューフォート風力、風の強さ、コース、海況。5月を選択中。",coords:"",caption:"シチリア島 → イオニア諸島、5月の風",card:!0},{id:"passage",number:"03",kicker:"航海プランナー · ウェザールーティング",title:"舫いを解く前に、到着時刻を知る。",text:"出発地と目的地を決めて艇を選べば、航海プランナーが今後10日間の予報の風の中を1時間ごとにたどり、速いルートを見つけます。途中のガストと波も表示します。レロス島からロドス島まで86海里、水曜20:00に出航すれば、追い風で一晩、風は最大15ノット、機走なしで、木曜の11時少し前に到着します。",points:["到着時刻、最大風速、ガストと波、帆走と機走の時間","あなたの艇に合わせて：艇種とサイズ、または独自のポーラー","航行中は計画と並べて現在位置を表示し、残りのルートを再計算"],image:"passage",alt:"風予報の上にレロス島からロドス島へのルートを表示した航海プランナー：時刻付きのウェイポイント、夜にコス島の南を走る艇、その横に到着時刻、最大風速、帆走と機走の時間。",coords:"36°48′N · 027°50′E",caption:"レロス島 → ロドス島、水曜20:00出航 · 10月31日の予報"},{id:"departures",number:"04",kicker:"出航時刻を比較",title:"出航にいちばんいい日を選ぶ。",text:"プランナーは同じ航海を6時間おきに最大12通りの出航時刻で計算し、到着時刻、所要時間、最大風速、機走時間を並べて比べます。水曜の朝にレロス島を出ればロドス島には深夜0時に、水曜の夕方に出れば翌朝に着きます。星印は、機走と風上航の時間がいちばん短い出航時刻です。",points:["最大12通りの出航時刻、6時間ごと","行をタップするとそのルートを表示","航海を保存してクルーと共有、常に最新の予報で"],image:"departures",alt:"レロス島からロドス島への出航時刻の表。水曜08:00から6時間ごとに、到着時刻、所要時間、最大風速、機走時間を表示し、最適な出航時刻である木曜14:00に星印。",coords:"",caption:"レロス島 → ロドス島、水曜08:00からの出航時刻",card:!0},{id:"stays",number:"05",kicker:"船の滞在候補",title:"ほかの船はどこに泊まるのか。",text:"夏の2か月、クルーはどこに船を置いていくのか。冬はどこで過ごすのか。船の滞在候補は、船が実際にどこに、どれくらい滞在するかを示します。数千の実際の船の動きから生まれた集合知です。数日から6か月以上まで、港や錨泊地での滞在をシーズンごとに表示します。",points:["滞在期間で絞り込み","その場所に船が滞在する月がわかる","人気の越冬港を見つける"],image:"stay-detail",alt:"プレヴェザ：一般的な滞在期間と、船が滞在する月。",coords:"38°57′N · 020°45′E",caption:"プレヴェザ、滞在期間とシーズン"},{id:"hotspots",number:"06",kicker:"ホットスポット",title:"静かな錨地を見つけよう。",text:"8月、ボートが混み合うのはどこで、まだ空いているのはどこか。ホットスポットは、各セーリングエリアの混み具合を月ごとに示します。イオニア海とサロニコス湾が明るく光る一方、アテネから1日の航程にあるアンドロス島は静かなままです。",points:["静かな場所から混雑した場所まで","1年のすべての月","どの地点でも最も混む月と空いている月"],image:"hotspots",alt:"8月のギリシャのセーリングエリアの混み具合：イオニア諸島周辺とサロニコス湾は混雑、アンドロス島沖は静か。地点インスペクターを表示中。",coords:"38°24′N · 023°36′E",caption:"ホットスポット、ギリシャ、8月"},{id:"spot",number:"07",kicker:"スポット情報",title:"ひとつの場所のすべてを、1枚のカードに。",text:"地図上の好きな場所を長押しするか右クリックすると、スポット情報が選んだ月のすべてをまとめて表示します。風と海況、雷雨、地形による遮蔽の度合い、そして近くの船の滞在とルート。9月のパクソス島ガイオスでは、ほとんどの時間が静穏か弱い風、海は穏やか～やや波あり、雷雨はおよそ6日に1日です。月ごとのバーを見ると、雷雨が最も多いのは11月だとわかります。",points:["ひとつの場所と月の風、海況、雷雨","5海里以内の船の滞在とルート","すべての月の評価をひと目で。クルーへのリンクとしても"],image:"spot",alt:"9月のパクソス島ガイオスのスポット情報：風と海況、雷雨、地形による遮蔽、近くの船の滞在とルート、そしてひと目でわかる各月の評価。",coords:"",caption:"ガイオス、パクソス島、9月",card:!0},{id:"wind",number:"08",kicker:"風",title:"北風はどれくらい吹くのか。",text:"風向と月を選ぶと、7月のエーゲ海中央部が濃い青に染まります。これがメルテミです。ミコノス島付近の地点をタップすると、7月の全時間の60％以上で北から吹いていることがわかります。",points:["毎月の風の強さと風向","時間帯別の風","地点をタップして数値を確認"],image:"wind",alt:"7月のエーゲ海で北風が吹く頻度。ミコノス島付近で地点の詳細を開いた画面。",coords:"37°36′N · 025°00′E",caption:"北からの風、エーゲ海、7月"},{id:"waves",number:"09",kicker:"波",title:"出航前に海況を知る。",text:"波高2.5 m以上の日は月に何日あるのか。1月には、ミストラルがリオン湾の沖までどこまで届くかがはっきり見えます。",points:["穏やかな海から非常に荒れた海まで","うねりと短く急な波","1年のすべての月"],image:"waves",alt:"1月の西地中海で海が荒れた日。",coords:"41°00′N · 005°00′E",caption:"荒れた日、西地中海、1月"},{id:"risk",number:"10",kicker:"雷雨リスク",title:"雷雨が少ないのは、どちらの港か。",text:"雷雨リスクは、雷雨がどれくらいの頻度で起きるか、どれほど激しいか、そして山や岬、外洋がそれをどう左右するかをまとめたものです。毎月、ひとつひとつの湾の単位まで表示します。ある場所をタップしてから別の場所をタップすると、2か所目のリスクがどれだけ高いか低いかがわかります。プレヴェザとメソロンギはどちらも越冬地として人気ですが、11月のメソロンギは雷雨リスクが27％低くなっています。",points:["雷雨日数、落雷密度、地形をひとつの値に","ひとつひとつの湾まで違いがわかる","2か所をタップして比較"],image:"risk",alt:"11月のイオニア海における雷雨リスク。先にプレヴェザ、次にメソロンギをタップすると、地点情報にリスクが27％低いと表示される。",coords:"38°40′N · 021°10′E",caption:"プレヴェザとメソロンギ、11月",markers:[{x:34.09,y:27.12,text:"最初にタップしたプレヴェザ：11月のリスク値は50。",color:"#7b2a83"},{x:58.05,y:72.78,text:"47海里離れたメソロンギ：雷雨リスクが27％低い。",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"雷のデータ",title:"どれくらい頻繁に、どれほど激しく、どれほど起こりやすく。",text:"リスクの裏には3つのレイヤーがあり、それぞれ単独でも開けます。どの月も同じスケールです。9月の地中海を見ると、3つすべてが必要な理由がわかります。雷雨が最も多いのはアドリア海とイオニア海の沿岸、落雷が最も密集するのはイタリアとギリシャの間の海上、そして雷雨が起きやすい条件ははるか南まで広がっています。",points:["雷雨日数：雷雨が起きる頻度（2013〜2025年）","落雷密度：雷雨の激しさ","雷雨の発生ポテンシャル：雷雨が発達しうる場所（1994〜2023年）"],image:"days",alt:"9月の地中海における雷雨日数。",coords:"40°00′N · 015°00′E",caption:"雷雨日数、地中海、9月",panels:[{label:"雷雨日数",image:"days",alt:"9月の地中海における雷雨日数。",caption:"雷雨日数、地中海、9月"},{label:"落雷密度",image:"density",alt:"9月の地中海における落雷密度。",caption:"落雷密度、地中海、9月"},{label:"雷雨の発生ポテンシャル",image:"potential",alt:"9月の地中海における雷雨の発生ポテンシャル。",caption:"雷雨の発生ポテンシャル、地中海、9月"}]},{id:"terrain",number:"12",kicker:"地形による曝露度",title:"同じ湾でも、守られ方は違う。",text:"どの湾にするかは雷雨リスクが、湾のどちら側にするかは地形による曝露度が教えてくれます。周囲の丘が錨泊地を雷から守ってくれることがあり、このレイヤーは湾のそれぞれの場所が地形にどれだけ守られているかを示します。錨を下ろす前に、より良い場所を選べます。",points:["ひとつの湾の中で場所を比較","30 m解像度の詳細な標高データ"],image:"terrain",alt:"クロアチア、ヴィス島のコミジャ湾における地形による曝露度。",coords:"43°02′N · 016°05′E",caption:"ヴィス島、コミジャ湾",markers:[{x:56.9,y:57.69,text:"周辺地形による遮蔽が少ない場所。",color:"#762a83"},{x:53.84,y:26.35,text:"周辺地形による遮蔽がある程度ある場所。",color:"#ecd27a"},{x:35.86,y:27.83,text:"周辺地形による遮蔽がより大きい場所。",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"海底",title:"砂か、海草か？",text:"錨を下ろす前に：「海底」レイヤーは、地中海から熱帯まで、沿岸の砂・泥・岩・海草・サンゴを表示します。パルマ湾では岸沿いに幅広い海草帯が続き、砂地はもっと沖にあります。ポシドニアの上での錨泊を禁止する場所は増えているので、到着前に知っておくと安心です。",points:["砂・泥・岩・海草・サンゴ","ヨーロッパと熱帯の浅い沿岸","誰でも利用可能"],image:"seabed",alt:"マヨルカ島パルマ湾の海底：岸沿いに幅広い海草帯、沖側は砂地。ポイントインスペクターが海草を表示しています。",coords:"39°30′N · 002°37′E",caption:"海底、パルマ湾"}],story:{kicker:"私たちのストーリー",title:"ひやりとした瞬間から生まれました。",text:"2024年10月、家族でイオニア海を航海していたとき、すぐそばに雷が落ちました。そのとき浮かんだのは、ひとつの素朴な疑問です。ここにいる方が安全なのか、それとも湾の反対側の方がいいのか。IncusGrid はその答えとして始まり、あのシーズンの前に知っておきたかったことすべてを載せた地図へと育ちました。",more:"ストーリーを読む（英語）",link:`${e}/blog/introducing-incusgrid/`,place:"ギリシャ、イグメニツァ",note:"アイデアが生まれた場所"},fromBlog:{kicker:"ブログから",title:"海のデータストーリー。",all:"すべての記事",note:"記事は英語です。"},devices:{kicker:"Web & Android",title:"デッキでも、チャートテーブルでも。",text:"IncusGrid はどのブラウザでも使え、Android アプリも用意しています。航行エリアを検索して、スマートフォン、タブレット、ノートパソコンで探索しましょう。",points:["ブラウザならインストール不要","Google Play で Android アプリを提供","19言語に対応"],web:"ブラウザで開く",android:"Google Play で手に入れよう",phoneAlt:"イオニア諸島周辺の船の滞在候補を表示した IncusGrid の Android アプリ。"},final:{title:"次のシーズンを計画しよう。次の航海も。",text:"長年の実データから作ったルート、船の滞在候補、風、波、雷に、10日間予報と航海プランナー。すべてをひとつの地図に。",cta:"地図を開く"},disclaimerLabel:"ご注意",disclaimer:"IncusGrid は計画のためのもので、航海計器ではありません。ルートは模式的に描かれており、船の滞在候補は船の位置報告の中断から推定したもので、確認済みの係留場所ではありません。航海プランナーは簡易的なポーラーを使い、潮流や波が艇速に与える影響は考慮せず、港の中まではルートを引きません。出航前には必ず最新の予報、公式の海図、現地の状況を確認してください。",footer:{blog:"ブログ",legal:"運営者情報",privacy:"プライバシーポリシー",terms:"利用規約",cookies:"Cookie 設定",support:"サポート",madeWith:"ポルトガルより",made:"を込めて",englishOnly:"法的ページは英語のみです。"}},x={path:"/ar",htmlLang:"ar",ogLocale:"ar_AR",meta:{title:"IncusGrid · المعرفة المحلية والتوجيه حسب الطقس للبحّارة",description:"مسارات إبحار وتوقفات قوارب مستمدة من رحلات حقيقية، وسنوات من بيانات الرياح والأمواج والبرق، إلى جانب توقعات الأيام العشرة القادمة والتوجيه حسب الطقس لقاربك. خطّط لموسمك ولعبورك على خريطة واحدة.",keywords:"التوجيه حسب الطقس، توجيه الإبحار، تخطيط العبور، تخطيط المسار، تخطيط موعد الإبحار، توقعات الإبحار، توقعات الرياح، منحنى الأداء القطبي للقارب، مسارات الإبحار، الإبحار الشراعي، رحلات اليخوت، تخطيط رحلة بحرية، مرسى، مارينا، إحصاءات الرياح، حالة البحر، الأمواج، البرق، العواصف الرعدية، خطر العواصف الرعدية، كثافة البرق، يخت، قارب شراعي، البحر المتوسط، قاع البحر، الأعشاب البحرية، بوسيدونيا، قاع الرسو"},nav:{routes:"المسارات",passages:"تخطيط الرحلة",stays:"توقفات القوارب",weather:"الطقس",thunderstorms:"البرق",blog:"المدونة",openApp:"افتح الخريطة"},hero:{position:"Sailing intelligence",lead:"يحوّل IncusGrid سنوات من البيانات إلى المعرفة المحلية التي يحتاجها كل طاقم قبل الإبحار: تحركات حقيقية للقوارب، والرياح والأمواج والبرق على خريطة واحدة. وإلى جانب ذلك، توقعات الأيام العشرة القادمة ومخطِّط عبور يوجّه قاربك عبر الرياح المتوقعة، ساعةً بساعة، مع الهبّات والأمواج على طول الطريق.",ctaApp:"افتح الخريطة",ctaAndroid:"تطبيق Android",heroAlt:"مسارات الإبحار عبر البحر الكاريبي، من هيسبانيولا إلى جزر الأنتيل الصغرى وساحل أمريكا الجنوبية، مرسومة من رحلات حقيقية لقوارب الإبحار.",heroCaption:"مسارات الإبحار، البحر الكاريبي · كل الأشهر",notes:[{label:"القوارب",value:"الآلاف"},{label:"التحركات",value:"الملايين"},{label:"ضربات البرق",value:"المليارات"},{label:"التوقعات",value:"10 أيام"},{label:"التغطية",value:"حول العالم"}]},contrast:{kicker:"الموسم والتوقعات",title:"الموسم يخبرك بأي شهر. والتوقعات تخبرك بأي يوم.",text:"أي عبور تسلكه الطواقم في يونيو؟ أين تقضي القوارب الشتاء؟ أي شهر يجلب رياح الميلتمي، وأي ميناء للتشتية يشهد عواصف رعدية أقل في نوفمبر؟ إجابات لا تظهر إلا حين تنظر إلى سنوات كثيرة دفعة واحدة. ومع اقتراب موعد إبحارك، يحسب مخطِّط العبور بناءً على توقعات الأيام العشرة متى تنطلق ومتى تصل."},chapters:[{id:"routes",number:"01",kicker:"مسارات الإبحار",title:"خطّط لعبورك بخبرة آلاف الطواقم.",text:"تُظهر آلاف الرحلات الحقيقية متى يكون العبور منطقيًا، وفي أي اتجاه، ومن أين تنطلق الطواقم وإلى أين تصل. الرياح السائدة، والأماكن المناسبة لانتظار نافذة طقس، والوصول الآمن إلى البر بعد ليلة في البحر، كلها محسوبة سلفًا. فمن صقلية إلى الجزر الأيونية مثلًا، تتجه معظم القوارب شرقًا في مايو ويونيو وتعود في سبتمبر.",points:["الشعبية حسب الشهر والاتجاه","المسارات الأكثر شعبية في عرض الخريطة الحالي","شارك مسارًا مع طاقمك"],image:"route-detail",alt:"المسار من صقلية إلى الجزر الأيونية محددًا، مع مدى شعبيته في كل شهر واتجاه.",coords:"38°12′N · 017°30′E",caption:"صقلية ← الجزر الأيونية، حسب الشهر والاتجاه"},{id:"route-wind",number:"02",kicker:"الرياح على المسار",title:"اعرف الرياح قبل أن تُبحر.",text:"يُظهر كل مسار الرياح التي يمكنك توقعها عليه، شهرًا بشهر: من أين تهب، وما قوتها، وكم من العبور تبحر فيه عكس الريح أو بريح جانبية أو مع الريح، وكم مرة يبقى البحر هادئًا. من صقلية إلى الجزر الأيونية في مايو: رياح شمالية غربية بقوة 3 بوفورت، وأكثر من نصف الطريق مع الريح.",points:["الرياح السائدة وقوتها بمقياس بوفورت لكل شهر","عكس الريح أو بريح جانبية أو مع الريح على مسار الطريق","حالة البحر على طول المسار"],image:"route-wind",alt:"بطاقة المسار من صقلية إلى الجزر الأيونية: الرياح السائدة، وقوة بوفورت، وشدة الرياح، والمسار، وحالة البحر لكل شهر، مع تحديد مايو.",coords:"",caption:"صقلية ← الجزر الأيونية، الرياح في مايو",card:!0},{id:"passage",number:"03",kicker:"مخطِّط العبور · التوجيه حسب الطقس",title:"اعرف موعد وصولك قبل أن تُبحر.",text:"حدّد نقطة الانطلاق والوجهة، واختر قاربك، فيجد مخطِّط العبور مسارًا سريعًا عبر الرياح المتوقعة للأيام العشرة القادمة، ساعةً بساعة، مع الهبّات والأمواج على طول الطريق. من ليروس إلى رودس، 86 ميلًا بحريًا، بانطلاق يوم الأربعاء الساعة 20:00: ليلة واحدة مع الريح لا تتجاوز فيها الرياح 15 عقدة، دون تشغيل المحرك، والوصول يوم الخميس قبيل الحادية عشرة.",points:["الوصول، وأقوى رياح، والهبّات والأمواج، وساعات الإبحار بالشراع وبالمحرك","لقاربك: النوع والحجم، أو منحنى الأداء القطبي الخاص بك","أثناء الإبحار: موقعك بجانب الخطة، مع إعادة حساب بقية المسار"],image:"passage",alt:"مخطِّط العبور مع المسار من ليروس إلى رودس على توقعات الرياح: نقاط المسار بأوقاتها، والقارب جنوب كوس ليلًا، وإلى جانبه موعد الوصول وأقوى رياح وساعات الإبحار بالشراع وبالمحرك.",coords:"36°48′N · 027°50′E",caption:"ليروس ← رودس، الانطلاق الأربعاء 20:00 · توقعات 31 أكتوبر"},{id:"departures",number:"04",kicker:"مقارنة مواعيد الانطلاق",title:"اليوم المناسب للإبحار.",text:"يحسب المخطِّط العبور نفسه لما يصل إلى اثني عشر موعد انطلاق، بفارق ست ساعات بين كل منها، ويضع جنبًا إلى جنب موعد الوصول والمدة وأقوى رياح ووقت الإبحار بالمحرك. إذا غادرت ليروس صباح الأربعاء وصلت إلى رودس عند منتصف الليل، وإذا غادرت مساء الأربعاء ففي صباح اليوم التالي. وتشير النجمة إلى موعد الانطلاق الذي يتطلب أقل وقت بالمحرك وعكس الريح.",points:["حتى اثني عشر موعد انطلاق، كل ست ساعات","اضغط على صف لترى مساره","احفظ العبور أو شاركه مع طاقمك، دائمًا وفق أحدث التوقعات"],image:"departures",alt:"جدول مواعيد الانطلاق من ليروس إلى رودس، كل ست ساعات بدءًا من الأربعاء 08:00: الوصول والمدة وأقوى رياح وساعات الإبحار بالمحرك، مع تمييز أفضل موعد انطلاق، الخميس الساعة 14:00، بنجمة.",coords:"",caption:"ليروس ← رودس، مواعيد الانطلاق بدءًا من الأربعاء 08:00",card:!0},{id:"stays",number:"05",kicker:"توقفات القوارب",title:"أين تبقى القوارب الأخرى.",text:"أين تترك الطواقم قواربها شهرين في الصيف، وأين تقضي الشتاء؟ تُظهر توقفات القوارب الموانئ والمراسي التي توقفت فيها القوارب — من بضعة أيام إلى أكثر من ستة أشهر، حسب الموسم.",points:["التصفية حسب مدة التوقف","اعرف في أي الأشهر تبقى القوارب في مكان ما","اكتشف الموانئ المفضلة لقضاء الشتاء"],image:"stay-detail",alt:"بريفيزا: مدة التوقف المعتادة والأشهر التي تبقى فيها القوارب هناك.",coords:"38°57′N · 020°45′E",caption:"بريفيزا، مدة التوقف والموسم"},{id:"hotspots",number:"06",kicker:"النقاط الساخنة",title:"اعثر على مرسى أهدأ.",text:"أين تزدحم القوارب في أغسطس، وأين لا يزال هناك متسع؟ تُظهر النقاط الساخنة شهرًا بشهر مدى ازدحام كل منطقة إبحار. يتوهج البحر الأيوني وخليج سارونيك، بينما تبقى أندروس، على بُعد يوم إبحار من أثينا، هادئة.",points:["من الهادئ إلى المزدحم","كل شهر من السنة","أكثر الأشهر ازدحامًا وأهدؤها في أي نقطة"],image:"hotspots",alt:"مدى ازدحام مناطق الإبحار اليونانية في أغسطس: مزدحمة حول الجزر الأيونية وفي خليج سارونيك، هادئة قبالة أندروس، مع فتح مستكشف النقطة.",coords:"38°24′N · 023°36′E",caption:"النقاط الساخنة، اليونان، أغسطس"},{id:"spot",number:"07",kicker:"بطاقة المكان",title:"كل شيء عن مكان واحد، في بطاقة واحدة.",text:"اضغط مطولًا على أي مكان في الخريطة أو انقر عليه بزر الفأرة الأيمن، فتجمع لك بطاقة المكان كل شيء للشهر الذي تختاره: الرياح وحالة البحر، والعواصف الرعدية، ومدى حماية التضاريس للمكان، وتوقفات القوارب والمسارات القريبة. غايوس في باكسوس في سبتمبر: سكون أو رياح خفيفة في معظم الوقت، وبحر هادئ إلى خفيف، وعواصف رعدية في نحو يوم من كل ستة أيام. ويُظهر شريط الأشهر أن نوفمبر هو الشهر الأكثر عواصف رعدية.",points:["الرياح وحالة البحر والعواصف الرعدية لمكان واحد وشهر واحد","توقفات القوارب والمسارات ضمن 5 أميال بحرية","تقييم كل شهر بنظرة واحدة، كرابط لطاقمك"],image:"spot",alt:"بطاقة المكان لغايوس في باكسوس في سبتمبر: الرياح وحالة البحر، والعواصف الرعدية، وحماية التضاريس، وتوقفات القوارب والمسارات القريبة، وتقييم كل شهر بنظرة واحدة.",coords:"",caption:"غايوس، باكسوس، سبتمبر",card:!0},{id:"wind",number:"08",kicker:"الرياح",title:"كم من الرياح الشمالية تتوقع؟",text:"اختر اتجاهًا وشهرًا: في يوليو يتحول وسط بحر إيجه إلى أزرق داكن. إنها رياح الميلتمي. اضغط على نقطة قرب ميكونوس لترى أنها تهب من الشمال في 60% من ساعات يوليو أو أكثر.",points:["القوة والاتجاه لكل شهر","الرياح حسب وقت اليوم","اضغط على أي نقطة لترى أرقامها"],image:"wind",alt:"كم مرة تهب الرياح من الشمال في بحر إيجه في يوليو، مع فاحص النقطة مفتوحًا قرب ميكونوس.",coords:"37°36′N · 025°00′E",caption:"رياح من الشمال، بحر إيجه، يوليو"},{id:"waves",number:"09",kicker:"الأمواج",title:"اعرف حالة البحر قبل أن تبحر.",text:"كم يومًا في الشهر تبلغ فيه الأمواج 2.5 م أو أكثر؟ في يناير يظهر بوضوح مدى امتداد رياح الميسترال عبر خليج ليون.",points:["من البحر الهادئ إلى شديد الهيجان","الأمواج المتضخمة والموج القصير الحاد","كل شهر من السنة"],image:"waves",alt:"الأيام الهائجة في غرب البحر المتوسط في يناير.",coords:"41°00′N · 005°00′E",caption:"أيام هائجة، غرب البحر المتوسط، يناير"},{id:"risk",number:"10",kicker:"خطر العواصف الرعدية",title:"أي ميناء يشهد عواصف رعدية أقل؟",text:"يجمع خطر العواصف الرعدية بين عدد مرات حدوث العواصف وشدتها وتأثير الجبال والرؤوس البحرية والبحر المفتوح فيها، لكل شهر وحتى مستوى الخلجان المنفردة. اضغط على مكان ثم على مكان آخر، لترى كم يزيد الخطر أو يقل في المكان الثاني. بريفيزا وميسولونغي كلتاهما وجهة شائعة لقضاء الشتاء: في نوفمبر يقل خطر العواصف الرعدية في ميسولونغي بنسبة 27%.",points:["أيام العواصف الرعدية وكثافة البرق والتضاريس في قيمة واحدة","فروق حتى مستوى الخلجان المنفردة","اضغط على مكانين لتقارن بينهما"],image:"risk",alt:"خطر العواصف الرعدية في البحر الأيوني في نوفمبر: الضغط على بريفيزا أولًا ثم على ميسولونغي، ويُظهر فاحص النقاط خطرًا أقل بنسبة 27%.",coords:"38°40′N · 021°10′E",caption:"بريفيزا مقابل ميسولونغي، نوفمبر",markers:[{x:34.09,y:27.12,text:"بريفيزا، الضغطة الأولى: قيمة الخطر 50 في نوفمبر.",color:"#7b2a83"},{x:58.05,y:72.78,text:"ميسولونغي، على بُعد 47 ميلًا بحريًا: خطر عواصف رعدية أقل بنسبة 27%.",color:"#d6604d"}]},{id:"lightning",number:"11",kicker:"بيانات البرق",title:"كم مرة، وبأي شدة، وما الاحتمال.",text:"وراء الخطر ثلاث طبقات يمكنك فتح كل منها على حدة، بالمقياس نفسه في كل شهر. في سبتمبر يبيّن البحر المتوسط لماذا تحتاج إليها جميعًا: العواصف الرعدية أكثر تكرارًا على سواحل البحر الأدرياتيكي والبحر الأيوني، والبرق أشد كثافة فوق البحر بين إيطاليا واليونان، والظروف المواتية للعواصف تمتد بعيدًا نحو الجنوب.",points:["أيام العواصف الرعدية: كم مرة تحدث العواصف، 2013–2025","كثافة البرق: مدى شدتها","احتمالية العواصف الرعدية: أين يمكن أن تتشكل، 1994–2023"],image:"days",alt:"أيام العواصف الرعدية في البحر المتوسط في سبتمبر.",coords:"40°00′N · 015°00′E",caption:"أيام العواصف الرعدية، البحر المتوسط، سبتمبر",panels:[{label:"أيام العواصف الرعدية",image:"days",alt:"أيام العواصف الرعدية في البحر المتوسط في سبتمبر.",caption:"أيام العواصف الرعدية، البحر المتوسط، سبتمبر"},{label:"كثافة البرق",image:"density",alt:"كثافة البرق في البحر المتوسط في سبتمبر.",caption:"كثافة البرق، البحر المتوسط، سبتمبر"},{label:"احتمالية العواصف الرعدية",image:"potential",alt:"احتمالية العواصف الرعدية في البحر المتوسط في سبتمبر.",caption:"احتمالية العواصف الرعدية، البحر المتوسط، سبتمبر"}]},{id:"terrain",number:"12",kicker:"التعرض بحسب التضاريس",title:"الخليج نفسه، وحماية مختلفة.",text:"يخبرك خطر العواصف الرعدية أي خليج تختار، ويخبرك التعرض بحسب التضاريس أي جانب منه: قد تحجب التلال المحيطة المرسى عن البرق، وتُظهر هذه الطبقة مدى حماية التضاريس لكل جزء من الخليج، لتختار الموقع الأفضل قبل أن تُلقي المرساة.",points:["قارن بين المواقع داخل خليج واحد","بيانات ارتفاع مفصّلة بدقة 30 م"],image:"terrain",alt:"التعرض بحسب التضاريس في خليج كوميجا بجزيرة فيس، كرواتيا.",coords:"43°02′N · 016°05′E",caption:"خليج كوميجا، جزيرة فيس",markers:[{x:56.9,y:57.69,text:"حجب قليل بفعل التضاريس المحيطة.",color:"#762a83"},{x:53.84,y:26.35,text:"بعض الحجب بفعل التضاريس المحيطة.",color:"#ecd27a"},{x:35.86,y:27.83,text:"حجب أكبر بفعل التضاريس المحيطة.",color:"#5aae61"}]},{id:"seabed",number:"13",kicker:"قاع البحر",title:"رمل أم أعشاب بحرية؟",text:"قبل أن تُلقي المرساة: تعرض طبقة قاع البحر الرمل والطين والصخور والأعشاب البحرية والمرجان على طول الساحل، من البحر المتوسط إلى المناطق المدارية. في خليج بالما يمتد شريط عريض من الأعشاب البحرية على طول الشاطئ، بينما يقع الرمل أبعد عنه. الرسو فوق البوسيدونيا محظور في أماكن متزايدة، لذا من المفيد أن تعرف ذلك قبل الوصول.",points:["رمل وطين وصخور وأعشاب بحرية ومرجان","أوروبا والسواحل المدارية الضحلة","متاحة للجميع"],image:"seabed",alt:"قاع البحر في خليج بالما، مايوركا: شريط عريض من الأعشاب البحرية على طول الشاطئ ورمل أبعد عنه، ومفتش النقطة يعرض أعشابًا بحرية.",coords:"39°30′N · 002°37′E",caption:"قاع البحر، خليج بالما"}],story:{kicker:"قصتنا",title:"وُلدت من لحظة خطر.",text:"في أكتوبر 2024 كانت عائلتنا تبحر في البحر الأيوني حين ضرب البرق بجوار قاربنا مباشرة. طرحت تلك اللحظة سؤالًا بسيطًا: هل نحن أكثر أمانًا هنا، أم على الجانب الآخر من الخليج؟ بدأ IncusGrid إجابةً عن هذا السؤال — ثم نما ليصبح خريطة لكل ما تمنّينا لو عرفناه قبل ذلك الموسم.",more:"اقرأ القصة كاملة (بالإنجليزية)",link:`${e}/blog/introducing-incusgrid/`,place:"إيغومينيتسا، اليونان",note:"حيث وُلدت الفكرة"},fromBlog:{kicker:"من المدونة",title:"قصص من البيانات عن البحر.",all:"كل المقالات",note:"المقالات باللغة الإنجليزية."},devices:{kicker:"الويب و Android",title:"على سطح القارب أو عند طاولة الخرائط.",text:"استخدم IncusGrid في أي متصفح أو ثبّت تطبيق Android. ابحث عن منطقة إبحارك واستكشفها على الهاتف أو الجهاز اللوحي أو الحاسوب المحمول.",points:["دون تثبيت في المتصفح","تطبيق Android على Google Play","متاح بـ 19 لغة"],web:"افتح في المتصفح",android:"نزّله من Google Play",phoneAlt:"تطبيق IncusGrid على Android يعرض توقفات القوارب حول الجزر الأيونية."},final:{title:"خطّط لموسمك القادم. ولعبورك القادم.",text:"المسارات وتوقفات القوارب والرياح والأمواج والبرق من سنوات طويلة من البيانات الحقيقية، إلى جانب توقعات الأيام العشرة ومخطِّط العبور — على خريطة واحدة.",cta:"افتح الخريطة"},disclaimerLabel:"تنبيه",disclaimer:"صُمّم IncusGrid للتخطيط، وهو ليس أداة ملاحة. المسارات مرسومة بشكل تخطيطي، وتوقفات القوارب مستنتجة من فترات انقطاع بلاغات القوارب، لا من مراسٍ مؤكدة. يستخدم مخطِّط العبور منحنى أداء قطبيًا مبسّطًا، دون احتساب التيارات أو تأثير الأمواج على سرعة القارب، ولا يوجّهك إلى داخل الميناء. تحقق دائمًا من أحدث التوقعات والخرائط البحرية الرسمية والظروف المحلية قبل الإبحار.",footer:{blog:"المدونة",legal:"الإشعار القانوني",privacy:"سياسة الخصوصية",terms:"شروط الخدمة",cookies:"إعدادات ملفات تعريف الارتباط",support:"الدعم",madeWith:"صُنع بـ",made:"في البرتغال",englishOnly:"الصفحات القانونية باللغة الإنجليزية."}},A=[{id:"en",name:"English"},{id:"de",name:"Deutsch"},{id:"fr",name:"Français"},{id:"it",name:"Italiano"},{id:"nl",name:"Nederlands"},{id:"es",name:"Español"},{id:"sv",name:"Svenska"},{id:"da",name:"Dansk"},{id:"nb",name:"Norsk (bokmål)"},{id:"fi",name:"Suomi"},{id:"el",name:"Ελληνικά"},{id:"hr",name:"Hrvatski"},{id:"tr",name:"Türkçe"},{id:"pt-BR",name:"Português (Brasil)"},{id:"ru",name:"Русский"},{id:"zh-Hans",name:"简体中文"},{id:"hi",name:"हिन्दी"},{id:"ja",name:"日本語"},{id:"ar",name:"العربية"}],I={en:o,de:s,fr:l,it:d,nl:u,es:m,sv:p,da:g,nb:c,fi:k,el:v,hr:h,tr:b,"pt-BR":y,ru:f,"zh-Hans":j,hi:z,ja:w,ar:x},D=a=>a==="en"?"/":"/"+a.toLowerCase();function L(a){var t,i;const n=(t=a.split("/")[1])==null?void 0:t.toLowerCase();return((i=A.find(r=>r.id!=="en"&&r.id.toLowerCase()===n))==null?void 0:i.id)??"en"}export{S as A,e as B,E as F,M as I,P,G as S,L as a,I as c,A as l,D as p};
